const TILE = 16;

// ── PALETTE ── canvas/JS mirror of the CSS design tokens (see the :root block
// at the top of the <style>). It reads the LIVE token values off :root, so
// canvas UI colors are the single source of truth as the DOM palette — change a
// token once and both the DOM and the canvas follow. Use these for UI-semantic
// canvas colors (bars, gold, xp, loot-tier tints, HUD text); genuinely bespoke
// pixel-art / particle / procedural-terrain colors stay as art, not tokens.
const PALETTE = (() => {
  const cs = getComputedStyle(document.documentElement);
  const t = n => cs.getPropertyValue('--' + n).trim() || '#000';
  return {
    bg: t('bg'), panel: t('panel'), border: t('border'), frame: t('frame'),
    text: t('text'), textMuted: t('text-muted'), gold: t('gold'), xp: t('xp'),
    hp: t('hp'), mp: t('mp'), danger: t('danger'), success: t('success'),
    warn: t('warn'), info: t('info'), interactive: t('interactive'),
    ink: t('ink'), paper: t('paper'),
    junk: t('junk'), normal: t('normal'), uncommon: t('uncommon'),
    rare: t('rare'), epic: t('epic'), legendary: t('legendary'), unique: t('unique'),
  };
})();

// Map dimensions in tiles. No longer fixed: floors grow with difficulty (see
// mapSizeFor) so harder tiers and deeper Endless floors are physically larger
// maps. generateMap() sets these per floor; buildTown() resets them to the base
// size (the town's building layout is hand-placed for a 20×20 plaza). BASE_* is
// the Normal / town size and the baseline for the area-ratio density scaling.
const BASE_MAP_W = 20, BASE_MAP_H = 20;
let MAP_W = BASE_MAP_W, MAP_H = BASE_MAP_H;

// Each equipment slot, with the base item names that roll for it.
