  burn:   'grayscale(1) sepia(1) saturate(9) hue-rotate(-30deg) brightness(1.2)',
  poison: 'grayscale(1) sepia(1) saturate(6) hue-rotate(60deg) brightness(1.05)',
  vuln:   'grayscale(1) sepia(1) saturate(6) hue-rotate(220deg) brightness(0.92)',
  stun:   'grayscale(1) sepia(1) saturate(7) hue-rotate(-15deg) brightness(1.25)',
  chill:  'grayscale(1) sepia(1) saturate(6) hue-rotate(160deg) brightness(1.15)',
  static: 'brightness(1.35) saturate(1.5)',
