// Friendly labels for every buff effect a topping or bowl can grant.
const FOOD_FX_LABELS = {
  dmgPct:   v => `+${Math.round(v * 100)}% Damage`,
  maxHpPct: v => `+${Math.round(v * 100)}% Max HP`,
  maxMpPct: v => `+${Math.round(v * 100)}% Max MP`,
  defFlat:  v => `+${abbreviateNumber(v)} Defense`,
  critPct:  v => `+${Math.round(v * 100)}% Crit`,
  dodgePct: v => `+${Math.round(v * 100)}% Dodge`,
  regen:    v => `+${abbreviateNumber(v)} HP Regen`,
  goldPct:  v => `+${Math.round(v * 100)}% Gold Find`,
  magicPct: v => `+${Math.round(v * 100)}% Magic Find`,
  // special secret-recipe effects
  lifesteal:v => `${Math.round(v * 100)}% Lifesteal`,
  thorns:   v => `Reflect ${abbreviateNumber(v)} dmg`,
  xpPct:    v => `+${Math.round(v * 100)}% XP`,
  dropPct:  v => `+${Math.round(v * 100)}% Extra Loot`,
  revive:   v => `Cheat death (once)`,
};
function fxDesc(fx) {
  return Object.entries(fx || {})
    .filter(([k, v]) => FOOD_FX_LABELS[k] && v)
    .map(([k, v]) => FOOD_FX_LABELS[k](v))
    .join(', ');
}
function round3(x) { return Math.round(x * 1000) / 1000; }

// ── cooking state & helpers ──
let cookPot = {};        // the ramen pot being built: ingredientKey -> count

function gainIngredient(k, n) {
  if (!player.ingredients) player.ingredients = {};
  player.ingredients[k] = (player.ingredients[k] || 0) + n;
}
function ingCount(k) { return (player.ingredients && player.ingredients[k]) || 0; }
function recipeById(id) { return RECIPES.find(r => r.id === id); }
function isDiscovered(id) { return (player.discoveredRecipes || []).includes(id); }
function haveIngredientsFor(r) { return Object.entries(r.ing).every(([k, n]) => ingCount(k) >= n); }
// Does an exact topping multiset match a secret recipe? Returns the recipe or null.
function matchRecipe(pot) {
  const keys = Object.keys(pot).filter(k => pot[k] > 0);
  return RECIPES.find(r => {
    const rk = Object.keys(r.ing);
    return rk.length === keys.length && rk.every(k => r.ing[k] === pot[k]);
  }) || null;
}
// Build the finished-bowl description from a pot: summed topping buffs, plus any
// secret-recipe bonus, with name/duration. Every bowl is ramen, so the art is
// always the ramen-bowl tile (no per-bowl emoji).
function bowlFromPot(pot) {
  const fx = {};
  for (const [k, c] of Object.entries(pot)) {
    if (!c || !INGREDIENTS[k]) continue;
    for (const [stat, v] of Object.entries(INGREDIENTS[k].fx)) fx[stat] = round3((fx[stat] || 0) + v * c);
  }
  const r = matchRecipe(pot);
  let name = 'Bowl of Ramen', floors = RAMEN_BASE_FLOORS, recipe = null;
  if (r) {
    for (const [stat, v] of Object.entries(r.bonus)) fx[stat] = round3((fx[stat] || 0) + v);
    name = r.name; floors = RAMEN_BASE_FLOORS + (r.bonusFloors || 0); recipe = r.id;
  }
  return { fx, name, floors, recipe, match: r };
}
// Active food-buff effect value for a stat key (0 when no/expired buff).
function foodFx(key) {
  const b = player.foodBuff;
  if (!b || !(b.floors > 0) || !b.fx) return 0;
  return b.fx[key] || 0;
}
// Active HEALER-buff effect value for a stat key: summed across the Rested bonus and
// any purchased Blessing (0 when none). Uses the SAME fx keys as food, so a healer
// buff folds into combat wherever foodFx already does — see the `+ healerFx(...)`
// terms alongside the foodFx terms in the derived-stat / loot formulas. Deliberately
// read live (not through the loadout cache), like foodFx, since buffs lapse per floor.
function healerFx(key) { return healerBuffFx(player.healerBuffs, key); }

