const CLASS_DMG_DEALT = { warrior: 1.10, rogue: 1.12, mage: 1.00, templar: 1.00, fortune: 1.08, windblade: 1.12, bloodletter: 1.15 };
const CLASS_DMG_TAKEN = { warrior: 0.90, rogue: 0.95, mage: 0.90, templar: 0.85, fortune: 1.00, windblade: 0.95, bloodletter: 0.92 };
