function classHpMult()             { return player.class === 'templar' ? 1.20 : player.class === 'bloodletter' ? 1.10 : 1; } // Templar +20%, Bloodletter +10% max HP
function classInnateRegen()        { return player.class === 'templar' ? 2 : 0; }                     // Templar: +2 HP regen/beat
function classSpellBonusFrac()     { return player.class === 'mage' ? 0.15 : player.class === 'windblade' ? 0.08 : 0; } // Mage +15%, Windblade +8% spell power
function classInnateCritRating()   { return player.class === 'rogue' ? 12 + player.level * 1.2 : player.class === 'fortune' ? 10 + player.level * 1.1 : 0; } // Rogue / Fortune-Seeker: level-scaled crit
