// fade to nothing as the health pool grows. `mpCost` is the skill's ordinary mana
// price AFTER Mana Cost Reduction, so MCR gear discounts blood the same as mana.
// (The Blood Pact keystone keeps charging the flat cost, so nothing about existing
// Rogue/Mage/Templar blood-casters changes.)
function skillLifeCost(mpCost) {
  return castLifeCost(player.maxHp, mpCost, keystoneFlag('bloodprice'));   // Blood Price keystone: double the toll
}
// The BLOOD a cast charges, or 0 for a hero who pays in mana. `baseMp` is the base
// (pre-MCR) cost — the discount is applied here so callers only ever hold one number.
function skillBloodCost(baseMp) {
  if (!paysSkillsInLife()) return 0;
  const cost = skillCastCost(baseMp);
  if (!cost) return 0;
  return classNoMana() ? skillLifeCost(cost) : cost;
}
// Can the hero currently AFFORD this skill's cost? Mana casts check the mana pool;
// life casts (a no-mana class, or the Blood Pact keystone) check that spending the
// health toll would leave them alive. One predicate so the skill bar, the tooltips
// and the gameState() snapshot never disagree with castSkillById. `baseMp` is the
// skill's BASE cost — MCR is applied inside, so callers pass sk.mp directly.
function canAffordSkill(baseMp) {
  return canAffordCast({ hp: player.hp, mp: player.mp, cost: skillCastCost(baseMp), life: skillBloodCost(baseMp) });
}
// The price to PRINT for a skill — "18 HP" for a blood-caster, "31 MP" otherwise —
// so a tooltip never quotes a number the cast doesn't charge.
function skillCostText(baseMp) { return castCostLabel(skillCastCost(baseMp), skillBloodCost(baseMp)); }
// Hemorrhage keystone: the health a cast just cost erupts outward as damage around
// the hero, so the class's own price becomes its area clear.
const HEMORRHAGE_RADIUS = 2, HEMORRHAGE_COEF = 1.6;
function hemorrhageBurst(spent) {
  const dmg = Math.max(1, Math.round(spent * HEMORRHAGE_COEF));
  for (const e of enemiesNear(HEMORRHAGE_RADIUS)) if (!e.dead) dealDamage(e, dmg, false);
}

// ── SKILL TREES (v4) ──
// Each class has a separate PASSIVE tree and ACTIVE tree, 30 nodes each, laid out
// in 6 bands (rows) of 5. Every node maxes at rank 10. The PASSIVE trees are now a
// branching DAG, not straight ladders: nodes link via `req` (ALL prereqs) and
// `reqAny` (any-of merges), and many carry a CONDITIONAL bonus — `cfx` that only
// applies while its `cond` is true (e.g. "+damage with a two-handed weapon", "+block
// with a shield"). A few are build-defining keystones that flip a `flag`/`unlock`
// (Titan's Grip → off-hand with a 2H weapon, Dual Mastery → off-hand swing, Aegis →
// raise the block cap) or pair power with a real cost (negative fx). See skillBonus
// (folds cfx), condMet (evaluates conds), skillFlag, and pointsInTree (pts gates).
// Ascending (see ASCENSIONS) unlocks a focused specialization "PATH" tree.
// The skill-point economy — SKILL_POINTS_PER_LEVEL / SKILL_POINTS_AT_START /
// ASCEND_LEVEL / ASC_POINT_EVERY and the earnedSkillPoints / earnedAscPoints
// helpers — lives in systems/skillMath.js (imported above) so it stays pure and
// unit-tested. Two independent pools: NORMAL skill points (one per level) fund
// the passive + active trees; ASCENDANCY points (one every ASC_POINT_EVERY
// levels from ASCEND_LEVEL) fund only the ascendancy path tree.
// band index → minimum hero level for base trees. (Ascension PATH nodes are no
// longer level-gated — they're gated purely by the earlier skills in their tree
// — so ASC_BANDS survives only as a cosmetic default and is never checked.)
const SKILL_BANDS = [1, 4, 8, 13, 19, 26];
const ASC_BANDS   = [20, 25, 31];

// Build a tree from rows of node literals: assigns band/col/type/max/lvl and a
// default prerequisite (the node directly above in the previous row) unless the
// node already declares `req`. Ascension nodes (asc set) use ASC_BANDS for level.
// Tier → minimum hero level for a WEB-laid-out tree (band index 0..n). Webs use
// fewer, deeper tiers than the old 6-band grid.
const WEB_BANDS = [1, 4, 9, 16, 24, 30];
// Build a free-form WEB tree: a flat list of nodes that each carry their own
// position (x,y in 0..1) and explicit req/reqAny edges, so a class path can branch
// and re-converge into a web instead of a straight column. `band` is kept only to
// gate by level (via WEB_BANDS); positions come from x/y, not a grid.
function buildWeb(nodes, kind, ascId) {
  for (const n of nodes) {
    n.type = n.t || kind; delete n.t;
    n.max = n.keystone ? 1 : (n.max || 10);
    if (ascId) n.asc = ascId;
    n.lvl = n.lvl != null ? n.lvl : (WEB_BANDS[Math.min(n.band || 0, WEB_BANDS.length - 1)] || 1);
    if (n.col == null) n.col = 0;
  }
  return nodes;
}
function buildTree(rows, kind, ascId) {
  const out = [];
  rows.forEach((row, b) => {
    row.forEach((n, c) => {
      n.band = b; n.col = c;
      n.type = n.t || kind; delete n.t;
      // Keystones are single-rank build-definers; everything else ranks to 10.
      n.max = n.keystone ? 1 : (n.max || 10);
      if (ascId) n.asc = ascId;
      n.lvl = (ascId ? ASC_BANDS : SKILL_BANDS)[b];
      // Auto-link a node to the one directly above it ONLY when it declares no
      // explicit prerequisite of its own. A DAG node uses `req` (AND of all) and/or
      // `reqAny` (OR of any), and a `root:true` node opens with no prereq at all —
      // that's what turns the old straight ladders into a branching web.
      if (!n.req && !n.reqAny && !n.root && b > 0) {
        const prev = rows[b - 1];
        const parent = prev[Math.min(c, prev.length - 1)];
        n.req = [parent.id];
      }
      out.push(n);
    });
  });
  return out;
}

