// Off by default; the choice is saved across sessions.
const HERO_BARS_KEY = 'dungeonLoot_heroBars';
let showHeroBars = false;
try { if (localStorage.getItem(HERO_BARS_KEY) === '1') showHeroBars = true; } catch (e) {}
// Optional red targeting crosshair drawn over the foe the hero's auto-attack is
// currently locked onto (see autoAttackTarget / the draw loop). On by default;
// the choice is saved across sessions.
const CROSSHAIR_KEY = 'dungeonLoot_crosshair';
