// choice is saved across sessions.
const STAIRS_ARROW_KEY = 'dungeonLoot_stairsArrow';
let showStairsArrow = true;
try { if (localStorage.getItem(STAIRS_ARROW_KEY) === '0') showStairsArrow = false; } catch (e) {}
// Optional small red arrows riding the map edge, one per off-screen living foe
// (see drawMonsterArrows) — the danger-coloured cousin of the stairs arrow, for
// tracking down the last stragglers sealing the floor. On by default; saved.
const MONSTER_ARROWS_KEY = 'dungeonLoot_monsterArrows';
let showMonsterArrows = true;
try { if (localStorage.getItem(MONSTER_ARROWS_KEY) === '0') showMonsterArrows = false; } catch (e) {}
// Optional camera shake on hits, crits, big casts and boss beats (see addShake /
// shakeOffset). On by default, but its amplitude is globally dialled down by
// SHAKE_SCALE so even the biggest beats stay gentle; toggle off for a dead-still
// view. Saved across sessions.
const SCREEN_SHAKE_KEY = 'dungeonLoot_screenShake';
let showScreenShake = true;
try { if (localStorage.getItem(SCREEN_SHAKE_KEY) === '0') showScreenShake = false; } catch (e) {}
// Optional brief full-screen colour wash on crits, low HP and big events (see
// screenFlash). On by default; its peak opacity lives in styles.css, dialled down
// from its old harsher value. Toggle off to keep the view clear. Saved.
const SCREEN_FLASH_KEY = 'dungeonLoot_screenFlash';
let showScreenFlash = true;
try { if (localStorage.getItem(SCREEN_FLASH_KEY) === '0') showScreenFlash = false; } catch (e) {}
// Cap on how many monster arrows ride the edge at once — a swarm floor keeps only
// the nearest few so the border never rings solid red (the minimap + FOES counter
// stay the complete tally).
const MONSTER_ARROW_CAP = 8;
// The foe the hero's auto-attack is currently locked onto (best in-reach target
// under the current focus mode), recomputed each frame in updatePlayerCombat via
// pickAutoTarget(). Declared here (with the other render state) so the draw loop's
// crosshair reference is initialised before the first frame runs.
let autoAttackTarget = null;
// Click-to-move (desktop): a world point (in tile units, matching player.fx/fy)
// the hero walks toward. `hold` means the button is still down, so the target
// keeps tracking the cursor and the hero only stops when you let go. A plain
// click leaves `hold` false: the hero walks to the point once and stops there.
// When the point isn't reachable in a straight line (a wall sits between), we
// plan a route around it — `path` holds the waypoints and `pathIdx` the one the
// hero is currently heading for (see updateMoveTargetPath / updatePlayer).
// `foe` (when set) makes this a CHASE: the destination glues to that foe's live
// position each frame and clears once it's in weapon reach or dies — clicking a
// foe paths you straight to it (see updatePlayer / the pointerup tap handler).
const moveTarget = { active: false, hold: false, wx: 0, wy: 0, path: null, pathIdx: 0, foe: null,
                     interactOnArrive: false,
                     _repathT: 0, _stallT: 0, _px: 0, _py: 0, _pathDX: -1, _pathDY: -1 };
const MOVE_ARRIVE = 0.18;   // tiles — how close counts as "reached the click point"
// ── TOUCH JOYSTICK ──
// On a touch device a floating on-screen stick drives the hero the same way held
// WASD does: its analog vector is injected into updatePlayer's input vector (see
// the joystickMath module for the pure math). `active` is true only once the
// thumb has dragged past the tap threshold (so a quick tap still walks/inspects
// via the normal tap path). Coordinates are client (CSS) px. `mag` (0..1) decides
// sprint — push the stick to the rim to run. Everything here is inert until the
// device reveals itself as touch (body.touch); desktop mouse input is untouched.
const JOY_RADIUS = 56;   // thumb throw distance (CSS px) for a full-magnitude push
// A quick FLICK of the stick — engage and release within this window while pushed
// past a fair magnitude — dashes in that direction. Longer holds are just walking.
const FLICK_MS = 260;
const FLICK_MAG = 0.5;
const touchStick = { pointerId: null, pending: false, active: false,
                     ox: 0, oy: 0, cx: 0, cy: 0, ix: 0, iy: 0, mag: 0 };
let _stickEngageAt = 0;      // performance.now() when the stick last engaged (flick timing)
function resetTouchStick() {
  touchStick.pointerId = null; touchStick.pending = false; touchStick.active = false;
  touchStick.ix = 0; touchStick.iy = 0; touchStick.mag = 0;
  hideJoyVisual();
}
// Touch sprint is an explicit on/off toggle (the sprint button) rather than a
// push-to-rim gesture — it just latches the same auto-sprint the keyboard uses.
function toggleTouchSprint() {
  sprintLatched = !sprintLatched;
  if (typeof sfx === 'function') sfx('click');
  if (typeof renderSkillBar === 'function') renderSkillBar();   // repaints the RUN tile's on/off state
}
