// ══════════════════════════════════════════
// AUDIO  (sound effects + background music)
// ══════════════════════════════════════════
// Everything here is synthesized live with the Web Audio API — no asset files —
// so the game stays a single self-contained, trivially shareable HTML file.
// The whole module is defensive: if audio is unavailable for any reason, the
// game keeps running silently rather than throwing.
const AUDIO_KEY = 'dungeonLootAudio';        // legacy single "all sound" switch
const AUDIO_MUSIC_KEY = 'dungeonLootMusic';
const AUDIO_SFX_KEY = 'dungeonLootSfx';
const AUDIO_MUTE_KEY = 'dungeonLootMuted';   // master mute — silences everything, per-channel mix untouched
const TOWN_AMB_KEY = 'dungeonLootTownAmb';   // town background chatter — OFF by default
const AUDIO_LEVELS = 5;                              // volume steps above off (0 = muted, 5 = full)
const SFX_BASE_GAIN = 0.4, MUSIC_BASE_GAIN = 0.28;  // full-volume bus gains
const MASTER_GAIN = 0.9;                             // normal master-bus gain (drops to 0 when muted)
// The generative soundtrack layers four voices; each gets its own fader (a level
// 0–5, full by default) so the player can mix the music to taste. Each key routes
// to a per-voice sub-bus under the music bus (see buildMusicVoiceBuses):
//   bass = the bassline · harm = chords/pads/arps · lead = the melody · perc = drums
const AUDIO_MIX_KEYS = { bass: 'dungeonLootMixBass', harm: 'dungeonLootMixHarm', lead: 'dungeonLootMixLead', perc: 'dungeonLootMixPerc' };
// Player-facing label + icon per voice for the Audio-tab faders.
const MIX_VOICES = [
  { key: 'bass', label: 'BASS' },
  { key: 'harm', label: 'CHORDS' },
  { key: 'lead', label: 'MELODY' },
  { key: 'perc', label: 'DRUMS' },
];
const audio = {
  ctx: null, master: null, musicGain: null, sfxGain: null,
  muted: false, musicLevel: AUDIO_LEVELS, sfxLevel: AUDIO_LEVELS, started: false,
  townAmbOn: false,   // town background sounds — opt-in, off by default
  // Per-voice music mix levels (0–5, full by default) and their live sub-buses.
  mix: { bass: AUDIO_LEVELS, harm: AUDIO_LEVELS, lead: AUDIO_LEVELS, perc: AUDIO_LEVELS },
  musicVoiceGain: null,
};
try { audio.townAmbOn = localStorage.getItem(TOWN_AMB_KEY) === 'on'; } catch (e) {}
try { audio.muted = localStorage.getItem(AUDIO_MUTE_KEY) === '1'; } catch (e) {}
try {
  // Music and SFX each pick a level 0–5 (0 = off). Migrate older saves: the split
  // on/off keys stored 'on'/'off'; before that a single "all sound" switch.
  const legacyOff = localStorage.getItem(AUDIO_KEY) === 'off';
  const readLevel = (raw) => {
    if (raw === null) return legacyOff ? 0 : AUDIO_LEVELS;   // fresh save → full
    if (raw === 'off') return 0;
    if (raw === 'on')  return AUDIO_LEVELS;
    const n = parseInt(raw, 10);
    return isNaN(n) ? AUDIO_LEVELS : Math.max(0, Math.min(AUDIO_LEVELS, n));
  };
  audio.musicLevel = readLevel(localStorage.getItem(AUDIO_MUSIC_KEY));
  audio.sfxLevel   = readLevel(localStorage.getItem(AUDIO_SFX_KEY));
  for (const k in AUDIO_MIX_KEYS) audio.mix[k] = readLevel(localStorage.getItem(AUDIO_MIX_KEYS[k]));
} catch (e) {}
// Bus gain for the current level (linear fraction of the full-volume gain).
function sfxBusGain()   { return SFX_BASE_GAIN   * audio.sfxLevel   / AUDIO_LEVELS; }
function musicBusGain() { return MUSIC_BASE_GAIN * audio.musicLevel / AUDIO_LEVELS; }

// ── VIEW ── how many tiles span the shorter axis of the play area. Fewer tiles
// = bigger tiles, so the game reads well at default browser zoom. This was once
// an adjustable Wide / Wider / Widest setting; it's now fixed at the most
// zoomed-in stop (Wide), which is the only view everyone wanted.
const VIEW_TILES = 13;

// Lazily create the AudioContext and the gain graph (master → sfx / music).
function audioInit() {
  if (audio.ctx) return audio.ctx;
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    audio.ctx = new AC();

    // Master bus → gentle limiter → speakers. The compressor glues the layered
    // voices together and tames peaks so nothing clips into harshness — most of
    // the difference between "cheap beep" and "polished" is this and the reverb.
    audio.master = audio.ctx.createGain();
    audio.master.gain.value = audio.muted ? 0 : MASTER_GAIN;
    const comp = audio.ctx.createDynamicsCompressor();
    comp.threshold.value = -14; comp.knee.value = 24; comp.ratio.value = 3;
    comp.attack.value = 0.003; comp.release.value = 0.25;
    audio.master.connect(comp);
    comp.connect(audio.ctx.destination);

    // A convolution reverb fed by a synthesized impulse — gives every sound a
    // sense of space/room instead of a dry, flat blip.
    audio.reverb = audio.ctx.createConvolver();
    audio.reverb.buffer = makeImpulse(audio.ctx, 1.8, 2.6);
    audio.reverb.connect(audio.master);

    // SFX bus: mostly dry with a touch of reverb.
    audio.sfxGain = audio.ctx.createGain();
    audio.sfxGain.gain.value = sfxBusGain();
    audio.sfxGain.connect(audio.master);
    const sfxVerb = audio.ctx.createGain();
    sfxVerb.gain.value = 0.12;
    audio.sfxGain.connect(sfxVerb);
    sfxVerb.connect(audio.reverb);

    // Music bus: more reverb for a lush, spacious dungeon ambience.
    audio.musicGain = audio.ctx.createGain();
    audio.musicGain.gain.value = musicBusGain();
    audio.musicGain.connect(audio.master);
    const musicVerb = audio.ctx.createGain();
    musicVerb.gain.value = 0.3;
    audio.musicGain.connect(musicVerb);
    musicVerb.connect(audio.reverb);

    // Per-voice sub-buses feed the music bus, so each layer (bass / chords / lead /
    // drums) has its own fader without disturbing the master music volume or reverb.
    buildMusicVoiceBuses();
  } catch (e) { audio.ctx = null; }
  return audio.ctx;
}

// Create the four per-voice gain sub-buses (bass/harm/lead/perc) at their saved mix
// levels, each feeding the current music bus. Rebuilt whenever the music bus is
// swapped (see resetMusicBus) so a SKIP still cuts cleanly.
function buildMusicVoiceBuses() {
  const ctx = audio.ctx;
  if (!ctx || !audio.musicGain) return;
  audio.musicVoiceGain = {};
  for (const k in AUDIO_MIX_KEYS) {
    const g = ctx.createGain();
    g.gain.value = (audio.mix[k] != null ? audio.mix[k] : AUDIO_LEVELS) / AUDIO_LEVELS;
    g.connect(audio.musicGain);
    audio.musicVoiceGain[k] = g;
  }
}
// Which per-voice sub-bus a note belongs to. Bass/lead/perc route to their own; the
// pad role (chords, arps) shares the harmony bus. Falls back to the music bus until
// the sub-buses exist.
function musicVoiceBus(role) {
  const vg = audio.musicVoiceGain;
  if (!vg) return audio.musicGain;
  if (role === 'bass') return vg.bass;
  if (role === 'lead') return vg.lead;
  if (role === 'perc') return vg.perc;
  return vg.harm;   // pad → chords / arps
}

// Build a decaying-noise impulse response for the convolution reverb above.
function makeImpulse(ctx, seconds, decay) {
  const len = Math.max(1, Math.floor(ctx.sampleRate * seconds));
  const buf = ctx.createBuffer(2, len, ctx.sampleRate);
  for (let ch = 0; ch < 2; ch++) {
    const d = buf.getChannelData(ch);
    for (let i = 0; i < len; i++) {
      d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay);
    }
  }
  return buf;
}

// Browsers block audio until a user gesture — call this from the first input to
// resume the context and kick off the looping background music.
function audioUnlock() {
  const ctx = audioInit();
  if (!ctx) return;
  if (ctx.state === 'suspended') { try { ctx.resume(); } catch (e) {} }
  if (!audio.started) { audio.started = true; startMusic(); }
}

// A rich single voice: two slightly detuned oscillators run through a lowpass
// filter with a real attack/decay envelope and a little filter movement. The
// detuning fattens it and the filter rounds off the raw-waveform "buzz" — this
// is what makes a note sound warm and produced rather than like a bare beep.
function voice(opts) {
  const ctx = audio.ctx;
  if (!ctx) return;
  const { freq, dur, when, dest = audio.sfxGain, type = 'triangle', vol = 0.4,
          detune = 7, slideTo = null, cutoff = 3000, q = 1, attack = 0.008 } = opts;
  const g = ctx.createGain();
  const f = ctx.createBiquadFilter();
  f.type = 'lowpass'; f.Q.value = q;
  f.frequency.setValueAtTime(cutoff, when);
  f.frequency.exponentialRampToValueAtTime(Math.max(180, cutoff * 0.5), when + dur);
  g.gain.setValueAtTime(0.0001, when);
  g.gain.exponentialRampToValueAtTime(vol, when + attack);
  g.gain.exponentialRampToValueAtTime(0.0001, when + dur);
  for (const dt of [-detune, detune]) {
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, when);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(1, slideTo), when + dur);
    o.detune.value = dt;
    o.connect(f);
    o.start(when); o.stop(when + dur + 0.03);
  }
  f.connect(g); g.connect(dest);
}

// A shaped blip for sound effects — a thin wrapper over the richer voice so
// every existing sfx call gets the detuned/filtered treatment for free.
function tone(freq, dur, when, type = 'square', vol = 0.5, slideTo = null) {
  voice({ freq, dur, when, dest: audio.sfxGain, type, vol, slideTo,
          detune: 7, cutoff: 3400, q: 1, attack: 0.006 });
}

// A burst of decaying noise — used for impacts, traps, and death. Now shaped by
// a filter and an envelope so it reads as a soft "whoosh"/"thud" rather than a
// harsh hiss.
function noise(dur, when, vol = 0.4, cutoff = 3800, type = 'lowpass') {
  const ctx = audio.ctx;
  if (!ctx) return;
  const n = Math.max(1, Math.floor(ctx.sampleRate * dur));
  const buf = ctx.createBuffer(1, n, ctx.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
  const src = ctx.createBufferSource(); src.buffer = buf;
  const f = ctx.createBiquadFilter(); f.type = type; f.frequency.value = cutoff; f.Q.value = 0.7;
  const g = ctx.createGain();
  g.gain.setValueAtTime(vol, when);
  g.gain.exponentialRampToValueAtTime(0.0001, when + dur);
  src.connect(f); f.connect(g); g.connect(audio.sfxGain);
  src.start(when); src.stop(when + dur);
}

// ══════════════════════════════════════════
// TOWN AMBIENCE
// ══════════════════════════════════════════
// Subtle, procedurally-synthesised life for the town: anvil clangs, chicken
// clucks, children's laughter, distant cheers and shouts, birdsong and the odd
// dog. Randomised events fire every few seconds while you're in town, routed
// (quietly) through the SFX bus so the Sound toggle mutes them too.
function ambVoice(o) { voice(Object.assign({ dest: audio.sfxGain, type: 'sine', vol: 0.06, detune: 5, cutoff: 4200, q: 0.8, attack: 0.01 }, o)); }
function ambSwell(t, dur, vol, cf) {   // a filtered noise crescendo (crowd/wind)
  const ctx = audio.ctx; if (!ctx) return;
  const n = Math.max(1, Math.floor(ctx.sampleRate * dur));
  const buf = ctx.createBuffer(1, n, ctx.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < n; i++) d[i] = Math.random() * 2 - 1;
  const src = ctx.createBufferSource(); src.buffer = buf;
  const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = cf; f.Q.value = 0.8;
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(vol, t + dur * 0.4);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(f); f.connect(g); g.connect(audio.sfxGain);
  src.start(t); src.stop(t + dur + 0.02);
}
function ambAnvil(t) {                 // ring of a smith's hammer on the anvil
  const hits = Math.random() < 0.5 ? 2 : 1;
  for (let i = 0; i < hits; i++) {
    const w = t + i * 0.24, f = 950 + Math.random() * 550;
    ambVoice({ freq: f, dur: 0.2, when: w, type: 'triangle', vol: 0.09, cutoff: 5500, q: 2, attack: 0.001, slideTo: f * 0.82 });
    ambVoice({ freq: f * 2.6, dur: 0.09, when: w, type: 'square', vol: 0.03, cutoff: 6500, q: 3, attack: 0.001 });
    noise(0.04, w, 0.04, 6500, 'highpass');
  }
}
function ambCluck(t) {                  // hen fussing — buck-buck-b'kaw
  const n = 2 + (Math.random() * 3 | 0);
  for (let i = 0; i < n; i++) { const w = t + i * 0.13, f = 340 + Math.random() * 260; ambVoice({ freq: f, dur: 0.07, when: w, type: 'square', vol: 0.045, slideTo: f * 0.68 }); }
  if (Math.random() < 0.4) { const w = t + n * 0.13, f = 620; ambVoice({ freq: f, dur: 0.22, when: w, type: 'sawtooth', vol: 0.05, slideTo: 300 }); }
}
function ambLaugh(t) {                  // a child's giggling little run of notes
  const base = 500 + Math.random() * 140, run = [0, 4, 7, 4, 9, 7];
  run.forEach((s, i) => ambVoice({ freq: base * Math.pow(2, s / 12), dur: 0.09, when: t + i * 0.105, type: 'sine', vol: 0.045 }));
}
function ambCheer(t) {                  // a distant crowd's rising cheer
  ambSwell(t, 1.3, 0.05, 720);
  ambVoice({ freq: 150, dur: 1.2, when: t, type: 'sawtooth', vol: 0.02, cutoff: 500, slideTo: 210 });
}
function ambShout(t) {                  // a faraway yell — a short vowel glide
  const f = 170 + Math.random() * 120;
  ambVoice({ freq: f, dur: 0.5, when: t, type: 'sawtooth', vol: 0.045, cutoff: 900, q: 2, slideTo: f * 1.8 });
  ambVoice({ freq: f * 1.5, dur: 0.4, when: t + 0.05, type: 'sawtooth', vol: 0.02, cutoff: 1100, q: 2, slideTo: f * 0.9 });
}
function ambBird(t) {                   // a sparrow's quick chirps
  const n = 2 + (Math.random() * 2 | 0);
  for (let i = 0; i < n; i++) { const w = t + i * 0.09, f = 2200 + Math.random() * 1300; ambVoice({ freq: f, dur: 0.05, when: w, type: 'sine', vol: 0.03, slideTo: f * 1.3 }); }
}
function ambDog(t) {                    // a distant bark or two
  const n = 1 + (Math.random() * 2 | 0);
  for (let i = 0; i < n; i++) { const w = t + i * 0.28, f = 170 + Math.random() * 60; ambVoice({ freq: f, dur: 0.12, when: w, type: 'square', vol: 0.05, cutoff: 1200, slideTo: f * 0.7 }); noise(0.05, w, 0.03, 1400); }
}
// Weighted event pool — homely sounds common, hollers rare.
const TOWN_AMBIENT = [[ambBird, 3], [ambAnvil, 3], [ambCluck, 3], [ambLaugh, 2], [ambDog, 1], [ambCheer, 1], [ambShout, 1]];
let _townAmbTimer = null;
function playTownAmbient() {
  if (!inTown || audio.sfxLevel <= 0 || !audio.townAmbOn) return;
  const ctx = audio.ctx;
  if (!ctx || ctx.state !== 'running') return;
  const total = TOWN_AMBIENT.reduce((s, e) => s + e[1], 0);
  let r = Math.random() * total, fn = TOWN_AMBIENT[0][0];
  for (const [f, w] of TOWN_AMBIENT) { if ((r -= w) < 0) { fn = f; break; } }
  try { fn(ctx.currentTime + 0.03); } catch (e) {}
}
function scheduleTownAmbient() {
  clearTimeout(_townAmbTimer);
  if (!inTown || !audio.townAmbOn) return;
  _townAmbTimer = setTimeout(() => { playTownAmbient(); scheduleTownAmbient(); }, 1400 + Math.random() * 3200);
}
function startTownAmbient() { scheduleTownAmbient(); }  // plays once audio is unlocked (any tap/keypress)
function stopTownAmbient() { clearTimeout(_townAmbTimer); _townAmbTimer = null; }
// Toggle the town background sounds on/off (persisted). Called from the town menu.
function toggleTownAmbient() {
  audio.townAmbOn = !audio.townAmbOn;
  try { localStorage.setItem(TOWN_AMB_KEY, audio.townAmbOn ? 'on' : 'off'); } catch (e) {}
  settingsChanged();
  if (audio.townAmbOn) { audioUnlock(); sfx('click'); startTownAmbient(); }
  else stopTownAmbient();
  const b = document.getElementById('town-amb-btn');
  if (b) { b.classList.toggle('on', audio.townAmbOn); b.textContent = audio.townAmbOn ? '🔔 Town sounds: On' : '🔕 Town sounds: Off'; }
}

// Named sound effects, each keyed to a game event.
function sfx(name) {
  if (audio.sfxLevel <= 0) return;
  const ctx = audioInit();
  if (!ctx || ctx.state === 'suspended') return;
  const t = ctx.currentTime;
  switch (name) {
    case 'attack':  tone(220, 0.09, t, 'square', 0.4, 140); noise(0.05, t, 0.16); break;
    case 'crit':    tone(330, 0.13, t, 'sawtooth', 0.5, 660); tone(660, 0.13, t + 0.02, 'square', 0.3); noise(0.09, t, 0.25); break;
    case 'hurt':    tone(200, 0.18, t, 'sawtooth', 0.45, 70); break;
    case 'heartbeat': { // soft, muffled low "lub-dub" under the low-HP danger halo — two quick thumps
      tone(58, 0.13, t,        'sine', 0.42, 40); // lub
      tone(52, 0.15, t + 0.15, 'sine', 0.34, 36); // dub
      break;
    }
    case 'uiclick': tone(1250, 0.022, t, 'triangle', 0.13); break; // soft, short press tick for UI chrome (clicks, not hover)
    case 'kill':    tone(160, 0.18, t, 'square', 0.4, 50); noise(0.16, t, 0.28); break;
    case 'boss':    tone(90, 0.5, t, 'sawtooth', 0.5, 40); tone(120, 0.5, t + 0.05, 'square', 0.3, 55); noise(0.3, t, 0.2); break;
    case 'loot':    [523, 659, 784].forEach((f, i) => tone(f, 0.1, t + i * 0.06, 'square', 0.4)); break;
    case 'gold':    tone(880, 0.06, t, 'square', 0.35); tone(1175, 0.07, t + 0.05, 'square', 0.3); break;
    case 'potion':  tone(440, 0.1, t, 'sine', 0.4, 880); tone(660, 0.12, t + 0.08, 'sine', 0.3, 990); break;
    case 'levelup': { // triumphant rising run that lands on a full, sparkling major chord
      [523, 659, 784, 1047].forEach((f, i) => {   // quick ascent: C E G high-C
        tone(f, 0.13, t + i * 0.07, 'square', 0.4);
        tone(f, 0.13, t + i * 0.07, 'triangle', 0.18); // soft body under each step
      });
      const land = t + 0.30;                        // the payoff chord lands here
      tone(1047, 0.6,  land,        'square',   0.42); // C
      tone(1319, 0.6,  land,        'triangle', 0.30); // E
      tone(1568, 0.6,  land,        'triangle', 0.26); // G — full major triad
      tone(2093, 0.55, land + 0.02, 'sine',     0.20); // high-C shimmer on top
      tone(131,  0.7,  land,        'sawtooth', 0.32, 65); // warm low root for weight
      noise(0.5, land, 0.16, 6500, 'highpass');        // sparkle sweep over the chord
      break;
    }
    case 'bosskill': { // grander victory fanfare — brassy two-part flourish + cymbal swell
      const fan = (f, d, w, v) => { tone(f, d, w, 'sawtooth', v * 0.5); tone(f, d, w, 'square', v * 0.4); };
      fan(392, 0.16, t,        0.5);  // G
      fan(523, 0.16, t + 0.15, 0.5);  // C
      fan(659, 0.16, t + 0.30, 0.5);  // E
      fan(784, 0.6,  t + 0.45, 0.55); // G (held, top of the run)
      fan(1047, 0.6, t + 0.45, 0.4);  // C above — victory chord
      noise(0.5, t + 0.45, 0.28, 6000, 'highpass'); // cymbal swell
      break;
    }
    // ── ACHIEVEMENT / VICTORY STINGS ── a little family of distinct, celebratory
    // cues, one per kind of accomplishment, so each win sounds like its own reward
    // (floor cleared, bounty done, points banked, ascension, deeds, feats). Kept
    // short and each in a different register/motif so they're told apart by ear. ──
    case 'floorclear': { // all foes down, the stairs unseal — a bright, quick rising flourish
      [523, 659, 784].forEach((f, i) => {   // C E G ascent
        tone(f, 0.11, t + i * 0.06, 'square', 0.34);
        tone(f, 0.11, t + i * 0.06, 'triangle', 0.16);
      });
      tone(1047, 0.34, t + 0.18, 'triangle', 0.30); // lands on high C
      tone(1568, 0.32, t + 0.20, 'sine', 0.16);      // airy fifth on top
      noise(0.28, t + 0.18, 0.12, 6800, 'highpass'); // light shimmer
      break;
    }
    case 'bounty': { // bounty complete — a proud two-note herald with a coin-bright sparkle
      const h = (f, w, v) => { tone(f, 0.16, w, 'sawtooth', v * 0.4); tone(f, 0.16, w, 'square', v * 0.26); };
      h(587, t, 0.5);          // D stab
      h(880, t + 0.14, 0.55);  // lifts to a held A
      tone(1319, 0.34, t + 0.16, 'sine', 0.18);  // bright third shimmer
      tone(1760, 0.1,  t + 0.16, 'square', 0.16); // coin glint
      tone(2093, 0.12, t + 0.24, 'square', 0.14);
      noise(0.2, t + 0.14, 0.12, 6500, 'highpass');
      break;
    }
    case 'ascpoint': { // an ascendancy point banked — an ethereal, ascending crystalline shimmer
      [784, 988, 1319, 1568].forEach((f, i) => tone(f, 0.2, t + i * 0.05, 'sine', 0.2)); // rising G B E G bells
      tone(2093, 0.5, t + 0.22, 'sine', 0.16);       // sustained high sparkle
      tone(196,  0.5, t,        'sine', 0.22, 392);  // soft rising sub for lift
      noise(0.4, t + 0.05, 0.12, 7200, 'highpass');  // airy sweep
      break;
    }
    case 'ascend': { // ascension into a class path — a grand, radiant rising chord that blooms open
      [392, 523, 659].forEach((f, i) => { tone(f, 0.16, t + i * 0.08, 'sawtooth', 0.34); tone(f, 0.16, t + i * 0.08, 'triangle', 0.2); }); // G C E rise
      const land = t + 0.30;
      tone(784,  0.7,  land,        'triangle', 0.34); // G
      tone(988,  0.7,  land,        'triangle', 0.28); // B
      tone(1175, 0.7,  land,        'sine',     0.24); // D — bright major bloom
      tone(1568, 0.65, land + 0.04, 'sine',     0.18);
      tone(98,   0.8,  land,        'sawtooth', 0.34, 49); // deep radiant root
      noise(0.6, land, 0.2, 7000, 'highpass');            // radiant sweep
      break;
    }
    case 'bosspoint': { // a Boss Point banked — a weighty low bloom into a resonant power chord
      tone(98,  0.5, t,        'sawtooth', 0.42, 49); // low root swell
      tone(196, 0.5, t + 0.02, 'square',   0.26);
      const c = t + 0.16;
      tone(392, 0.5,  c,        'sawtooth', 0.32); // G
      tone(587, 0.5,  c,        'square',   0.24); // D — open fifth
      tone(784, 0.55, c + 0.02, 'triangle', 0.24); // octave, power-chord shimmer
      noise(0.4, t, 0.18, 3200, 'lowpass');        // dark body
      noise(0.3, c, 0.12, 6000, 'highpass');       // top sparkle
      break;
    }
    case 'deed': { // a deed earned — a noble, ceremonial IV→I resolve with a bright bell
      const h = (f, w, v) => { tone(f, 0.4, w, 'sawtooth', v * 0.34); tone(f, 0.4, w, 'triangle', v * 0.26); };
      h(349, t,        0.5);  // F (IV)
      h(523, t + 0.18, 0.55); // C (I) — the resolve
      tone(1047, 0.5, t + 0.2,  'sine', 0.22); // bright bell over the cadence
      tone(1568, 0.4, t + 0.24, 'sine', 0.14);
      noise(0.35, t + 0.18, 0.12, 6200, 'highpass');
      break;
    }
    case 'achieve': { // an achievement/feat earned — a bright trophy triad landing on a sparkle
      [659, 880, 1319].forEach((f, i) => { tone(f, 0.14, t + i * 0.07, 'square', 0.3); tone(f, 0.14, t + i * 0.07, 'sine', 0.16); }); // E A high-E bells
      tone(1760, 0.4, t + 0.24, 'sine', 0.2);  // sparkling top
      tone(2637, 0.3, t + 0.26, 'sine', 0.12);
      noise(0.32, t + 0.2, 0.14, 7400, 'highpass'); // glitter
      break;
    }
    case 'stairs':  [392, 330, 262].forEach((f, i) => tone(f, 0.14, t + i * 0.08, 'triangle', 0.4)); break;
    case 'shrine':  tone(523, 0.4, t, 'sine', 0.35, 784); tone(659, 0.4, t + 0.04, 'sine', 0.25, 988); break;
    // ── LOOT REVEAL & REWARD STINGS ── escalating payoffs for rarer drops. ──
    case 'epicdrop': // a bright, shimmering triad — richer than the plain loot blip
      [659, 880, 1175].forEach((f, i) => tone(f, 0.16, t + i * 0.05, 'triangle', 0.4));
      noise(0.3, t + 0.05, 0.14, 6500, 'highpass'); break;
    case 'legendary': { // jackpot — a rising arpeggio, a shimmer sweep and a low boom
      [523, 659, 784, 1047, 1319].forEach((f, i) => { tone(f, 0.22, t + i * 0.07, 'square', 0.4); tone(f * 2, 0.22, t + i * 0.07, 'triangle', 0.18); });
      tone(1568, 0.7, t + 0.4, 'triangle', 0.32); tone(2093, 0.7, t + 0.42, 'sine', 0.2);
      tone(70, 0.8, t + 0.36, 'sawtooth', 0.5, 34);            // deep boom under it
      noise(0.7, t + 0.36, 0.3, 7000, 'highpass'); break;      // sparkle sweep
    }
    case 'milestone': { // deep-dive fanfare — a proud two-note horn stab + swell
      const h = (f, w, v) => { tone(f, 0.5, w, 'sawtooth', v * 0.45); tone(f, 0.5, w, 'square', v * 0.35); };
      h(392, t, 0.5); h(587, t + 0.16, 0.5); h(784, t + 0.34, 0.55);
      noise(0.5, t + 0.34, 0.22, 5000, 'highpass'); break;
    }
    case 'rampage': // combo tier up — a short rising battle-stab
      tone(300, 0.12, t, 'sawtooth', 0.4, 620); tone(600, 0.12, t + 0.03, 'square', 0.28, 900);
      noise(0.1, t, 0.2); break;
    case 'critbig': // an emphatic crit — the crit sound with more body & a sub thump
      tone(330, 0.16, t, 'sawtooth', 0.55, 780); tone(660, 0.16, t + 0.02, 'square', 0.34);
      tone(90, 0.2, t, 'sawtooth', 0.4, 50); noise(0.12, t, 0.3); break;
    case 'crunch': // meaty elite/boss finisher — a low crushing impact
      tone(70, 0.28, t, 'sawtooth', 0.6, 30); tone(120, 0.24, t + 0.02, 'square', 0.4, 44);
      noise(0.24, t, 0.5, 2400, 'lowpass'); noise(0.12, t, 0.4); break;
    case 'equip':   tone(330, 0.05, t, 'square', 0.3); tone(494, 0.07, t + 0.04, 'square', 0.3); break;
    case 'buy':     tone(659, 0.07, t, 'square', 0.35); tone(988, 0.09, t + 0.06, 'square', 0.3); break;
    case 'sell':    tone(494, 0.07, t, 'square', 0.35); tone(740, 0.08, t + 0.05, 'square', 0.3); break;
    case 'death':   tone(330, 0.6, t, 'sawtooth', 0.5, 55); noise(0.5, t, 0.25); break;
    case 'trap':    noise(0.3, t, 0.4); tone(140, 0.3, t, 'sawtooth', 0.4, 60); break;
    case 'wall-hit':   // a dull stony knock — a chip taken off a cracked wall
      tone(150, 0.07, t, 'square', 0.34, 88); noise(0.08, t, 0.3, 2600, 'lowpass'); noise(0.03, t, 0.16, 4200, 'highpass'); break;
    case 'wall-break': // the wall gives — a low crumble with tumbling rubble
      tone(78, 0.24, t, 'sawtooth', 0.5, 36); tone(128, 0.18, t + 0.02, 'square', 0.34, 52);
      noise(0.3, t, 0.46, 2200, 'lowpass'); noise(0.16, t + 0.05, 0.3); break;
    case 'click':   tone(660, 0.04, t, 'square', 0.22); break;
    case 'denied':  tone(180, 0.12, t, 'square', 0.3); tone(120, 0.16, t + 0.1, 'square', 0.28); break;
    case 'teleport': tone(880, 0.18, t, 'sine', 0.35, 220); tone(440, 0.2, t + 0.06, 'sine', 0.28, 1320); noise(0.12, t, 0.18); break;
    // ── TOWN-PORTAL TELEPORT ── a rising swell as the hero rockets away, and a
    // diving pitch that lands on a solid thump as they materialize back in.
    case 'portalout': // fade-out + beam-up: energy sweeps upward and off the map
      tone(294, 0.5, t, 'sine', 0.34, 1760); tone(588, 0.42, t + 0.05, 'triangle', 0.2, 2640);
      noise(0.55, t, 0.22, 6000, 'highpass'); break;
    case 'portalin':  // pillar-in + materialize: pitch dives in, then a low thump
      tone(1760, 0.42, t, 'sine', 0.32, 294); tone(880, 0.4, t + 0.04, 'triangle', 0.18, 220);
      noise(0.4, t, 0.2, 5200, 'highpass'); tone(120, 0.3, t + 0.24, 'sawtooth', 0.4, 60); break;
    // ── ATTACK / SPELL CASTS ── short, element-flavoured sounds for weapon swings,
    // fired shots and the per-shape/element spell casts (see castSoundFor). ──
    case 'bowshot':  // a taut string release + arrow whoosh
      tone(600, 0.06, t, 'triangle', 0.28, 240); noise(0.14, t + 0.02, 0.22, 3000, 'highpass'); break;
    case 'magicbolt': // a quick zap
      tone(880, 0.12, t, 'sine', 0.3, 320); tone(440, 0.1, t + 0.02, 'square', 0.16, 220); break;
    case 'slash':    // a blade swoosh
      noise(0.12, t, 0.3, 2600, 'bandpass'); tone(320, 0.05, t, 'triangle', 0.14, 520); break;
    case 'novacast': // an outward whoomph
      tone(140, 0.24, t, 'sine', 0.4, 60); noise(0.24, t, 0.28, 1600, 'lowpass'); break;
    case 'beamcast': // a searing lance
      tone(240, 0.34, t, 'sawtooth', 0.28, 760); noise(0.3, t, 0.18, 3200, 'bandpass'); break;
    case 'buffcast': // a warm rising shimmer
      [523, 659, 784].forEach((f, i) => tone(f, 0.16, t + i * 0.05, 'sine', 0.24)); break;
    case 'summoncast': // an otherworldly swell
      tone(196, 0.4, t, 'sawtooth', 0.28, 392); tone(294, 0.34, t + 0.05, 'triangle', 0.18, 588); noise(0.3, t, 0.14, 5000, 'highpass'); break;
    case 'castfire': // a fwoosh
      tone(180, 0.22, t, 'sawtooth', 0.3, 90); noise(0.2, t, 0.26, 1800, 'lowpass'); break;
    case 'castice':  // a crystalline chime
      [1568, 2093, 2637].forEach((f, i) => tone(f, 0.22, t + i * 0.03, 'sine', 0.16)); tone(200, 0.16, t, 'sine', 0.2, 120); break;
    case 'castspark': // a crackle
      noise(0.14, t, 0.3, 4200, 'highpass'); for (let i = 0; i < 3; i++) tone(1400 + i * 500, 0.04, t + i * 0.03, 'square', 0.2); break;
    case 'castarcane': // a bright arcane ping
      tone(660, 0.16, t, 'sine', 0.28, 990); tone(990, 0.14, t + 0.03, 'triangle', 0.16); break;
    case 'castholy': // a soft radiant tone
      [659, 988, 1319].forEach((f, i) => tone(f, 0.2, t + i * 0.03, 'sine', 0.2)); break;
    case 'castvenom': // a wet, low bubble
      tone(160, 0.2, t, 'sine', 0.28, 90); noise(0.16, t, 0.16, 1200, 'lowpass'); break;
    // ── ULTIMATE CASTS ── big, cinematic capstone-spell sounds. ──
    case 'ult': // huge generic impact — a deep, room-shaking boom
      tone(70, 0.7, t, 'sawtooth', 0.6, 30); tone(110, 0.6, t + 0.04, 'square', 0.4, 45);
      noise(0.6, t, 0.45, 2600, 'lowpass'); noise(0.2, t, 0.4); break;
    case 'ult-fire': // meteor — a screaming descent into a colossal fiery blast
      tone(1300, 0.34, t, 'sawtooth', 0.26, 130);          // whistling fall
      tone(70, 0.8, t + 0.22, 'sawtooth', 0.62, 28);        // deep impact
      tone(105, 0.7, t + 0.24, 'square', 0.42, 40);
      noise(0.8, t + 0.22, 0.5, 2200, 'lowpass');           // fiery roar
      noise(0.22, t + 0.22, 0.45); break;                   // impact crack
    case 'ult-ice': // frost nova — a low boom under a crystalline shimmer
      tone(90, 0.5, t, 'sine', 0.42, 40);
      [1568, 2093, 2637, 3136].forEach((f, i) => tone(f, 0.5, t + 0.06 + i * 0.04, 'sine', 0.16));
      noise(0.45, t, 0.32, 5200, 'highpass'); break;        // frost crack
    case 'ult-lightning': // storm — a sharp crackle and rolling thunder
      noise(0.5, t, 0.5, 4200, 'highpass');
      tone(85, 0.65, t + 0.02, 'sawtooth', 0.55, 32);
      for (let i = 0; i < 5; i++) tone(1600 + Math.random() * 1800, 0.05, t + i * 0.035, 'square', 0.24); break;
    case 'ult-beam': // annihilation ray — a rising, searing hum
      tone(180, 0.5, t, 'sawtooth', 0.35, 900); tone(360, 0.5, t + 0.02, 'square', 0.22, 1400);
      noise(0.5, t, 0.3, 3000, 'bandpass'); break;
    case 'ult-holy': // radiant — a bright, ascending chord
      [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.6, t + i * 0.05, 'sine', 0.3));
      tone(1568, 0.7, t + 0.2, 'triangle', 0.2); noise(0.5, t, 0.18, 6500, 'highpass'); break;
    case 'ult-summon': // conjuration — a swelling, otherworldly rise
      tone(160, 0.6, t, 'sine', 0.34, 320); tone(240, 0.6, t + 0.05, 'triangle', 0.24, 480);
      [784, 988, 1319].forEach((f, i) => tone(f, 0.4, t + 0.25 + i * 0.05, 'sine', 0.2)); break;
  }
}

// ── Background music ──
// A *generative* minor-key dungeon theme rather than a fixed loop: it walks a
// rotating chord progression and improvises a fresh melody, arpeggio, bassline
// and light percussion bar by bar, so the music keeps evolving and never
// repeats note-for-note. Everything is scheduled a fraction of a second ahead
// of the playhead so it never glitches.
let musicTimer = null, musicStep = 0, musicNext = 0;
let musicProg = null, musicLeadIdx = 4, musicArpIdx = 0, musicBarCount = 0;
// The track drifts between distinct *styles* ("sections") over time. Each style
// has its own scale/mode, bank of chord progressions, rhythmic groove AND
// instruments — so it is genuinely different music, not just a different tempo.
// It holds one style for a couple of minutes, then slowly crossfades into the
// next: the timbres blend continuously while the harmony and groove pivot at the
// midpoint of the fade (masked by the equal blend), so the character changes
// noticeably without ever hard-cutting.
let musicSectionIdx = 0;      // style whose timbre/feel is currently playing
let musicStructIdx = 0;       // style whose scale/chords/groove drive the notes
let musicTrans = null;        // active crossfade: { fromIdx, toIdx, start, end }
let musicSectionEndTime = 0;  // ctx time at which the current section drifts on
let musicSkip = false;        // SKIP button sets this to jump to a fresh style now
// Per-performance variation: each time a style takes over the musical structure
// we re-roll a key (transposition) and a tempo multiplier, so the *same* style
// sounds genuinely different each time it comes around — a different song, not a
// replay. These are picked in rollMusicVariation() whenever the structure pivots.
let musicKeyOffset = 0;       // semitones every voice is transposed by
let musicTempoMul = 1;        // multiplies the style's base tempo (>1 = slower)
let musicRegister = 0;        // extra octave nudge on the lead (0 or ±12)
// Candidate keys to transpose into. All keep the style's mode intact (the whole
// scale shifts together); the spread is small enough to stay in a pleasant
// register. Picked per performance for harmonic variety between songs.
const MUSIC_KEYS = [-5, -3, -2, 0, 0, 2, 4, 5, 7];
function rollMusicVariation() {
  musicKeyOffset = mpick(MUSIC_KEYS);
  musicTempoMul = 0.86 + Math.random() * 0.28;        // ±~14% tempo swing
  musicRegister = mpick([0, 0, 0, 12, -12]);          // occasional octave lift/drop
}
// ── Music vibe ── the player picks any MIX of styles ("vibes") in Settings ▸ Audio
// (multi-select), or leaves every style enabled to shuffle through them all. The
// soundtrack drifts only among the selected styles; a single selection locks to it.
// Boss floors don't swap the style — they just race the current track. Saved
// globally as 'auto' (all) or a sorted comma list of style indices ('3' | '3,5,9');
// an older single-index save still parses correctly. Selection math is the pure,
// unit-tested src/systems/musicVibe.js; here we just wire it to audio + the UI.
const MUSIC_VIBE_KEY = 'musicVibe';
let musicVibe = 'auto';
try { const _mv = localStorage.getItem(MUSIC_VIBE_KEY); if (_mv) musicVibe = _mv; } catch (e) {}
// Normalise any legacy/stored value against the live style count (drops stale
// indices, collapses a full selection to 'auto'). MUSIC_SECTIONS.length is live at
// eval time; NORMAL_SECTIONS (same value) isn't defined until below.
musicVibe = serializeVibe(musicVibe, MUSIC_SECTIONS.length);
// The next style to drift/skip to, drawn from the selected pool (or every style on
// Shuffle). `avoid` is skipped when the pool leaves another choice, so a shuffle
// never repeats back-to-back; a single locked style returns itself (caller decides).
function pickNextNormalSection(avoid) {
  return pickVibeSection(musicVibe, NORMAL_SECTIONS, Math.random, avoid);
}
// Bright, upbeat styles a fresh run opens on (HAPPY_START_SECTIONS resolved to live
// indices, so a reorder of MUSIC_SECTIONS can't desync them).
const HAPPY_SECTIONS = HAPPY_START_SECTIONS
  .map(n => MUSIC_SECTIONS.findIndex(s => s.name === n))
  .filter(i => i >= 0);
// The style a NEW game starts on: a random happy track on Shuffle, else a happy one
// among the selection (falling back to any selected style).
function pickHappyStartSection() {
  return pickStartSection(musicVibe, NORMAL_SECTIONS, HAPPY_SECTIONS, Math.random);
}
// Repaint the multi-select picker chips to match the current selection.
function renderMusicVibeControls() {
  const row = document.getElementById('music-vibe-row');
  if (!row) return;
  const set = new Set(parseVibe(musicVibe, NORMAL_SECTIONS));
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
  // Shuffle-all when nothing is picked; otherwise each selected style lights up.
  let html = `<button class="dpad-cfg-btn vibe-chip vibe-all ${set.size ? '' : 'sel'}" `
    + `onclick="setMusicVibeAll()" title="Shuffle through every style">`
    + `<span class="vibe-name">Shuffle (all)</span></button>`;
  for (let i = 0; i < NORMAL_SECTIONS; i++) {
    const name = MUSIC_SECTIONS[i] ? MUSIC_SECTIONS[i].name : ('Style ' + i);
    const tag = MUSIC_VIBE_TAGS[name] || '';
    html += `<button class="dpad-cfg-btn vibe-chip ${set.has(i) ? 'sel' : ''}" `
      + `onclick="toggleMusicVibe(${i})" title="${esc(name)}${tag ? ' — ' + esc(tag) : ''}">`
      + `<span class="vibe-name">${esc(name)}</span>`
      + (tag ? `<span class="vibe-tag">${esc(tag)}</span>` : '')
      + `</button>`;
  }
  row.innerHTML = html;
}
// Persist the current selection and repaint the picker. Kept separate so both
// setters (toggle / shuffle-all) share it.
function saveMusicVibe() {
  try { localStorage.setItem(MUSIC_VIBE_KEY, musicVibe); } catch (e) {}
  settingsChanged();
  renderMusicVibeControls();
  if (typeof sfx === 'function') sfx('click');
}
