let _bountyOffers = null;
function acceptBounty(i) {
  const offers = _bountyOffers || rollBounties(); const o = offers[i]; if (!o) return;
  // Store the fully-resolved description (a delve bounty's floorTag can't take a
  // placeholder); the display sites' harmless .replace('{n}', …) still handles
  // any older save whose desc was stored with a {n} token.
  player.bounty = { kind: o.kind, need: o.need, snap: o.snap, rewards: o.rewards, desc: o.desc(o.need) };
  sfx('click');
  log(`<span data-spr=scroll></span> Bounty accepted: ${o.desc(o.need)}.`, 'important');
  renderBounty(); updateObjectiveChip(); renderSkillBar(); saveGame();
}
function claimBounty() {
  const b = player.bounty; if (!b || !bountyDone(b)) return;
  const rewards = bountyRewardList(b);
  const parts = [];             // combat-log fragments, one per reward paid
  let bannerItem = null;        // best gear piece to celebrate with the drop banner
  let gainedXp = false;
  for (const r of rewards) {
    // × the live season's bounty-payout rule (×1 when un-enrolled) — a Gilded or
    // Ironblood Cycle pays its contracts richer, which is half of what it promises.
    if (r.t === 'gold') { const got = egCyclePayout(r.amt); player.gold += got; parts.push(`+<span data-spr=ic_money></span>${fmtGold(got)}`); }
    // Curated-reward exception: a bounty pays its listed material ungated by
    // difficulty — you earned the contract, so the payout ignores the drop gate.
    else if (r.t === 'mat') { gainMaterial(r.mat, r.amt); parts.push(`+${abbreviateNumber(r.amt)}<span data-spr=mat_${r.mat}></span>`); }
    else if (r.t === 'xp') { const got = grantXp(r.amt); gainedXp = true; parts.push(`+${abbreviateNumber(got)} XP`); }
    else if (r.t === 'gear') {
      const item = generateItem(2, r.ilvl || ((player.maxFloor || 1) + 1), r.tier || null);
      inventory.push(item);
      if (!bannerItem || TIER_ORDER.indexOf(item.tier) > TIER_ORDER.indexOf(bannerItem.tier)) bannerItem = item;
      parts.push(logItem(item));
    }
  }
  player.bounty = null;
  // A legendary/unique gear payoff gets the full drop banner; lesser rewards keep
  // the gold-flash fanfare.
  if (bannerItem && isTopTierItem(bannerItem)) lootReveal(bannerItem);
  else { sfx('levelup'); screenFlash('#ffd24b'); }
  if (gainedXp) checkLevelUp();
  log(`<span data-spr=scroll></span> Bounty complete! ${parts.join(', ')}.`, 'loot');
  // renderSkillBar() clears the belt's now-stale bounty module at once — otherwise
  // its green "ready to claim" pulse would linger until the next world-tick rebuild.
  updateBars(); renderPanel(); renderBounty(); updateObjectiveChip(); renderSkillBar(); saveGame();
}
function abandonBounty() { player.bounty = null; sfx('click'); log('<span data-spr=scroll></span> Bounty abandoned.'); renderBounty(); updateObjectiveChip(); renderSkillBar(); saveGame(); }

// ── OBJECTIVE CHIP / DAILY STREAK / COMBO + GREED RESETS ─────────────────────
// The objective chip (a compact "what am I working toward" banner near the top),
// the daily-play streak it shows, and the reset helpers for the rampage meter and
// the greed gate. These drive the HTML/CSS scaffolding of those features; keeping
// them defined is also what lets the game boot (loadDaily runs during init).

// Daily-play streak — consecutive calendar days the game has been opened. Stored
// in its own localStorage key (outside the save slots) so it survives switching
// characters and starting fresh runs. Surfaced as a small badge on the chip.
let dailyStreak = 0;
const DAILY_KEY = 'dungeonLoot_daily';
function dayStamp(d) { return d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate(); }
function loadDaily() {
  try {
    const today = new Date();
    const todayStr = dayStamp(today);
    const yestStr = dayStamp(new Date(today.getTime() - 864e5));
    let rec = null;
    try { rec = JSON.parse(localStorage.getItem(DAILY_KEY) || 'null'); } catch (e) {}
    if (rec && rec.last === todayStr) dailyStreak = rec.streak || 1;          // already counted today
    else if (rec && rec.last === yestStr) dailyStreak = (rec.streak || 1) + 1; // consecutive day
    else dailyStreak = 1;                                                     // first play, or a gap reset it
    localStorage.setItem(DAILY_KEY, JSON.stringify({ last: todayStr, streak: dailyStreak }));
  } catch (e) { dailyStreak = 0; }
}

// Repaint the objective chip from the hero's active bounty. It only shows during
// active dungeon play (hidden in town, on the title screen, and while no bounty is
// taken) so it stays a quiet cue rather than clutter.
// The chip repaints on every kill (and gold gain) but its strings rarely move, so
// the last-written state is remembered and unchanged repaints skip the DOM writes.
let _objChipLast = null;
