// ── ISLAND THEMES ── occasional OUTDOOR floors that come up as a landmass ringed
// by open sea (generateMap's moat pass floods the border rock to water). Both are
// sandy shores that read as land meeting water; their names match LPC_BIOME
// entries so the autotiler grounds them in Sand. Reuse the existing theme objects
// (no colour duplication to drift) — the island is a STRUCTURAL change, not a new
// palette.
const ISLAND_THEMES = [
  TUTORIAL_THEME,                                      // 'the Sunlit Shore' — pale beach sand, rocky coast
  THEMES.find((t) => t.name === 'the Coral Lagoon'),  // teal-and-coral tropical shore, leafy inland walls
];
// Share of eligible (outdoor, non-boss) floors that come up as an island.
const ISLAND_FLOOR_CHANCE = 0.12;
// When a floor rolls indoor, this holds that floor's chosen indoor theme; null on
// ordinary outdoor floors. Set in generateMap, cleared in town.
let floorThemeOverride = null;
// When a floor rolls as an island, this holds its coastal theme; null otherwise.
let floorIslandTheme = null;
let previewForceIndoor = null; // preview only: force a specific INDOOR_THEMES index
let previewForceIsland = false; // preview only: force an island floor
let previewDrawSolids = false; // preview only: paint solid tiles red to verify collision
// Themed by the DISPLAYED floor, so each difficulty replays the same visual
// progression (floor 1 always looks like floor 1) — only the red wash deepens.
// An indoor floor (floorThemeOverride), an island floor (floorIslandTheme) and the
// tutorial beach override this.
function currentTheme() { return floorThemeOverride || floorIslandTheme || (tutorialActive ? TUTORIAL_THEME : THEMES[(displayFloor() - 1) % THEMES.length]); }

// Rounded-rect helper (older canvases lack ctx.roundRect).
function roundRectPath(x, y, w, h, r) {
  if (ctx.roundRect) { ctx.beginPath(); ctx.roundRect(x, y, w, h, r); return; }
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// Draw the hero as a small composed adventurer instead of a single emoji, so the
// equipped (or cosmetic) head / chest / weapon visibly change the sprite. Each
// gear piece sits in its own clear zone: a helm on the head, armor on the torso,
// a weapon held to the side. Empty slots fall back to plain hair / tunic / hand.
// Weapon icon keys that have a matching pixel weapon sprite (w_<key>) in the
// atlas — so the hero can visibly hold whatever weapon type is equipped.
const WEAPON_ICON_KEYS = new Set(['sword','axe','dagger','staff','bow','mace','spear','scythe']);
// Quest-pet emoji → animal sprite (lost-pet quests).
// Town-NPC role → pixel townsfolk sprite (gambler/mystic reuse their world sprites).
const TOWN_SPRITE = { forge:'town_craftsman', healer:'town_healer', trainer:'town_trainer',
  enchanter:'town_enchanter', stash:'town_vault', gate:'feat_gate_red', gambler:'npc_gambler', mystic:'npc_mage' };
// Town building kind → pixel icon for its hanging shop shingle.
const BUILDING_SIGN_SPRITE = { merchant:'ic_money', forge:'ic_mallet', healer:'ic_heart',
  mystic:'ic_orb', enchanter:'ic_wand', gate:'feat_gate_red', trainer:'w_sword', gambler:'ic_coffer' };

// ── [data-spr] painter ───────────────────────────────────────────────────────
// Every game icon in the DOM is referenced directly by its atlas key — either an
// inline dlIcon(key) call or a `<span data-spr=key>` placeholder. This painter
// fills those placeholders (static markup at boot + any later-rendered ones via a
// MutationObserver). There is NO emoji resolution and NO emoji fallback anywhere:
// a genuine emoji left in the text (a decorative header glyph that maps to no
// sprite) simply renders as itself.
// Size a [data-spr] icon to its surroundings: scale it with the container's own
// font-size so it fills whatever context it sits in (a skill button, a menu row,
// a HUD chip), never below the 16px that reads well inline. Reading the *computed*
// font-size means the icon also tracks responsive media-query sizes for free.
function _ctxIconPx(parent) {
  let fs = 16;
  if (parent && parent.nodeType === 1) {
    try { fs = parseFloat(getComputedStyle(parent).fontSize) || 16; } catch (e) {}
  }
  // The computed font-size ALREADY includes the UI SIZE multiplier (the rem root
  // scales by --ui-scale), and dlIcon/dlIconAt now re-apply uiScale themselves —
  // so divide it back out here to hand dlIcon a BASE px and avoid scaling twice
  // (that double-count ballooned auto-de-emojified icons ~4x at 2x UI SIZE).
  const s = (typeof uiScale === 'number' && uiScale) ? uiScale : 1;
  return Math.max(16, Math.round((fs / s) * 1.2));
}
// Computed font-size (px) of an element's context; the rem root already bakes in
// the UI SIZE multiplier, so this value tracks the player's setting for free.
function _ctxFontPx(parent) {
  let fs = 16;
  if (parent && parent.nodeType === 1) {
    try { fs = parseFloat(getComputedStyle(parent).fontSize) || 16; } catch (e) {}
  }
  return fs;
}
// An inline atlas icon sized to the text beside it: its opaque art is trimmed of
// transparent padding and scaled so its HEIGHT ≈ the font-size, so every icon
// reads at the same height as the text — and as each other, regardless of how
// much empty margin its own tile happened to carry.
function _dlTextSpan(name, parent) { return _dlTextSpanPx(name, _ctxFontPx(parent)); }
// The icon-html builder, given an already-resolved context font-size (px). Split
// out of _dlTextSpan so the [data-spr] painter can hoist ALL its getComputedStyle
// reads ahead of its innerHTML writes (and dedupe them per parent). A parent's
// font-size never changes when a child span's innerHTML is written, so a batched
// read yields byte-identical html to the old per-icon interleaved read.
function _dlTextSpanPx(name, fs) {
  const sk = skillIconAt(name, Math.round(fs * TEXT_ICON_H / (uiScale || 1)));
  if (sk) return sk;
  const i = SPRITE_IDX[name];
  if (i === undefined || !spriteReady) return '';
  const targetH = Math.max(13, Math.round(fs * TEXT_ICON_H));
  const aw = spriteSheet.naturalWidth || 960, ah = spriteSheet.naturalHeight || 960;
  const col = i % ATLAS_COLS, row = (i / ATLAS_COLS) | 0;
  const box = _iconTrimBox(name);
  if (box) {
    const scale = targetH / box.h;
    const bx = -(col * ATLAS_TS + box.x0) * scale, by = -(row * ATLAS_TS + box.y0) * scale;
    return `<span class="dl-ic" style="width:${(box.w * scale).toFixed(2)}px;height:${targetH}px;` +
      `background-size:${aw * scale}px ${ah * scale}px;background-position:${bx.toFixed(2)}px ${by.toFixed(2)}px"></span>`;
  }
  const sc = targetH / ATLAS_TS;
  return `<span class="dl-ic" style="width:${targetH}px;height:${targetH}px;` +
    `background-size:${aw * sc}px ${ah * sc}px;background-position:-${col * targetH}px -${row * targetH}px"></span>`;
}
// Fill any [data-spr] element with its pixel atlas icon, trimmed and sized to the
// text around it (see _dlTextSpan).
function _collectDataSpr(root, out) {
  if (!root || root.nodeType !== 1) return;
  if (root.hasAttribute && root.hasAttribute('data-spr')) out.push(root);
  if (root.querySelectorAll) root.querySelectorAll('[data-spr]').forEach(e => out.push(e));
}
// READ-ALL then WRITE-ALL, in one pass: build every icon's html FIRST (all the
// getComputedStyle font-size reads hit one already-flushed layout, deduped per
// parent), THEN write all the innerHTML. The old loop read-then-wrote per icon, so
// each write dirtied layout and the next icon's read re-flushed it — O(n) forced
// reflows per paint, and #520's 960×960 resampled atlas made each flush ~3× costlier.
// One flush per pass now; the html bytes are identical, so icons render pixel-for-pixel
// unchanged.
function _paintSprList(list) {
  if (!spriteReady) return;
  const writes = [];
  const fsByParent = new Map();
  for (const el of list) {
    if (el.dataset.sprDone) continue;
    const parent = el.parentNode || el;
    let fs = fsByParent.get(parent);
    if (fs === undefined) { fs = _ctxFontPx(parent); fsByParent.set(parent, fs); }
    const html = _dlTextSpanPx(el.getAttribute('data-spr'), fs);
    if (html) writes.push(el, html);
  }
  for (let i = 0; i < writes.length; i += 2) { writes[i].innerHTML = writes[i + 1]; writes[i].dataset.sprDone = '1'; }
}
function paintDataSpr(root) {
  if (!spriteReady || !root || root.nodeType !== 1) return;
  const list = [];
  _collectDataSpr(root, list);
  _paintSprList(list);
}
// Boot the [data-spr] painter: paint the static markup once, then watch for any
// later-inserted placeholders (logs, panels, tooltips, HUD) and paint those too.
let _sprObserver = null;
function startSprPainter() {
  if (_sprObserver || !document.body) return;
  paintDataSpr(document.body);
  _sprObserver = new MutationObserver(muts => {
    if (!spriteReady) return;
    // Collect every newly-inserted placeholder across the WHOLE microtask, then
    // paint them in ONE read-all/write-all pass (a single kill inserts ~6 log-line
    // divs; batching pays one layout flush for the lot, not one per div).
    const list = [];
    for (const mu of muts) {
      mu.addedNodes.forEach(node => { if (node.nodeType === 1) _collectDataSpr(node, list); });
    }
    if (list.length) _paintSprList(list);
  });
  _sprObserver.observe(document.body, { childList: true, subtree: true });
}

// Draw the equipped weapon TYPE as a pixel sprite held at the hero's left side.
function drawHeldWeapon(px, py, tw, th, facingRight) {
  if (!spriteReady) return;
  const key = visualIcon('weapon');
  if (!key || !WEAPON_ICON_KEYS.has(key)) return;
  // Weapons are packed pointing up-and-to-the-left (tip top-left, grip bottom-
  // right) for the default left-facing hero, held low at the side. When the hero
  // faces right the weapon mirrors to the right side so the tip still angles up
  // and AWAY from the body.
  // Scale the 16px tile by a WHOLE-NUMBER multiple so the sprite's straight
  // diagonals stay straight. A fractional scale with nearest-neighbour doubles
  // some pixel rows and not others, which warps clean edges into wavy stairs.
  const k = Math.max(1, Math.round(tw * 0.5 / ATLAS_TS));
  const sz = ATLAS_TS * k;
  // Snap the draw origin to whole pixels too, so the scaled grid lands on exact
  // pixel boundaries (sub-pixel placement re-introduces the same warping).
  const ox = Math.round(facingRight ? px + tw * 0.96 : px + tw * 0.04);
  const oy = Math.round(py + th * 0.58);
  ctx.save();
  ctx.translate(ox, oy);
  if (facingRight) ctx.scale(-1, 1);
  drawSpriteC('w_' + key, 0, 0, sz);
  ctx.restore();
}

// Walk-cycle animation state: a phase accumulated by distance travelled, plus the
// last frame's timestamp so we can advance it by real elapsed time.
let _walkPhase = 0, _walkLastT = 0;
// Draw one frame of the hero's walk sheet: the row is chosen by 4-way facing and
// the column by the walk-cycle frame (animated while the hero is moving, frozen on
// the standing frame when still). The 48px character is drawn larger than a tile
// and bottom-anchored so its feet rest on the hero's cell. player.faceDir is kept
// up to date as the hero moves (see updatePlayer). These sheets carry their own
// left AND right rows, so they are NOT mirrored like the atlas hero.
function drawHeroWalk(img, px, py, tw, th) {
  const now = animNow();
  let adt = _walkLastT ? (now - _walkLastT) / 1000 : 0;
  if (adt > 0.1) adt = 0.1;                  // clamp after a stall so the cycle can't jump
  _walkLastT = now;
  const row = (HERO_WALK_ROW[player.faceDir] != null) ? HERO_WALK_ROW[player.faceDir] : HERO_WALK_ROW.down;
  const speed = Math.hypot(player.vx || 0, player.vy || 0);   // tiles/sec
  const moving = speed > 0.06;
  let col;
  if (moving) {
    // Advance the walk cycle by DISTANCE travelled, so the stride quickens with
    // speed — sprinting steps visibly faster than a walk.
    _walkPhase += Math.min(speed, HERO_WALK_MAXSPD) * adt * HERO_WALK_STRIDE;
    col = Math.floor(_walkPhase) % HERO_WALK_COLS;
  } else {
    col = HERO_WALK_IDLE;                     // neutral standing pose
    _walkPhase = HERO_WALK_IDLE;              // resume cleanly from neutral next step
  }
  const S = Math.round(th * 1.7);            // taller than a tile — these sprites read big
  const cx = px + tw / 2;
  const footY = py + th * 0.92;              // feet rest near the bottom of the cell
  const dx = Math.round(cx - S / 2);
  const dy = Math.round(footY - S * 0.92);   // 0.92 ≈ where the feet sit within the 48px frame
  const sm = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(img, col * HERO_WALK_TS, row * HERO_WALK_TS, HERO_WALK_TS, HERO_WALK_TS, dx, dy, S, S);
  ctx.imageSmoothingEnabled = sm;
}

// A faint, slowly-breathing golden aura around the hero whenever a worn set is
// complete (see completedSets) — the prestige "you finished a set" flourish. Drawn
// under the sprite so it haloes the feet/body. Cheap: one additive radial gradient.
function drawSetAura(cx, cy, tw) {
  const pulse = 0.5 + 0.5 * Math.sin(animNow() / 460);   // 0..1 slow breathe
  const R = tw * (1.12 + 0.1 * pulse);
  const gold = PALETTE.gold || '#e8c267';
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';               // additive → reads as emitted light
  const g = ctx.createRadialGradient(cx, cy, R * 0.12, cx, cy, R);
  g.addColorStop(0,    hexA(gold, 0.20 + 0.10 * pulse));
  g.addColorStop(0.5,  hexA(gold, 0.08 + 0.05 * pulse));
  g.addColorStop(1,    hexA(gold, 0));
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

function drawHeroSprite(px, py, tw, th, scale) {
  // Pixel-art hero, chosen by class so a Warrior, Rogue, Mage and Templar each
  // read differently. The equipped weapon TYPE is shown as a pixel weapon held
  // at the hero's side (matching the class's weapon, e.g. a staff for a Mage).
  // Animated 4-direction walk sheet (currently the Warrior's male/female art).
  // When the current hero has one, it fully replaces the atlas tile + mirroring.
  const walkImg = heroWalkSheet();
  if (walkImg) { drawHeroWalk(walkImg, px, py, tw, th); return; }
  // This class has a bespoke walk sheet that just hasn't decoded yet (only true
  // for the sub-second load window, and hidden behind the title overlay then):
  // hold off rather than flash the static atlas hero tile as a stand-in. The
  // shadow already drew and the walk sheet's onload repaints the instant it's
  // ready. Only a class with NO walk art falls through to the atlas tile below.
  if (heroHasWalkArt()) return;
  // No walk sheet (only a legacy classless save): fall through to the procedural
  // knight drawn below — no atlas hero tile, no fallback image.
  const cx = px + tw/2;
  const headCY  = py + th*0.30, headR = tw*0.155;
  const torsoTop = py + th*0.44, torsoW = tw*0.42, torsoH = th*0.30;
  const torsoX = cx - torsoW/2;

  const headIcon  = visualIcon('head');
  const chestIcon = visualIcon('chest');
  const weaponIcon = visualIcon('weapon');
  const chestTier = equipped.chest ? (equipped.chest.set ? SET_RARITY_COLOR : (TIERS[equipped.chest.tier]?.color || '#6d5a44')) : null;

  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';

  // ── legs + boots ──
  const legW = torsoW*0.30, legY = torsoTop + torsoH - th*0.01, legH = th*0.13;
  ctx.fillStyle = '#3f3550';
  ctx.fillRect(cx - torsoW*0.30, legY, legW, legH);
  ctx.fillRect(cx + torsoW*0.00, legY, legW, legH);
  ctx.fillStyle = '#241d30';
  ctx.fillRect(cx - torsoW*0.32, legY + legH, legW*1.1, th*0.04);
  ctx.fillRect(cx - torsoW*0.02, legY + legH, legW*1.1, th*0.04);

  // ── torso (armor if a chest piece is worn, plain tunic otherwise) ──
  ctx.fillStyle = chestTier || '#6d5a44';
  roundRectPath(torsoX, torsoTop, torsoW, torsoH, Math.max(2, 4*scale));
  ctx.fill();
  ctx.lineWidth = Math.max(1, 1.4*scale);
  ctx.strokeStyle = 'rgba(0,0,0,0.45)';
  ctx.stroke();

  // ── arms ──
  ctx.fillStyle = '#e8b48c';
  ctx.fillRect(torsoX - tw*0.06, torsoTop + torsoH*0.10, tw*0.07, torsoH*0.55);
  ctx.fillRect(torsoX + torsoW - tw*0.01, torsoTop + torsoH*0.10, tw*0.07, torsoH*0.55);

  // ── head (skin) ──
  ctx.fillStyle = '#e8b48c';
  ctx.beginPath();
  ctx.arc(cx, headCY, headR, 0, Math.PI*2);
  ctx.fill();
  ctx.lineWidth = Math.max(1, 1.2*scale);
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.stroke();

  // Default hair only when no headgear hides it.
  if (!headIcon) {
    ctx.fillStyle = '#5a3a22';
    ctx.beginPath();
    ctx.arc(cx, headCY - headR*0.25, headR, Math.PI*1.05, Math.PI*1.95);
    ctx.fill();
  }
  // Simple eyes for a bit of character.
  ctx.fillStyle = '#2a1d14';
  const eY = headCY + headR*0.08, eDx = headR*0.38, eR = Math.max(1, headR*0.16);
  ctx.beginPath(); ctx.arc(cx - eDx, eY, eR, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(cx + eDx, eY, eR, 0, Math.PI*2); ctx.fill();

  // ── worn gear, each drawn in its zone and tinted to its rarity colour ──
  ctx.shadowColor = 'rgba(0,0,0,0.55)';
  ctx.shadowBlur = 2*scale;
  const headColor   = equipped.head   ? (equipped.head.set   ? SET_RARITY_COLOR : (TIERS[equipped.head.tier]?.color   || '#cfd3da')) : '#cfd3da';
  const weaponColor = equipped.weapon ? (equipped.weapon.set ? SET_RARITY_COLOR : (TIERS[equipped.weapon.tier]?.color || '#cfd3da')) : '#cfd3da';

  if (chestIcon) {
    // The torso is already painted the chest's rarity colour, so draw the piece
    // in its own material colours on top (no rarity halo) and let the torso tint
    // carry the rarity for robe/plate/mail.
    drawIconPath(chestIcon, cx, torsoTop + torsoH*0.50, tw*0.42, null);
  }
  if (headIcon) {
    // Sit the headgear on the crown of the head, overlapping the top slightly.
    drawIconPath(headIcon, cx, headCY - headR*0.32, tw*0.54, headColor);
  }
  if (weaponIcon) {
    // Held in the right hand, tilted so it reads as a wielded weapon.
    ctx.save();
    ctx.translate(torsoX + torsoW + tw*0.12, torsoTop + torsoH*0.42);
    ctx.rotate(-0.5);
    drawIconPath(weaponIcon, 0, 0, tw*0.60, weaponColor);
    ctx.restore();
  }
  ctx.restore();
}

// Off-map and wall/cracked-wall tiles count as "wall" for seamless edges.
function isWallTile(x, y) {
  if (x < 0 || y < 0 || x >= MAP_W || y >= MAP_H) return true;
  const t = mapData[y][x];
  return t === 1 || t === 10;
}

// Draw a natural wall tile. Rocky cliff for most themes, leafy trees for the
// forest theme. Per-tile noise (from `seed`) keeps neighbours from cloning, and
// faces exposed to open floor get lit rims / cast shadows for depth. A wall mass
// is sunlit only along its crest (top tile), so stacked walls read as one cliff.
function drawWall(px, py, tw, th, x, y, seed, C, cracked) {
  // Indoor + outdoor both use the LPC autotiler now: drawLPCTerrain fills the
  // wall mass, so here we only add the crack overlay for damaged tiles.
  if (lpcReady) { if (cracked) lpcCrackOverlayMasked(px, py, tw, th, crackSeverity(wallCracks[y + ',' + x] || 0), seed, x, y); return; }
  if (C.wallStyle === 'forest') { drawForestWall(px, py, tw, th, x, y, seed, C, cracked); return; }
  if (C.wallStyle === 'pine') { drawPineWall(px, py, tw, th, x, y, seed, C, cracked); return; }
  if (C.wallStyle === 'mushroom') { drawMushroomWall(px, py, tw, th, x, y, seed, C, cracked); return; }
  if (C.wallStyle === 'crystal') { drawCrystalWall(px, py, tw, th, x, y, seed, C, cracked); return; }
  // Procedural rock wall (the original terrain look — the sprite atlas is reserved for
  // objects like stairs, spikes, characters and items, not the base terrain).
  const h = Math.abs(seed);
  const W = Math.max(1, Math.floor(tw)), H = Math.max(1, Math.floor(th));
  const topLit = !isWallTile(x, y - 1);

  // Base: vertical gradient — sunlit crest fading to shadow at the base.
  const g = ctx.createLinearGradient(px, py, px, py + th);
  if (topLit) { g.addColorStop(0, C.wallTop); g.addColorStop(0.28, C.wall); g.addColorStop(1, C.mortar); }
  else { g.addColorStop(0, C.wall); g.addColorStop(1, C.mortar); }
  ctx.fillStyle = g;
  ctx.fillRect(px, py, tw, th);

  // Rocky lumps — alternating light highlights and dark pockets, placed by seed.
  const lumps = 3 + (h % 3);
  for (let i = 0; i < lumps; i++) {
    const hsh = (h >> (i * 2 + 1));
    const lx = px + (hsh % W);
    const ly = py + ((hsh >> 4) % H);
    const r = tw * (0.12 + ((hsh >> 8) % 5) * 0.03);
    ctx.globalAlpha = 0.3;
    ctx.fillStyle = (i % 2 === 0) ? C.wallTop : C.mortar;
    ctx.beginPath(); ctx.arc(lx, ly, r, 0, Math.PI * 2); ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Fine grain speckle.
  ctx.fillStyle = 'rgba(0,0,0,0.12)';
  for (let i = 0; i < 4; i++) {
    const s = (h >> (i * 3 + 2));
    ctx.fillRect(px + (s % W), py + ((s >> 3) % H), Math.max(1, tw * 0.06), Math.max(1, th * 0.06));
  }

  // Decorative hairline fissure on the odd plain wall for texture — cracked walls
  // get the real breakable fracture from lpcCrackOverlay below instead.
  if (!cracked && h % 4 === 0) {
    ctx.strokeStyle = C.crack;
    ctx.lineWidth = Math.max(1, tw * 0.03);
    const sx = px + tw * (0.3 + (h % 3) * 0.16);
    const dir = (h % 2) ? 1 : -1;
    ctx.beginPath();
    ctx.moveTo(sx, py + th * 0.08);
    ctx.lineTo(sx + tw * 0.12 * dir, py + th * 0.5);
    ctx.lineTo(sx - tw * 0.06 * dir, py + th * 0.94);
    ctx.stroke();
  }

  // Exposed faces: lit rim where open above/left, cast shadow where open right.
  if (!isWallTile(x, y - 1)) { ctx.fillStyle = 'rgba(255,250,235,0.16)'; ctx.fillRect(px, py, tw, Math.max(1, th * 0.12)); }
  if (!isWallTile(x - 1, y)) { ctx.fillStyle = 'rgba(255,250,235,0.06)'; ctx.fillRect(px, py, Math.max(1, tw * 0.1), th); }
  if (!isWallTile(x + 1, y)) { ctx.fillStyle = 'rgba(0,0,0,0.2)'; ctx.fillRect(px + tw - Math.max(1, tw * 0.16), py, Math.max(1, tw * 0.16), th); }

  // Breakable fracture — the shared hairline crack overlay every wall style uses,
  // so a cracked wall reads by its cracks alone (no box), fanning wider each shove.
  if (cracked) lpcCrackOverlay(px, py, tw, th, crackSeverity(wallCracks[y + ',' + x] || 0), seed);
}

// Leafy-tree wall for the forest theme — overlapping canopies read as a thicket.
function drawForestWall(px, py, tw, th, x, y, seed, C, cracked) {
  const h = Math.abs(seed);
  const W = Math.max(1, Math.floor(tw)), H = Math.max(1, Math.floor(th));
  // Shadowed undergrowth base.
  ctx.fillStyle = C.mortar;
  ctx.fillRect(px, py, tw, th);
  // Trunk.
  ctx.fillStyle = '#4a2f1c';
  ctx.fillRect(px + tw / 2 - tw * 0.08, py + th * 0.5, tw * 0.16, th * 0.5);
  // Canopy: layered blobs in three greens, placed by seed so each tile differs.
  const cols = [C.wall, C.brickA, C.wallTop];
  const blobs = 4 + (h % 3);
  for (let i = 0; i < blobs; i++) {
    const hsh = (h >> (i * 2 + 1));
    const cx = px + tw * (0.2 + (hsh % 6) * 0.1);
    const cy = py + th * (0.12 + ((hsh >> 4) % 5) * 0.09);
    const r = tw * (0.22 + ((hsh >> 8) % 4) * 0.04);
    ctx.fillStyle = cols[i % cols.length];
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();
  }
  // Shadow pocket for depth.
  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  ctx.beginPath(); ctx.arc(px + tw * 0.72, py + th * 0.62, tw * 0.26, 0, Math.PI * 2); ctx.fill();
  // Sun-dappled highlights.
  ctx.fillStyle = 'rgba(220,255,160,0.25)';
  for (let i = 0; i < 3; i++) {
    const s = (h >> (i * 3 + 2));
    ctx.fillRect(px + (s % W), py + ((s >> 3) % H), Math.max(1, tw * 0.07), Math.max(1, th * 0.07));
  }
  if (cracked) lpcCrackOverlay(px, py, tw, th, crackSeverity(wallCracks[y + ',' + x] || 0), seed);
}

// Conifer wall for alpine themes — stacked triangular tiers with snow-bright
// tips, slightly offset per tile so a stand of pines reads as a forest.
function drawPineWall(px, py, tw, th, x, y, seed, C, cracked) {
  const h = Math.abs(seed);
  // Shadowed groundcover base.
  ctx.fillStyle = C.mortar;
  ctx.fillRect(px, py, tw, th);
  // Trunk.
  ctx.fillStyle = '#4a2f1c';
  ctx.fillRect(px + tw / 2 - tw * 0.06, py + th * 0.74, tw * 0.12, th * 0.26);
  // Three conifer tiers, widest at the bottom; lighter/snowier toward the top.
  const cx = px + tw / 2 + ((h % 3) - 1) * tw * 0.05;
  const tierCols = [C.wallTop, C.brickA, C.wall];
  for (let i = 0; i < 3; i++) {
    const t0 = i / 3;
    const topY = py + th * (0.06 + t0 * 0.26);
    const botY = py + th * (0.40 + t0 * 0.26);
    const halfW = tw * (0.16 + t0 * 0.17);
    ctx.fillStyle = tierCols[i];
    ctx.beginPath();
    ctx.moveTo(cx, topY);
    ctx.lineTo(cx - halfW, botY);
    ctx.lineTo(cx + halfW, botY);
    ctx.closePath();
    ctx.fill();
  }
  // Snow-bright cap on the very tip.
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.beginPath();
  ctx.moveTo(cx, py + th * 0.06);
  ctx.lineTo(cx - tw * 0.06, py + th * 0.16);
  ctx.lineTo(cx + tw * 0.06, py + th * 0.16);
  ctx.closePath();
  ctx.fill();
  if (cracked) lpcCrackOverlay(px, py, tw, th, crackSeverity(wallCracks[y + ',' + x] || 0), seed);
}

// Giant toadstool wall — a pale stalk under a spotted dome cap, for the exotic
// mushroom theme. Cap colour and spots come from the palette; offset per tile.
function drawMushroomWall(px, py, tw, th, x, y, seed, C, cracked) {
  const h = Math.abs(seed);
  ctx.fillStyle = C.mortar;
  ctx.fillRect(px, py, tw, th);
  const sx = px + tw / 2 + ((h % 3) - 1) * tw * 0.06;
  // Stalk.
  ctx.fillStyle = C.brickB;
  ctx.fillRect(sx - tw * 0.09, py + th * 0.42, tw * 0.18, th * 0.58);
  // Cap dome.
  const capCol = (h % 2) ? C.wall : C.brickA;
  const capY = py + th * 0.4, rx = tw * 0.34, ry = th * 0.28;
  ctx.fillStyle = capCol;
  ctx.beginPath(); ctx.ellipse(sx, capY, rx, ry, 0, 0, Math.PI * 2); ctx.fill();
  // Underside shadow line.
  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.fillRect(sx - rx * 0.9, capY + ry * 0.55, rx * 1.8, Math.max(1, th * 0.04));
  // Spots.
  ctx.fillStyle = C.wallTop;
  for (let i = 0; i < 3; i++) {
    const s = (h >> (i * 3 + 1));
    const dx = ((s % 100) / 100 - 0.5) * rx * 1.2;
    const dy = ((s >> 4) % 100) / 100 * ry * 0.6 - ry * 0.2;
    ctx.beginPath(); ctx.arc(sx + dx, capY + dy, tw * 0.05, 0, Math.PI * 2); ctx.fill();
  }
  if (cracked) lpcCrackOverlay(px, py, tw, th, crackSeverity(wallCracks[y + ',' + x] || 0), seed);
}

// Glowing crystal cluster wall — angular shards rising from the floor, lit with
// a soft glow, for the exotic crystal-cavern theme.
function drawCrystalWall(px, py, tw, th, x, y, seed, C, cracked) {
  const h = Math.abs(seed);
  ctx.fillStyle = C.mortar;
  ctx.fillRect(px, py, tw, th);
  ctx.save();
  ctx.shadowColor = C.wallTop;
  ctx.shadowBlur = 8 * (tw / 16);
  const shards = 3 + (h % 3);
  const cols = [C.wall, C.brickA, C.wallTop];
  for (let i = 0; i < shards; i++) {
    const s = (h >> (i * 2 + 1));
    const bx = px + tw * (0.18 + (s % 7) * 0.1);
    const by = py + th * 0.98;
    const wHalf = tw * (0.06 + ((s >> 4) % 3) * 0.03);
    const ht = th * (0.42 + ((s >> 8) % 5) * 0.1);
    ctx.fillStyle = cols[i % cols.length];
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.lineTo(bx - wHalf, by - ht * 0.62);
    ctx.lineTo(bx, by - ht);
    ctx.lineTo(bx + wHalf, by - ht * 0.62);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
  if (cracked) lpcCrackOverlay(px, py, tw, th, crackSeverity(wallCracks[y + ',' + x] || 0), seed);
}

// ── AMBIENT EMBERS ── seed the decorative drifting motes once (see the
// #ambient-embers CSS). They're slow and faint so they enliven the map without
// distracting from play; the colour is theme-tinted by updateAmbientTint().
function seedAmbientEmbers() {
  const host = document.getElementById('ambient-embers');
  if (!host || host.childElementCount) return;
  let html = '';
  for (let i = 0; i < 12; i++) {
    const left = Math.round(Math.random() * 100);
    const size = (1.5 + Math.random() * 2).toFixed(1);
    const dur = (10 + Math.random() * 8).toFixed(1);
    const delay = (Math.random() * 12).toFixed(1);
    const drift = Math.round(-40 + Math.random() * 80);
    html += `<span class="amber" style="left:${left}%;width:${size}px;height:${size}px;animation-duration:${dur}s;animation-delay:${delay}s;--drift:${drift}px"></span>`;
  }
  host.innerHTML = html;
}
// ── Static HUD node cache ──
// The per-frame HUD updaters (vital fills, stamina, cooldown dials, halo,
// ambient tint, the pause checks) each did fresh getElementById lookups every
// frame. These nodes are all static in the shell (index.html) and never
// recreated — syncDesktopHud only re-PARENTS #skill-bar/#pact-hud/#food-hud,
// which keeps node identity — so resolve each id once and reuse the element.
const _hudEls = {};
function hudEl(id) {
  let el = _hudEls[id];
  if (el === undefined) el = _hudEls[id] = document.getElementById(id);
  return el;
}
// Tint the motes to the current floor's glow colour (warm on fiery themes, cool
// on icy ones). Cheap, but guarded so it only writes when the theme changes.
let _amberTint = null;
function updateAmbientTint(theme) {
  const host = hudEl('ambient-embers');
  if (!host) return;
  const tint = ((theme || currentTheme()) || {}).stairsGlow || '#ffb24a';
  if (tint === _amberTint) return;
  _amberTint = tint;
  host.style.setProperty('--amber', tint);
}

// The painterly vignette gradient depends only on the canvas size, so it's
// memoized and rebuilt only on resize (building a radial gradient every frame
// was pure repeated work — the stops never change).
let _vignetteGrad = null, _vignetteW = 0, _vignetteH = 0;

function draw() {
  const W = canvas.width, H = canvas.height;
  const C = currentTheme();
  updateAmbientTint(C);
  ctx.fillStyle = '#0a0a0f';
  ctx.fillRect(0, 0, W, H);

  // ── FOLLOW CAMERA ──
  // Aim to show ~VIEW_TILES across the shorter axis, so tiles are large.
  const tw = Math.ceil(Math.min(W, H) / VIEW_TILES);
  const th = tw;

  // Center the camera on the player, then clamp so we never scroll past edges.
  // While walking THROUGH a teleporter the camera instead glides from the pad the
  // hero left to its partner (warpFrame.panT), so you see where you came out. On a
  // map smaller than the viewport the clamp centres it and the pan is a no-op —
  // both pads are already on screen.
  let camFx = player.fx, camFy = player.fy;
  if (warpFx) {
    const wf = warpFrameAt(warpFx.t, warpFx.dur);
    camFx = warpFx.sx + (warpFx.dx - warpFx.sx) * wf.panT;
    camFy = warpFx.sy + (warpFx.dy - warpFx.sy) * wf.panT;
  }
  let camX = camFx * tw - W/2;
  // On touch, lift the hero above the bottom control band (joystick / skill
  // cluster) so the thumbs never cover it. touchCamBiasPx is device px, recomputed
  // per resize/orientation; 0 on desktop, so this line is a no-op there.
  let camY = camFy * th - H/2 + touchCamBiasPx;
  const maxCamX = MAP_W * tw - W;
  const maxCamY = MAP_H * th - H;
  // If the map is smaller than the viewport on an axis, center it instead.
  camX = (MAP_W * tw <= W) ? -(W - MAP_W*tw)/2 : Math.max(0, Math.min(camX, maxCamX));
  camY = (MAP_H * th <= H) ? -(H - MAP_H*th)/2 : Math.max(0, Math.min(camY, maxCamY));

  const [_shx, _shy] = shakeOffset();
  const offX = Math.round(-camX + _shx);
  const offY = Math.round(-camY + _shy);
  const scale = tw / TILE; // for glow blur sizing, relative to base tile

  // Remember the camera so a click on the canvas can be converted back to a map
  // tile (click-to-move / click-to-USE).
  lastCam = { tw, th, camX, camY };

  // Only draw tiles within the visible window (perf + clean edges)
  const x0 = Math.max(0, Math.floor(camX / tw));
  const y0 = Math.max(0, Math.floor(camY / th));
  const x1 = Math.min(MAP_W, Math.ceil((camX + W) / tw));
  const y1 = Math.min(MAP_H, Math.ceil((camY + H) / th));

  // LPC terrain — real autotiled pixel ground replaces the procedural fill.
  // Indoor maps route through the same autotiler now (via indoorRoles), so both
  // outdoor biomes and built interiors get real tiled floors + clustered accents.
  if (PROC_TERRAIN && !inTown && !C.indoor) drawProcTerrain(offX, offY, tw); // preview: procedural terrain-pack ground
  else if (lpcReady) drawLPCTerrain(offX, offY, tw, x0, y0, x1, y1);   // town uses the real autotiled terrain too (grass + dirt trails)

  // Draw tiles
  for (let y = y0; y < y1; y++) {
    for (let x = x0; x < x1; x++) {
      const px = offX + x * tw, py = offY + y * th;
      const t = mapData[y][x];
      const seed = (x * 73856093) ^ (y * 19349663); // deterministic per-tile

      // The walkable town renders through the SAME real terrain path as an outdoor
      // floor (grass + dirt trails, rock border) — see terrainRoles/TOWN_TERRAIN — so
      // there's no town-special tile branch here anymore; it just falls through.

      // preview: the procedural terrain pass already painted walls/water/lava
      if (PROC_TERRAIN && (t === 1 || t === 10 || t === 6 || t === 7)) continue;
      if (t === 1) {
        drawWall(px, py, tw, th, x, y, seed, C, false);
      } else if (t === 2) {
        // Stairs down — pixel staircase (the ▼ arrow is baked into the
        // tile). While the floor is uncleared the exit is sealed: a red wash plus
        // a padlock icon. Once cleared, a pulsing gold ring marks it as the
        // way DEEPER, so it's obvious you descend here and not via the up-stairs.
        const sealed = !floorCleared;
        if (!(spriteReady && drawSprite('stairs_down', px, py, tw))) {
          // Legacy fallback: dark pit with descending steps.
          ctx.fillStyle = '#0d0d14'; ctx.fillRect(px, py, tw, th);
          for (let s = 0; s < 4; s++) {
            const shade = 20 + s * 14;
            ctx.fillStyle = `rgb(${shade+30},${shade+22},${Math.floor(shade*0.4)})`;
            const inset = (s / 4) * tw * 0.4, sy = py + (s / 4) * th * 0.5;
            ctx.fillRect(px + inset, sy, tw - inset*2, th * 0.125 + 1);
          }
        }
        if (sealed) {
          // Faint red wash + a padlock icon so a not-yet-open exit reads at
          // a glance. Colour alone (no text label) signals the locked state.
          ctx.save(); ctx.globalAlpha = 0.28; ctx.fillStyle = '#cc3322'; ctx.fillRect(px, py, tw, th); ctx.restore();
          if (spriteReady) drawSpriteC('feat_lock', px + tw/2, py + th*0.5, Math.round(tw*0.5));
        } else {
          // Cleared → highlight the way deeper with a pulsing gold ring so the
          // descent stair is unmistakable next to the (plain) up-stairs.
          const pulse = 0.5 + 0.5 * Math.sin(animNow() / 320);
          const lw = Math.max(2, tw * 0.09), o = lw / 2 + 1;
          ctx.save();
          ctx.lineWidth = lw;
          ctx.strokeStyle = `rgba(255,207,90,${0.5 + 0.45 * pulse})`;
          ctx.shadowColor = 'rgba(255,200,80,0.9)';
          ctx.shadowBlur = tw * (0.18 + 0.22 * pulse);
          ctx.strokeRect(px + o, py + o, tw - o * 2, th - o * 2);
          ctx.restore();
        }
      } else if (t === 12) {
        // "Up" stair. On floor 1 of a difficulty it's the way back to TOWN, so it
        // shows the dungeon-gate marker (the same tile the HUD floor and town gate
        // use); on deeper floors it's the climbing staircase.
        const upSprite = displayFloor() === 1 ? 'feat_gate_red' : 'stairs_up';
        if (!(spriteReady && drawSprite(upSprite, px, py, tw))) {
          ctx.fillStyle = '#0d0d14'; ctx.fillRect(px, py, tw, th);
          for (let s = 0; s < 4; s++) {
            const shade = 20 + s * 14;
            ctx.fillStyle = `rgb(${shade+30},${shade+22},${Math.floor(shade*0.4)})`;
            const inset = (s / 4) * tw * 0.4, sy = py + th*0.5 - (s / 4) * th * 0.5;
            ctx.fillRect(px + inset, sy, tw - inset*2, th * 0.125 + 1);
          }
        }
      } else if (t === 3) {
        // Fountain of Healing — a tiered stone fountain with water spraying
        // from a central spout into a glowing basin.
        drawFloorBase(px, py, tw, th, seed, C);
        const cx = px + tw/2, cy = py + th/2, s = tw/TILE;
        const tNow = animNow();
        const wp = 0.5 + 0.5*Math.sin(tNow/400);   // slow pool shimmer
        // soft ground shadow
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.28)';
        ctx.beginPath();
        ctx.ellipse(cx, cy + th*0.30, tw*0.40, th*0.20, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.restore();
        // outer stone basin — darker base ring for depth
        ctx.fillStyle = '#3d3d52';
        ctx.beginPath();
        ctx.ellipse(cx, cy + th*0.06, tw*0.44, th*0.34, 0, 0, Math.PI*2);
        ctx.fill();
        // stone rim (lighter on top to read as 3D)
        ctx.fillStyle = '#6a6a86';
        ctx.beginPath();
        ctx.ellipse(cx, cy, tw*0.44, th*0.32, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.fillStyle = '#85859e';
        ctx.beginPath();
        ctx.ellipse(cx, cy - th*0.02, tw*0.44, th*0.16, 0, Math.PI, Math.PI*2);
        ctx.fill();
        // water pool inside the basin
        ctx.fillStyle = `rgba(70,160,235,${0.85+0.15*wp})`;
        ctx.beginPath();
        ctx.ellipse(cx, cy, tw*0.34, th*0.24, 0, 0, Math.PI*2);
        ctx.fill();
        // animated ripple rings on the pool
        ctx.save();
        ctx.strokeStyle = 'rgba(190,230,255,0.5)';
        ctx.lineWidth = Math.max(1, 1.4*s);
        for (let r = 0; r < 2; r++) {
          const rr = ((tNow/700 + r*0.5) % 1);
          ctx.globalAlpha = 0.5 * (1 - rr);
          ctx.beginPath();
          ctx.ellipse(cx, cy, tw*0.30*rr + tw*0.05, th*0.20*rr + th*0.04, 0, 0, Math.PI*2);
          ctx.stroke();
        }
        ctx.restore();
        // central stone pedestal + top dish
        ctx.fillStyle = '#6a6a86';
        ctx.fillRect(cx - tw*0.07, cy - th*0.20, tw*0.14, th*0.22);
        ctx.fillStyle = '#85859e';
        ctx.beginPath();
        ctx.ellipse(cx, cy - th*0.20, tw*0.16, th*0.07, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.fillStyle = `rgba(120,200,255,${0.8+0.2*wp})`;
        ctx.beginPath();
        ctx.ellipse(cx, cy - th*0.20, tw*0.10, th*0.04, 0, 0, Math.PI*2);
        ctx.fill();
        // glowing water jet spraying up from the dish
        ctx.save();
        ctx.shadowColor = '#9ad8ff';
        ctx.shadowBlur = 8 * s;
        ctx.strokeStyle = 'rgba(200,240,255,0.85)';
        ctx.lineWidth = Math.max(1.5, 2*s);
        ctx.beginPath();
        ctx.moveTo(cx, cy - th*0.22);
        ctx.lineTo(cx, cy - th*0.46);
        ctx.stroke();
        // arcing droplets falling back into the pool
        ctx.fillStyle = 'rgba(210,240,255,0.95)';
        for (let d = 0; d < 6; d++) {
          const ph = ((tNow/520 + d/6) % 1);          // 0→1 arc progress
          const dir = d % 2 ? 1 : -1;
          const dx = dir * tw*0.30 * ph;
          const dy = -th*0.42 + (th*0.66) * (ph*ph);  // up then accelerate down
          ctx.beginPath();
          ctx.arc(cx + dx, cy - th*0.04 + dy, Math.max(1, 1.6*s), 0, Math.PI*2);
          ctx.fill();
        }
        ctx.restore();
        // overall healing glow
        ctx.save();
        ctx.globalAlpha = 0.10 + 0.10*wp;
        ctx.fillStyle = '#8ad0ff';
        ctx.beginPath();
        ctx.ellipse(cx, cy, tw*0.5, th*0.4, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.restore();
      } else if (t === 5) {
        // Shrine — altar on the floor. A soft purple glow fades out from
        // behind the icon only (same radial style as a lucky chest), not a flat
        // wash over the whole tile.
        drawFloorBase(px, py, tw, th, seed, C);
        const sp = 0.5 + 0.5*Math.sin(animNow()/350);
        if (spriteReady && SPRITE_IDX['feat_shrine'] !== undefined) {
          glowUnder(px + tw/2, py + th/2, tw*(0.34 + 0.06*sp), `rgba(216,168,255,${0.40 + 0.22*sp})`);
          drawSprite('feat_shrine', px, py, tw);
        } else {
          ctx.save();
          ctx.shadowColor = '#d8a8ff';
          ctx.shadowBlur = (6 + 6*sp) * (tw/TILE);
          ctx.fillStyle = '#6a5a8a';
          ctx.fillRect(px+tw*0.38, py+th*0.25, tw*0.24, th*0.55); // pillar
          ctx.fillStyle = `rgba(216,168,255,${0.6+0.4*sp})`;
          ctx.beginPath();
          ctx.arc(px+tw/2, py+th*0.28, tw*0.16, 0, Math.PI*2); // glowing orb
          ctx.fill();
          ctx.restore();
        }
      } else if (t === 6) {
        // Water — procedural animated liquid (terrain stays procedural).
        drawLiquid(px, py, tw, th, x, y, seed, C, 'water');
      } else if (t === 7) {
        // Lava — procedural animated liquid (terrain stays procedural).
        drawLiquid(px, py, tw, th, x, y, seed, C, 'lava');
      } else if (t === 8) {
        // Spike trap — flush spikes set into the floor that thrust up
        // while the player stands on the tile. It renders the retracted tile
        // (`spikes_rest`) normally and the extruded tile (`spikes_up`) when the
        // hero is on it, then sinks back to flush once they step off.
        drawFloorBase(px, py, tw, th, seed, C);
        const armed = !!(player && player.x === x && player.y === y);
        const spikeTile = armed ? 'spikes_up' : 'spikes_rest';
        if (spriteReady && drawSprite(spikeTile, px, py, tw)) {
          continue;
        }
        // Procedural spikes fallback — slim blades, taller while armed.
        const baseY = py + th*0.7, tipY = py + th*(armed ? 0.30 : 0.46);
        ctx.fillStyle = '#9a9aac';
        ctx.fillRect(px+tw*0.28, baseY, tw*0.44, Math.max(1, th*0.06));
        ctx.fillStyle = '#c4c4d2';
        for (let s = 0; s < 3; s++) {
          const sx = px + tw*(0.34 + s*0.16);
          ctx.beginPath();
          ctx.moveTo(sx - tw*0.04, baseY);
          ctx.lineTo(sx, tipY);
          ctx.lineTo(sx + tw*0.04, baseY);
          ctx.closePath();
          ctx.fill();
        }
      } else if (t === 9) {
        // Teleporter pad — the shared animated portal, tinted PURPLE so an in-level
        // warp reads distinctly from the BLUE town portals.
        drawFloorBase(px, py, tw, th, seed, C);
        drawPortal(px + tw / 2, py + th / 2, tw, 'teleporter');
      } else if (t === 10) {
        // Cracked wall — natural rock with an obvious breakable fracture.
        drawWall(px, py, tw, th, x, y, seed, C, true);
      } else if (t === 11) {
        // Locked vault door — door tile over the floor.
        drawFloorBase(px, py, tw, th, seed, C);
        if (!(spriteReady && drawSprite('feat_door', px, py, tw))) {
          ctx.fillStyle = '#5a3a1c';
          ctx.fillRect(px+tw*0.18, py+th*0.1, tw*0.64, th*0.8);
          ctx.fillStyle = '#3f2813';
          ctx.fillRect(px+tw*0.46, py+th*0.1, Math.max(1, tw*0.06), th*0.8);
          ctx.fillStyle = '#caa15a';
          ctx.beginPath();
          ctx.arc(px+tw*0.66, py+th*0.5, tw*0.08, 0, Math.PI*2);
          ctx.fill();
        }
      } else if (!lpcReady) {
        // Floor base — organic per-tile variation instead of a checkerboard:
        // most tiles use the base colour, a few the alt, and every tile gets a
        // faint lightness jitter so the ground reads as natural, worn stone.
        ctx.fillStyle = (Math.abs(seed) % 5 === 0) ? C.floorAlt : C.floor;
        ctx.fillRect(px, py, tw, th);
        const fv = (Math.abs(seed >> 2) % 7) - 3;   // -3..+3
        if (fv > 0) { ctx.fillStyle = `rgba(255,248,230,${fv * 0.013})`; ctx.fillRect(px, py, tw, th); }
        else if (fv < 0) { ctx.fillStyle = `rgba(0,0,0,${(-fv) * 0.022})`; ctx.fillRect(px, py, tw, th); }
        // flagstone seams — barely-there grid lines
        ctx.fillStyle = 'rgba(0,0,0,0.05)';
        ctx.fillRect(px, py, tw, 1);
        ctx.fillRect(px, py, 1, th);
        // speckle / rubble (deterministic)
        const speckles = (seed % 4);
        ctx.fillStyle = C.speckle;
        for (let s = 0; s < speckles; s++) {
          const sx = px + ((seed >> (s*3+1)) % tw);
          const sy = py + ((seed >> (s*2+2)) % th);
          ctx.fillRect(sx, sy, Math.max(1, tw*0.08), Math.max(1, th*0.08));
        }
        // occasional accent tint (moss/embers/frost depending on theme)
        if (seed % 11 === 0) {
          ctx.fillStyle = C.accent;
          ctx.fillRect(px+tw*0.2, py+th*0.2, tw*0.5, th*0.5);
        }
        // Ambient occlusion: walls cast a soft shadow onto the floor below and
        // to the right, giving the tiles a painterly sense of depth.
        if (y > 0 && (mapData[y-1][x] === 1 || mapData[y-1][x] === 10)) {
          ctx.fillStyle = 'rgba(0,0,0,0.28)';
          ctx.fillRect(px, py, tw, Math.max(1, th*0.16));
          ctx.fillStyle = 'rgba(0,0,0,0.12)';
          ctx.fillRect(px, py + th*0.16, tw, Math.max(1, th*0.12));
        }
        if (x > 0 && (mapData[y][x-1] === 1 || mapData[y][x-1] === 10)) {
          ctx.fillStyle = 'rgba(0,0,0,0.18)';
          ctx.fillRect(px, py, Math.max(1, tw*0.14), th);
        }
      }
    }
  }

  // Ground decor (non-blocking): drawn over the floor, under actors. Both outdoor
  // scenery (trees/rocks/bushes) and indoor props (furniture/crates). This runs in
  // its OWN pass — not inside the tile loop above — because a piece is anchored by
  // its feet and extends up/out, so one whose anchor tile sits just past the screen
  // edge can still show its crown or flanks. Over-scan the window by the tallest/
  // widest sprite (below + sideways; feet never rise above the anchor, so the top
  // needs only a small pad) and iterate top→bottom so nearer pieces paint over far.
  // Runs in both the dungeon and the walkable town — the town authors its greenery
  // into decorMap the same way (buildTown), and it's culled to the visible window.
  {
    const dx0 = Math.max(0, x0 - DECOR_MAX_HALF_W), dx1 = Math.min(MAP_W, x1 + DECOR_MAX_HALF_W);
    const dy0 = Math.max(0, y0 - 1), dy1 = Math.min(MAP_H, y1 + DECOR_MAX_H_TILES);
    for (let y = dy0; y < dy1; y++) for (let x = dx0; x < dx1; x++) {
      if (mapData[y][x] === 0) drawDecorAt(x, y, offX + x * tw, offY + y * th, tw, th);
    }
  }

  // Click-to-move destination marker (desktop): a small pulsing gold ring on the
  // ground where the hero is headed, so the click target reads at a glance. Drawn
  // on the floor, beneath actors. Procedural UI overlay, not a world asset.
  if (moveTarget.active) {
    // When routing around a wall, sketch faint gold breadcrumbs along the planned
    // route (from where the hero is now) so the path it will take reads at a glance.
    const path = moveTarget.path;
    if (showPathLine && path && path.length) {
      ctx.save();
      ctx.strokeStyle = 'rgba(232,194,103,0.35)';
      ctx.lineWidth = Math.max(1, tw * 0.04);
      ctx.setLineDash([tw * 0.14, tw * 0.14]);
      ctx.beginPath();
      ctx.moveTo(offX + player.fx * tw, offY + player.fy * th);
      for (let i = moveTarget.pathIdx; i < path.length; i++) ctx.lineTo(offX + path[i].x * tw, offY + path[i].y * th);
      ctx.lineTo(offX + moveTarget.wx * tw, offY + moveTarget.wy * th);
      ctx.stroke();
      ctx.restore();
    }
    const mxp = offX + moveTarget.wx * tw, myp = offY + moveTarget.wy * th;
    const pulse = 0.5 + 0.5 * Math.sin(animNow() / 180);
    const rad = tw * (0.18 + 0.05 * pulse);
    ctx.save();
    ctx.lineWidth = Math.max(1.5, tw * 0.05);
    ctx.strokeStyle = `rgba(232,194,103,${0.5 + 0.4 * pulse})`;
    ctx.shadowColor = 'rgba(232,194,103,0.85)';
    ctx.shadowBlur = tw * 0.18;
    ctx.beginPath(); ctx.arc(mxp, myp, rad, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(mxp - rad * 0.55, myp); ctx.lineTo(mxp + rad * 0.55, myp);
    ctx.moveTo(mxp, myp - rad * 0.55); ctx.lineTo(mxp, myp + rad * 0.55);
    ctx.stroke();
    ctx.restore();
  }

  // Boss-conjured hazards — walls of flame and arcane barriers. Drawn over the
  // floor but beneath actors. Fire uses the flame tile; the barrier is a
  // procedural magical construct (terrain-like, so procedural is fine).
  bossHazards.forEach(h => {
    if (h.x + 1 < x0 || h.x > x1 || h.y + 1 < y0 || h.y > y1) return; // off-screen (same window as the enemy/trap loops)
    const px = offX + h.x * tw, py = offY + h.y * th;
    const cx = px + tw/2, cy = py + th/2;
    const wob = 0.6 + 0.4 * Math.sin(animNow()/120 + (h.x*7 + h.y*13));
    if (h.kind === 'fire') {
      glowUnder(cx, cy, tw*0.55, `rgba(255,110,40,${0.28 + 0.18*wob})`);
      if (spriteReady) drawSpriteC('ic_fire', cx, cy, Math.round(tw*0.92));
    } else if (h.kind === 'wall') {
      const a = h.secs <= 1 ? 0.5 : 0.85; // fades in its final second as it's about to crumble
      ctx.save();
      ctx.globalAlpha = a;
      ctx.fillStyle = '#5b43a0';
      ctx.fillRect(px+tw*0.06, py+th*0.06, tw*0.88, th*0.88);
      ctx.fillStyle = `rgba(190,160,255,${0.5 + 0.4*wob})`;
      ctx.fillRect(px+tw*0.06, py+th*0.06, tw*0.88, Math.max(1, th*0.14));
      ctx.strokeStyle = `rgba(205,175,255,${0.55 + 0.35*wob})`;
      ctx.lineWidth = Math.max(1, tw*0.05);
      ctx.strokeRect(px+tw*0.06, py+th*0.06, tw*0.88, th*0.88);
      ctx.restore();
    }
  });

  // Boss telegraphs — floor indicators for incoming boss attacks, painted on the
  // ground under the sprites so the danger zone reads clearly.
  drawBossTelegraphs(offX, offY, tw, th, x0, y0, x1, y1);

  // Ground chests — a classic brown chest with gold trim, drawn by hand so it
  // looks the same on every device. Lucky chests glow brighter gold.
  groundItems.forEach(({ x, y, luck }) => {
    if (x + 1 < x0 || x > x1 || y + 1 < y0 || y > y1) return; // off-screen
    const lucky = (luck || 1) > 1;
    const px = offX + x * tw, py = offY + y * th;
    const cx = px + tw/2, cy = py + th/2;
    // Pixel-art chest sprite (lucky chests get a brighter glow), with the
    // hand-drawn chest below as fallback.
    if (spriteReady && SPRITE_IDX['chest'] !== undefined) {
      glowUnder(cx, cy, tw * (lucky ? 0.6 : 0.46), lucky ? 'rgba(255,224,102,0.45)' : 'rgba(202,162,74,0.3)');
      drawSpriteC('chest', cx, cy, itemSpritePx(tw));
      return;
    }
    const w = tw * 0.58, h = th * 0.46;
    const bx = cx - w/2, by = cy - h/2;
    const gold = lucky ? '#ffd24b' : '#d9a441';
    ctx.save();
    ctx.shadowColor = lucky ? '#ffe066' : '#caa24a';
    ctx.shadowBlur = (lucky ? 14 : 7) * scale;
    // wooden body
    ctx.fillStyle = '#7a4a22';
    ctx.fillRect(bx, by, w, h);
    ctx.shadowBlur = 0;
    // lid (slightly lighter band across the top)
    ctx.fillStyle = '#8a5628';
    ctx.fillRect(bx, by, w, h * 0.42);
    // lid top highlight
    ctx.fillStyle = '#a36c36';
    ctx.fillRect(bx, by, w, Math.max(1, h * 0.1));
    // gold trim: lid seam + bottom edge
    ctx.fillStyle = gold;
    ctx.fillRect(bx, by + h * 0.38, w, Math.max(1, h * 0.1));
    ctx.fillRect(bx, by + h - Math.max(1, h * 0.1), w, Math.max(1, h * 0.1));
    // vertical gold straps
    ctx.fillRect(bx + w * 0.14, by, Math.max(1, w * 0.09), h);
    ctx.fillRect(bx + w * 0.77, by, Math.max(1, w * 0.09), h);
    // lock plate
    ctx.fillStyle = lucky ? '#fff0a0' : '#e8c050';
    ctx.fillRect(cx - w * 0.09, by + h * 0.32, w * 0.18, h * 0.3);
    // keyhole
    ctx.fillStyle = '#4a2f15';
    ctx.fillRect(cx - w * 0.025, by + h * 0.42, w * 0.05, h * 0.13);
    ctx.restore();
  });

  // Ground food — drawn large so a rare bowl is easy to spot on the map.
  groundFood.forEach(f => {
    if (f.x + 1 < x0 || f.x > x1 || f.y + 1 < y0 || f.y > y1) return; // off-screen
    const px = offX + f.x * tw, py = offY + f.y * th;
    const foodSize = Math.round(tw * 0.95);
    drawSpriteC(f.sprite || 'food', px + tw/2, py + th/2, foodSize);
  });

  // Coin piles — a soft circular golden glow so loose gold catches the eye.
  groundGold.forEach(g => {
    if (g.x + 1 < x0 || g.x > x1 || g.y + 1 < y0 || g.y > y1) return; // off-screen
    const px = offX + g.x * tw, py = offY + g.y * th;
    glowUnder(px + tw/2, py + th/2, tw * 0.42, 'rgba(255,224,102,0.4)');
    if (spriteReady) drawSpriteC('coins', px + tw/2, py + th/2, itemSpritePx(tw));
  });

  // Vault key — pulses a warm gold glow and bobs gently so it catches the eye
  // across the floor (a layered halo + brighter core, the merchant-glow style).
  if (groundKey) {
    const gcx = offX + groundKey.x * tw + tw/2, gcy = offY + groundKey.y * th + th/2;
    const pulse = 0.5 + 0.5 * Math.sin((animNow() % 1400) / 1400 * Math.PI * 2);
    glowUnder(gcx, gcy, tw * (0.58 + 0.18 * pulse), `rgba(255,214,90,${0.30 + 0.26 * pulse})`);
    glowUnder(gcx, gcy, tw * (0.34 + 0.08 * pulse), `rgba(255,238,150,${0.42 + 0.30 * pulse})`);
    if (spriteReady) drawSpriteC('key', gcx, gcy - pulse * th * 0.06, itemSpritePx(tw));
  }

  // Express staircase inside an opened vault — a pixel down-stair ringed by a
  // pulsing violet glow so it reads apart from the normal (gold-ringed) descent.
  if (deepStair) {
    const px = offX + deepStair.x * tw, py = offY + deepStair.y * th;
    const pulse = 0.5 + 0.5 * Math.sin((animNow() % 1100) / 1100 * Math.PI * 2);
    glowUnder(px + tw/2, py + th/2, tw * (0.66 + 0.16 * pulse), `rgba(150,110,255,${0.34 + 0.26 * pulse})`);
    if (!(spriteReady && drawSprite('stairs_down', px, py, tw))) {
      ctx.fillStyle = '#160d24'; ctx.fillRect(px, py, tw, th);
    }
    const lw = Math.max(2, tw * 0.09), o = lw / 2 + 1;
    ctx.save();
    ctx.lineWidth = lw;
    ctx.strokeStyle = `rgba(176,124,255,${0.5 + 0.45 * pulse})`;
    ctx.shadowColor = 'rgba(150,110,255,0.9)';
    ctx.shadowBlur = tw * (0.18 + 0.22 * pulse);
    ctx.strokeRect(px + o, py + o, tw - o * 2, th - o * 2);
    ctx.restore();
  }

  // Merchant (roaming trader in bright robes) — never the town stand-in.
  if (merchant && !inTown) {
    const px = offX + merchant.x * tw, py = offY + merchant.y * th;
    drawActorShadow(px + tw/2, py + th*0.82, tw);
    // Heavy gold glow that pulses and fades out from behind them (the same radial
    // style as pickup glows). Two layered radial fades — a broad halo plus a
    // brighter core — read as a thicker, weightier glow than a single pass.
    const t = (animNow() % 1800) / 1800;
    const pulse = 0.5 + 0.5 * Math.sin(t * Math.PI * 2);
    const gcx = px + tw/2, gcy = py + th/2;
    glowUnder(gcx, gcy, tw * (0.92 + 0.14 * pulse), `rgba(255,198,66,${0.34 + 0.24 * pulse})`);
    glowUnder(gcx, gcy, tw * (0.54 + 0.10 * pulse), `rgba(255,226,138,${0.45 + 0.28 * pulse})`);
    // merchant sprite on top — a full pixel townsfolk walk sprite. It always has
    // bespoke art, so we never flash the static npc_shop atlas tile as a stand-in
    // while its (preloaded, tiny) sheet decodes: the glow/shadow already drew and
    // the sheet's onload repaints the moment it's ready.
    drawTownWalk('merchant', px + tw/2, py + th*0.9, Math.round(th * 1.6));
  }

  // Wandering Mystic (hooded pact-vendor with a purple mystical aura)
  if (mystic && !inTown) {
    const px = offX + mystic.x * tw, py = offY + mystic.y * th;
    drawActorShadow(px + tw/2, py + th*0.82, tw);
    // Heavy purple glow that pulses and fades — same layered radial style as the
    // merchant's, so the two roaming vendors read as a matched pair (gold vs
    // purple) and stand out boldly from the floor.
    const t = (animNow() % 2600) / 2600;
    const pulse = 0.5 + 0.5 * Math.sin(t * Math.PI * 2);
    const gcx = px + tw/2, gcy = py + th/2;
    glowUnder(gcx, gcy, tw * (0.92 + 0.14 * pulse), `rgba(150,78,255,${0.34 + 0.24 * pulse})`);
    glowUnder(gcx, gcy, tw * (0.54 + 0.10 * pulse), `rgba(196,134,255,${0.45 + 0.28 * pulse})`);
    // mystic sprite on top — a full hooded pixel walk sprite that always has
    // bespoke art, so we never flash the static npc_mage atlas tile as a stand-in
    // while its (preloaded) sheet decodes; the aura already drew and the sheet's
    // onload repaints the instant it's ready.
    drawTownWalk('mystic', px + tw/2, py + th*0.9, Math.round(th * 1.6));
  }

  // Town buildings + NPCs (only present in the safe hub). Buildings first so the
  // townsfolk and hero stand in front of them.
  if (inTown) drawTownWorld(offX, offY, tw, th, scale);   // walkable town: statue, keepers, gate, portal + prompt (no buildings)

  // Group active status effects by their target once, so each actor below reads
  // its own ailments in O(1) instead of re-filtering the whole list per draw.
  const statusByTarget = new Map();
  for (const s of statusEffects) {
    let arr = statusByTarget.get(s.target);
    if (!arr) statusByTarget.set(s.target, arr = []);
    arr.push(s);
  }

  // Enemies. Skip any whose footprint sits entirely outside the visible window
  // (with a 1-tile margin for auras/HP bars) — off-screen foes cost nothing to
  // not draw, which keeps frame times flat when a big pack is on the floor.
  enemies.forEach(e => {
    if (e.dead) return;
    const S = e.size || 1;                 // multi-tile footprint span
    if (e.x + S <= x0 - 1 || e.x >= x1 + 1 || e.y + S <= y0 - 1 || e.y >= y1 + 1) return;
    // Smooth render position: e.fx/fy is the footprint CENTRE (lazy-init in
    // updateActorRender), so the top-left of the footprint is (fx - S/2, fy - S/2).
    const efx = (e.fx == null ? e.x + S/2 : e.fx), efy = (e.fy == null ? e.y + S/2 : e.fy);
    const px = offX + (efx - S/2) * tw, py = offY + (efy - S/2) * th;
    const cw = S * tw, ch = S * th;        // full footprint in pixels
    const cx = px + cw/2;                   // footprint centre
    drawActorShadow(cx, py + ch*0.82, cw);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    // Status tint: green = poisoned, gold = stunned, orange = burning, blue = chilled.
    // One pass over this foe's statuses sets all six flags at once (six
    // .some(closure) calls per enemy per frame re-scanned the list and allocated
    // a closure each); foes with no statuses skip the loop entirely.
    const eStatus = statusByTarget.get(e);
    let poisoned = false, stunned = false, burning = false, cursed = false, chilled = false, charged = false;
    if (eStatus) for (const s of eStatus) {
      const eff = s.effect;
      if (eff === 'poison') poisoned = true;
      else if (eff === 'stun') stunned = true;
      else if (eff === 'burn') burning = true;
      else if (eff === 'vuln') cursed = true;
      else if (eff === 'chill') chilled = true;
      else if (eff === 'static') charged = true;
    }
    // Status tint → a cached pre-tinted sprite (was a per-frame ctx.filter, one of
    // the priciest 2D-canvas ops; the cached tile is pixel-identical). Priority
    // matches the old if/else chain: hit-flash first, then the elemental washes.
    let _tint = null;
    if (e.hitAt && Date.now() - e.hitAt < 110) _tint = 'hit';   // white hit-flash
    else if (burning) _tint = 'burn';
    else if (poisoned) _tint = 'poison';
    else if (cursed) _tint = 'vuln';
    else if (stunned) _tint = 'stun';
    else if (chilled) _tint = 'chill';
    else if (charged) _tint = 'static';
    // Pixel-art creature sprite (scaled to the footprint), falling back to glyph.
    // A brief attack lunge nudges only the sprite toward its target — the HP bar
    // and threat ring below stay anchored to the enemy's real tile.
    const _elunge = attackLungeOffset(e, tw, th);
    const _elx = _elunge ? _elunge.dx : 0, _ely = _elunge ? _elunge.dy : 0;
    // Spawn pop-in: a freshly-summoned foe scales up from small over ~300ms (ease-out)
    // so it erupts into being instead of blinking in fully-formed.
    const _bornK = e.spawnT ? Math.min(1, (Date.now() - e.spawnT) / 300) : 1;
    const _bornSc = 0.4 + 0.6 * (1 - (1 - _bornK) * (1 - _bornK));
    const _esz = Math.round(cw * (e.isBoss ? 1.0 : (e.isElite ? 0.96 : 0.9)) * _bornSc);
    const _scx = cx + _elx, _scy = py + ch/2 + th*0.02 + _ely;
    // Pop: a coloured halo marks elites/bosses/affixed foes so they stand out.
    // Painted as a cached radial glow behind the sprite (was a per-frame
    // shadowBlur on the sprite itself). Plain foes get no halo.
    const eAura = e.isBoss ? 'rgba(255,70,70,0.95)' : (e.isElite ? 'rgba(255,215,90,0.95)' : e.affixColor);
    if (eAura) glowUnder(_scx, _scy, cw * 0.6, eAura);
    let _drew = false;
    // Every regular monster draws from the generated monster sheet; bosses (and any
    // scripted foe carrying its own atlas key) keep their bespoke art.
    if (!e.isBoss && MONSTER_SPRITE_IDX[e.type] !== undefined) {
      if (monsterReady) {
        // These bespoke sprites are full characters (like the hero/NPC walk sheets),
        // so draw them at a matching scale, grounded a touch above centre — a plain
        // 0.9x tile read too small next to the ~1.7x hero.
        const _msz = Math.round(cw * (e.isElite ? 1.5 : 1.4) * _bornSc);
        const _mcy = _scy - th * 0.18;
        if (_tint) _drew = drawMonsterTintedC(e.type, _scx, _mcy, _msz, _tint);
        if (!_drew) _drew = drawMonsterC(e.type, _scx, _mcy, _msz);
      }
    } else if (e.isBoss && typeof BOSS_SPRITE_IDX === 'object' && BOSS_SPRITE_IDX[e.type] !== undefined) {
      if (bossReady) {
        // Fill the multi-tile footprint (cw already spans e.size tiles), a touch
        // grander and grounded slightly above centre.
        const _bsz = Math.round(cw * 1.12);
        const _bcy = _scy - th * 0.1;
        if (_tint) _drew = drawBossTintedC(e.type, _scx, _bcy, _bsz, _tint);
        if (!_drew) _drew = drawBossC(e.type, _scx, _bcy, _bsz);
      }
    } else {
      const _espr = enemySprite(e);
      if (spriteReady && _espr) {
        if (_tint) _drew = drawSpriteTintedC(_espr, _scx, _scy, _esz, _tint);
        if (!_drew) _drew = drawSpriteC(_espr, _scx, _scy, _esz);   // tint not ready → plain sprite
      }
    }
    if (!_drew) {
      // No atlas tile (still loading, or a foe with no sprite): a coloured square
      // placeholder with the foe's initial — never an emoji.
      ctx.save();
      if (_tint) ctx.filter = TINT_FILTERS[_tint];
      const _mn = (typeof MONSTERS === 'object' && MONSTERS[e.type] && MONSTERS[e.type].name) || e.name || '?';
      drawMonsterSquare(_scx, _scy, _esz, e.mColor || ICON_EMPTY_COLOR, _mn.charAt(0).toUpperCase());
      ctx.restore();
    }

    // ── PERSISTENT BOSS-BUFF AURA ── a shimmering blue ward while shielded and a
    // pulsing red rage outline while enraged/berserk, so the active power state
    // stays visible for its whole duration — not just the one-frame cast puff.
    if (e.isBoss || e.isElite) {
      if (e.shieldT > 0) { const wp = 0.5 + 0.5 * Math.sin(animNow() / 300); ringGlow(_scx, _scy, cw * (0.62 + 0.06 * wp), '150,216,255', 0.26 + 0.16 * wp); }
      if (e.enraged || e.berserkT > 0) { const rp = 0.5 + 0.5 * Math.sin(animNow() / 180); glowUnder(_scx, _scy, cw * (0.58 + 0.08 * rp), `rgba(255,70,45,${(0.2 + 0.18 * rp).toFixed(3)})`); }
    }

    // ── THREAT TELEGRAPH ── make "who can hit me, from where, right now" legible.
    // Ring any foe that can strike the hero on its next move (melee adjacent, or
    // ranged with line of sight in range); for ranged threats also draw a faint
    // lane from the foe to the hero so off-screen chip damage is never a mystery.
    if (!inTown && !e.isGoblin) {
      const ebeh = BEHAVIORS[e.behavior] || BEHAVIORS.chaser;
      const edist = Math.abs(e.x - player.x) + Math.abs(e.y - player.y);
      const isRanged = ebeh.ranged || (e.size || 1) > 1;
      const inRange = isRanged && edist <= (ebeh.range || 4) && hasLineToPlayer(e);
      const threatens = edist <= 1 || inRange;
      if (threatens) {
        const tp = 0.5 + 0.5 * Math.sin(animNow() / 380);   // calm, slow pulse
        const fcx = cx, fcy = py + ch / 2;
        // Threat marker: a soft red glow ring that fades out at both edges (no
        // hard outline), echoing the radial-glow style used elsewhere. Cached
        // ring texture blitted at the pulsing alpha — no per-frame gradient.
        const rr = cw * 0.52, a = 0.20 + 0.16 * tp;
        ringGlow(fcx, fcy, rr, '255,70,58', a);
      }
    }

    // Goblin loot tag or bounty marker, floated above. (Affixes show as the
    // coloured aura above — no floating icon.)
    if (e.questTarget || e.isGoblin) {
      const tagSprite = e.questTarget ? 'ic_target' : 'ic_money';
      if (spriteReady) drawSpriteC(tagSprite, cx, py - th*0.02, Math.round(tw * 0.4));
    }

    // HP bar (spans the whole footprint)
    if (e.hp < e.maxHp) {
      const bw = cw - 2, bh = Math.max(2, th * 0.14);
      ctx.fillStyle = '#000';
      ctx.fillRect(px, py, bw+2, bh+1);
      ctx.fillStyle = '#3a0000';
      ctx.fillRect(px+1, py, bw, bh);
      ctx.fillStyle = e.isBoss ? '#ff6622' : (e.isElite ? '#ffaa22' : '#ff3344');
      ctx.fillRect(px+1, py, bw * (e.hp/e.maxHp), bh);
    }

    // Targeting reticle — a red crosshair over the foe the hero's auto-attack is
    // locked onto (optional; toggled in Settings → Visuals). Anchored to the real
    // tile centre like the HP bar / threat ring, so a lunge doesn't drag it.
    if (showCrosshair && !inTown && e === autoAttackTarget)
      drawTargetCrosshair(cx, py + ch / 2, cw);
  });

  // Grave marker — your dropped satchel, waiting to be reclaimed. Drawn with the
  // grave tile plus a bright pulsing gold halo and an expanding ring so
  // it visibly glows and the player knows to walk over and grab it.
  if (graveMarker) {
    const gpx = offX + graveMarker.x * tw, gpy = offY + graveMarker.y * th;
    const cx = gpx + tw / 2, cy = gpy + th / 2 + th * 0.02;
    const t = animNow() / 300;
    const gsp = 0.5 + 0.5 * Math.sin(t);
    // Bright pulsing glow behind the grave sprite — a soft radial fade (the same
    // style as pickups), not a boxy shadow halo. Doubled up so it really beams.
    glowUnder(cx, cy, tw * (0.75 + 0.18 * gsp), `rgba(255,200,70,${0.4 + 0.25 * gsp})`);
    glowUnder(cx, cy, tw * (0.42 + 0.12 * gsp), `rgba(255,240,160,${0.6 + 0.3 * gsp})`);
    ctx.save();
    // Two staggered expanding "come grab me" rings that fade as they grow — an
    // animated beacon so the reclaim spot is impossible to miss.
    for (let r = 0; r < 2; r++) {
      const ringT = ((animNow() + r * 600) % 1200) / 1200;
      ctx.strokeStyle = `rgba(255,215,90,${0.6 * (1 - ringT)})`;
      ctx.lineWidth = Math.max(1.5, tw * 0.06);
      ctx.beginPath();
      ctx.arc(cx, cy, tw * (0.3 + 0.4 * ringT), 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
    if (spriteReady) drawSpriteC('feat_grave', cx, cy, charSpritePx(tw));
    // Bobbing downward chevron floating above the grave — a clear "pick this up"
    // beacon that points right at your lost loot. Drawn procedurally (UI marker).
    ctx.save();
    const bob = Math.sin(animNow() / 250) * th * 0.08;
    const ay = gpy - th * 0.18 + bob, aw = tw * 0.26, ah = th * 0.2;
    ctx.fillStyle = `rgba(255,225,110,${0.75 + 0.25 * gsp})`;
    ctx.strokeStyle = 'rgba(90,55,0,0.6)';
    ctx.lineWidth = Math.max(1, tw * 0.03);
    ctx.beginPath();
    ctx.moveTo(cx - aw, ay);
    ctx.lineTo(cx + aw, ay);
    ctx.lineTo(cx, ay + ah);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }

  // Rainbow conquest gate — the animated portal to the next difficulty.
  if (nextDiffPortal) {
    const ppx = offX + nextDiffPortal.x * tw + tw / 2, ppy = offY + nextDiffPortal.y * th + th / 2;
    drawPortal(ppx, ppy, tw, 'rainbow');
  }
  // Graduation escape portal — the blue town portal that opens on the first Floor-5 kill.
  if (gradPortal) {
    const gpx = offX + gradPortal.x * tw + tw / 2, gpy = offY + gradPortal.y * th + th / 2;
    drawPortal(gpx, gpy, tw, 'town');
  }

  // Quest markers — NPCs, objectives, and pickups, each ringed to stand out.
  if (quest) {
    const sp = 0.5 + 0.5*Math.sin(animNow()/300);
    const drawMark = (mx, my, ring, sprite, big) => {
      const dx0 = offX + mx * tw, dy0 = offY + my * th;
      // No backing circle — a soft radial glow (matching pickups) keeps the
      // marker readable instead of a boxy shadow halo.
      glowUnder(dx0 + tw/2, dy0 + th/2 + th*0.02, tw * (0.4 + 0.04*sp), `rgba(${ring},${0.42 + 0.2*sp})`);
      if (sprite && spriteReady) {
        // A quest CHARACTER (giver / lost pet) draws at foe scale, raised so its
        // feet rest on the tile — matching the hero and enemies rather than a small
        // pickup. Objective pickups keep the smaller item size.
        if (big) drawSpriteC(sprite, dx0 + tw/2, dy0 + th*0.5 - th*0.16, Math.round(tw * 1.4));
        else drawSpriteC(sprite, dx0 + tw/2, dy0 + th/2 + th*0.02, charSpritePx(tw));
      }
    };
    const GREEN = '80,220,120', GOLD = '255,210,80';
    if (quest.npc) {
      // Lost-pet quests show the animal sprite; everyone else the quest-giver.
      const npcSprite = quest.npc.sprite || 'npc_quest';
      // Draw at the smooth render position (fx/fy) so a follower glides between
      // tiles; fall back to the logic cell on the very first frame before
      // updateActorRender has seeded fx/fy.
      const nfx = quest.npc.fx != null ? quest.npc.fx : quest.npc.x;
      const nfy = quest.npc.fy != null ? quest.npc.fy : quest.npc.y;
      drawMark(nfx, nfy, GREEN, npcSprite, true);
      const dx0 = offX + nfx * tw, dy0 = offY + nfy * th;
      const following = quest.type === 'escort' && quest.npc.following;
      // A pixel arrow marks "follow me" (up) vs "quest here" (down). Float it
      // clear ABOVE the giver's head, not over the face: the giver draws big
      // (side tw*1.4, centred at dy0 + th*0.34 — see drawMark), so its top sits
      // ~0.36·th above dy0; park the arrow just over that top with a small gap.
      const npcSz = Math.round(tw * 1.4), arrowSz = Math.round(tw * 0.34);
      const npcTop = dy0 + th*0.34 - npcSz/2;
      if (spriteReady) drawSpriteC(following ? 'ic_up' : 'ic_down', dx0 + tw/2, npcTop - arrowSz/2 - th*0.04, arrowSz);
    }
    if (quest.item && !quest.hasItem) drawMark(quest.item.x, quest.item.y, GOLD, 'q_relic');
    if (quest.spot) drawMark(quest.spot.x, quest.spot.y, GOLD, quest.spot.sprite);
    if (quest.markers) quest.markers.forEach(m => {
      if (quest.type === 'beacons') {
        // Beacons stay on the floor once lit — a cold beacon while dormant, a
        // blazing one after you light it (instead of vanishing like gathered herbs).
        drawMark(m.x, m.y, GOLD, m.done ? 'q_beacon_lit' : 'q_beacon');
      } else if (!m.done) {
        drawMark(m.x, m.y, GOLD, 'q_mushroom');
      }
    });
  }

  // Summoned minions — autonomous allies, drawn with a soft coloured aura and a
  // thin lifespan bar so the player can read how long each will last.
  minions.forEach(m => {
    if (m.x + 1 < x0 || m.x > x1 || m.y + 1 < y0 || m.y > y1) return; // off-screen (1-tile margin covers aura/lunge)
    const mx = offX + m.x * tw, my = offY + m.y * th;
    drawActorShadow(mx + tw/2, my + th*0.82, tw);
    ctx.save();
    if (m.hitAt && Date.now() - m.hitAt < 110) ctx.filter = 'brightness(2.2)';
    ctx.shadowColor = m.color; ctx.shadowBlur = Math.max(2, tw * (m.strong ? 0.3 : 0.2));
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    // Pixel minion sprite (scaled up a touch for "strong" summons), referenced
    // directly by the minion's kind — no emoji.
    const mSprite = MINION_SPRITE[m.kind];
    const mSz = Math.max(charSpritePx(tw), Math.round(tw * (m.strong ? 0.92 : 0.82)));
    // Attack lunge nudges the minion sprite toward its target (lifespan bar stays put).
    const mLunge = attackLungeOffset(m, tw, th);
    const mlx = mLunge ? mLunge.dx : 0, mly = mLunge ? mLunge.dy : 0;
    if (mSprite) drawSpriteC(mSprite, mx + tw/2 + mlx, my + th/2 + th*0.02 + mly, mSz);
    // Skeleton archer carries a bow, drawn at its side the same way the hero's
    // equipped bow is rendered (whole-number scale so the diagonals stay clean).
    if (m.kind === 'skelarcher' && spriteReady && SPRITE_IDX['w_bow'] !== undefined) {
      drawSpriteC('w_bow', mx + tw * 0.70 + mlx, my + th * 0.58 + mly, Math.round(tw * 0.42));
    }
    ctx.restore();
    // Lifespan bar (cyan) so the temporary nature reads at a glance.
    const bw = tw - 4, bh = Math.max(2, th * 0.1);
    const frac = Math.max(0, Math.min(1, m.ttl / (m.ttlMax || 18)));
    ctx.fillStyle = '#000'; ctx.fillRect(mx+2, my+1, bw+1, bh+1);
    ctx.fillStyle = '#2b6f8f'; ctx.fillRect(mx+2, my+1, bw, bh);
    ctx.fillStyle = '#5fd0ff'; ctx.fillRect(mx+2, my+1, bw * frac, bh);
  });

  // ── Traps & projectiles (real-time hazards) ──
  traps.forEach(tr => {
    if (tr.x + 1 < x0 || tr.x > x1 || tr.y + 1 < y0 || tr.y > y1) return;
    const tcx = offX + (tr.x + 0.5) * tw, tcy = offY + (tr.y + 0.5) * th;
    ctx.save();
    if (tr.kind === 'arrow') {
      // Emitter recessed into the wall behind it; brightens just before it fires.
      const warm = Math.max(0, 1 - tr.cd / 0.6);
      const ex = tcx - tr.dx * tw * 0.42, ey = tcy - tr.dy * th * 0.42;
      ctx.fillStyle = 'rgba(60,52,44,0.92)';
      ctx.beginPath(); ctx.arc(ex, ey, tw * 0.13, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = `rgba(255,214,128,${0.25 + 0.6 * warm})`;
      ctx.beginPath(); ctx.arc(ex, ey, tw * 0.06, 0, Math.PI * 2); ctx.fill();
    } else if (tr.kind === 'fire') {
      ctx.fillStyle = 'rgba(38,28,22,0.8)';
      ctx.fillRect(tcx - tw * 0.32, tcy - th * 0.32, tw * 0.64, th * 0.64);
      const warming = !tr.on && tr.t > tr.period * (1 - tr.onFrac) - 0.5;
      if (tr.on) {
        const f = 0.6 + 0.4 * Math.sin(animNow() / 70 + tr.x);
        ctx.shadowColor = '#ff6a22'; ctx.shadowBlur = tw * 0.4;
        ctx.fillStyle = `rgba(255,${Math.round(100 + 80 * f)},40,0.88)`;
        ctx.beginPath(); ctx.arc(tcx, tcy, tw * 0.27 * f, 0, Math.PI * 2); ctx.fill();
      } else if (warming) {
        ctx.fillStyle = `rgba(255,120,40,${0.18 + 0.2 * Math.abs(Math.sin(animNow() / 90))})`;
        ctx.beginPath(); ctx.arc(tcx, tcy, tw * 0.13, 0, Math.PI * 2); ctx.fill();
      }
    }
    ctx.restore();
  });
  const _projNow = Date.now();
  projectiles.forEach(p => {
    const ppx = offX + p.x * tw, ppy = offY + p.y * th;     // bolts stay smooth (fast hazards)
    const m = Math.hypot(p.vx, p.vy) || 1, ux = p.vx / m, uy = p.vy / m; // forward
    // Each bolt renders as an element-tinted sprite chosen by its `kind` (arrow,
    // magic orb, fireball, ice shard, spark, venom glob…) — see drawProjectileKind.
    ctx.save();
    drawProjectileKind(p, ppx, ppy, ux, uy, tw, _projNow);
    ctx.restore();
  });

  // Player (smooth float position). While walking THROUGH a teleporter the hero is
  // drawn at the pad it LEFT while it's swallowed (spun down into the swirl), then at
  // the partner pad as it emerges — decoupled from the follow-cam pan set up above.
  const warpHero = warpFx ? warpFrameAt(warpFx.t, warpFx.dur) : null;
  const heroWX = warpHero ? (warpHero.atDest ? warpFx.dx : warpFx.sx) : player.fx;
  const heroWY = warpHero ? (warpHero.atDest ? warpFx.dy : warpFx.sy) : player.fy;
  const px = offX + (heroWX - 0.5) * tw, py = offY + (heroWY - 0.5) * th;
  // Town-portal teleport underway? Pull this frame's fade / lift / beam envelope so
  // the hero fades and rides the beam up off the map (departure) or drops in and
  // solidifies out of the pillar (arrival). null the rest of the time.
  const fxHero = portalTransiting() ? portalFrame(portalFx.dir, portalFx.t, portalFx.dur) : null;
  const heroAlpha = fxHero ? fxHero.heroAlpha : 1;
  const heroLift = fxHero ? fxHero.heroLift * th * 2.6 : 0;   // px risen up the beam / dropping into place
  const teleFx = fxHero || warpHero;   // either kind of teleport dims the hero and hides its bars/aura
  // Soft under-the-feet contact shadow grounds the hero (no coloured backing
  // circle — matching the de-cluttered enemies). It fades (and shrinks, mid-warp)
  // out with the hero.
  ctx.save();
  if (fxHero) ctx.globalAlpha = heroAlpha;
  else if (warpHero) ctx.globalAlpha = warpHero.heroAlpha;
  drawActorShadow(px + tw/2, py + th*0.82, tw * (warpHero ? Math.max(0.05, warpHero.heroScale) : 1));
  ctx.restore();
  // Golden completion aura, under the hero, when any worn set is complete (hidden
  // mid-teleport — the beam / portal swirl owns the hero's light then).
  if (!teleFx && completedSets().length) drawSetAura(px + tw/2, py + th*0.6, tw);
  // Composite the hero — a class-specific pixel adventurer that visibly carries
  // its equipped weapon type at its side. A quick attack lunge nudges the sprite
  // toward its target while leaving the stamina bar / portal glow below in place.
  // Mid-town-teleport the hero fades (heroAlpha) and rides up / drops down the beam
  // (heroLift); mid-map-warp it spins and scales into / out of the pad (invisible
  // through the camera pan, when heroScale is 0).
  const pLunge = attackLungeOffset(player, tw, th);
  if (warpHero) {
    if (warpHero.heroScale > 0.01) {
      ctx.save();
      ctx.globalAlpha = warpHero.heroAlpha;
      const hcx = px + tw / 2, hcy = py + th / 2;
      ctx.translate(hcx, hcy);
      ctx.rotate(warpHero.spin);
      ctx.scale(warpHero.heroScale, warpHero.heroScale);
      ctx.translate(-hcx, -hcy);
      drawHeroSprite(px, py, tw, th, scale);
      ctx.restore();
    }
  } else {
    ctx.save();
    if (fxHero) ctx.globalAlpha = heroAlpha;
    drawHeroSprite(px + (pLunge ? pLunge.dx : 0), py - heroLift + (pLunge ? pLunge.dy : 0), tw, th, scale);
    ctx.restore();
  }
  // Vital bars under the hero. With the Hero Bars setting ON, red Health and
  // blue Mana are ALWAYS visible (even at full — never blinking away); the
  // stamina bar (amber) still pops up only while stamina isn't full, so it
  // stays out of the way at rest. They stack just under the hero's feet, with
  // the stamina bar at its usual spot. Hidden while teleporting — the hero
  // isn't really standing on the floor then.
  if (!teleFx) {
    const bw = tw * 0.8, bh = Math.max(2, th * 0.07), bx = px + (tw - bw) / 2;
    const bars = [];   // top → bottom
    if (showHeroBars)
      bars.push({ frac: player.hp / player.maxHp, track: '#3a1013', fill: PALETTE.hp });
    if (showHeroBars && player.maxMp > 0)
      bars.push({ frac: player.mp / player.maxMp, track: '#102138', fill: PALETTE.mp });
    if (player.stamina < player.maxStamina - 0.5)
      bars.push({ frac: player.stamina / player.maxStamina, track: '#4a3a12', fill: '#ffcf52' });
    const rh = bh + 2;
    let by = py + th * 0.9 - (bars.length - 1) * rh;   // bottom bar sits at the old stamina spot
    for (const b of bars) {
      ctx.fillStyle = '#000'; ctx.fillRect(bx - 1, by - 1, bw + 2, bh + 2);
      ctx.fillStyle = b.track; ctx.fillRect(bx, by, bw, bh);
      ctx.fillStyle = b.fill; ctx.fillRect(bx, by, bw * Math.max(0, Math.min(1, b.frac)), bh);
      by += rh;
    }
  }

  // Town-portal CHARGING AURA: blue energy gathers over the hero for the whole
  // channel (0 → 1 as it completes), with the remaining-seconds count floating above
  // so the progress (and the "don't get hit" stakes) read at a glance.
  if (portalChanneling()) {
    const prog = chargeProgress(portalCharge, PORTAL_CHANNEL_SECS);
    drawPortalCharge(px + tw / 2, py + th / 2, tw, prog);
    ctx.save();
    ctx.font = `bold ${Math.max(12, Math.round(tw * 0.34))}px ${uiFontCss}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const ny = py - th * 0.18;
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 3;
    const portalSecsLeft = Math.ceil(portalCharge);
    ctx.strokeText(portalSecsLeft, px + tw / 2, ny);
    ctx.fillStyle = '#bfe8ff';
    ctx.fillText(portalSecsLeft, px + tw / 2, ny);
    ctx.restore();
  } else if (fxHero) {
    // TELEPORT BEAM: shoots up off the map (departure) or stabs in and recedes as the
    // hero materializes (arrival). Anchored at the hero's feet so it reads as the
    // shaft of light they ride. Drawn last so it engulfs the fading/forming hero.
    drawPortalBeam(px + tw / 2, py + th * 0.92, tw, H, fxHero, portalFx.t);
  } else if (warpHero) {
    // PORTAL SWALLOW / EMERGE: a purple vortex centred on the pad that pulls the hero
    // in (absorb) or flings it out (emerge). Drawn last so it engulfs the hero.
    drawPortalSwallow(px + tw / 2, py + th / 2, tw, warpHero, warpFx.t);
  }

  // Tall decor (trees) occludes actors standing behind it, with a tinted
  // silhouette over the covered part so the hero/foes stay trackable.
  drawDecorOcclusion(offX, offY, tw, th, x0, y0, x1, y1, scale);   // hero + town keepers get proper depth behind trees (silhouetted), not drawn on top
  if (previewDrawSolids) { ctx.save(); ctx.globalAlpha = 0.38; ctx.fillStyle = '#ff2020'; for (const k in furnitureMap) { const c = k.split(','), sx = +c[1], sy = +c[0]; ctx.fillRect(offX + sx * tw, offY + sy * th, tw, th); } ctx.restore(); }

  // Player status effects are surfaced as full-screen coloured halos (see
  // updateHaloVignette), not as little icons over the hero sprite.

  // Combat particles — hit sparks / blood that burst, drift, and fade. A single
  // in-place pass compacts expired sparks out (recycling them into the pool) and
  // draws the survivors — no per-frame array copy or save/restore per spark; only
  // globalAlpha changes, so one reset after the loop restores the context.
  const pnow = Date.now();
  let pAlive = 0;
  for (let i = 0; i < particles.length; i++) {
    const p = particles[i];
    const e = pnow - p.born;
    if (e >= p.life) { _particlePool.push(p); continue; }   // expired → recycle
    particles[pAlive++] = p;
    const t = e / p.life, f = e / 16;
    const wx = p.x + p.vx * f, wy = p.y + p.vy * f + 0.00006 * e * f; // light gravity
    const px = offX + wx * tw, py = offY + wy * th;
    const s = Math.max(1, tw * 0.1 * (1 - t * 0.6));
    ctx.globalAlpha = Math.max(0, 1 - t);
    ctx.fillStyle = p.color;
    ctx.fillRect(px - s/2, py - s/2, s, s);
  }
  particles.length = pAlive;
  ctx.globalAlpha = 1;

  // Attack / spell / monster-ability animations (slash arcs, novas, beams, chains,
  // impacts, auras…) paint over the world with the cinematics, beneath the damage
  // numbers so hits stay readable.
  drawAttackFx(offX, offY, tw, th);

  // Ultimate-spell cinematics (meteor slam, frost nova, storm…) paint over the
  // world but beneath the floating damage numbers so hits stay readable.
  drawUltimateFx(offX, offY, tw, th);

  // Floating damage numbers — compacted in place with a write index (the old
  // per-frame .filter allocated a fresh array every frame).
  const now = Date.now();
  let ftAlive = 0;
  for (let i = 0; i < floatingTexts.length; i++) {
    const ft = floatingTexts[i];
    if (now - ft.start >= ft.duration) continue;   // expired → drop
    floatingTexts[ftAlive++] = ft;
    const t = (now - ft.start) / ft.duration;
    const px = offX + ft.x * tw + tw / 2;
    const py = offY + ft.y * th - t * tw * 0.8;
    const alpha = 1 - t * t;
    ctx.save();
    ctx.globalAlpha = Math.max(0, alpha);
    const fsz = Math.max(12, Math.round(tw * 0.28 * (ft.size || 1)));
    ctx.font = `${(ft.size || 1) > 1 ? 'bold ' : ''}${fsz}px ${uiFontCss}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.lineWidth = 2;
    // Gold floaters lead with the coin sprite (matching the HUD/menus). Draw it to
    // the left of the number and shift the number right so the pair stays centred
    // on the spawn point and reads as one "coin + amount" group.
    const coinOk = ft.coin && spriteReady && SPRITE_IDX['ic_money'] !== undefined;
    if (coinOk) {
      const cs = Math.max(16, Math.round(fsz * 1.15));
      const gap = Math.max(1, Math.round(fsz * 0.15));
      // measureText is costly per frame, so the width is cached on the floater
      // and only re-measured if its font changes (e.g. the canvas was resized).
      if (ft._mFont !== ctx.font) { ft._mFont = ctx.font; ft._mW = ctx.measureText(ft.text).width; }
      const twd = ft._mW;
      const left = px - (cs + gap + twd) / 2;
      const tcx = left + cs + gap + twd / 2;
      ctx.strokeText(ft.text, tcx, py);
      ctx.fillStyle = ft.color;
      ctx.fillText(ft.text, tcx, py);
      drawSpriteC('ic_money', left + cs / 2, py, cs);
    } else {
      ctx.strokeText(ft.text, px, py);
      ctx.fillStyle = ft.color;
      ctx.fillText(ft.text, px, py);
    }
    ctx.restore();
  }
  floatingTexts.length = ftAlive;

  // Atmospheric colour wash for this floor, if any.
  if (floorTint) {
    ctx.fillStyle = floorTint;
    ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  }

  // Difficulty wash: each harder dungeon tier bleeds a little more red into the
  // world — subtle on Hardened, oppressive (but still readable) in Endless. Town
  // is a safe haven, so it stays untinted.
  if (!inTown) {
    const dTint = diffMeta().tint;
    if (dTint > 0) {
      ctx.fillStyle = `rgba(196,22,28,${dTint})`;
      ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
    }
  }

  // Painterly vignette: a warm overhead light fading to shadowed edges, for
  // that Golden Sun / Tactics diorama feel.
  const cw = ctx.canvas.width, ch = ctx.canvas.height;
  if (!_vignetteGrad || _vignetteW !== cw || _vignetteH !== ch) {
    _vignetteW = cw; _vignetteH = ch;
    _vignetteGrad = ctx.createRadialGradient(cw/2, ch*0.42, Math.min(cw, ch)*0.18, cw/2, ch*0.5, Math.max(cw, ch)*0.72);
    _vignetteGrad.addColorStop(0, 'rgba(255,236,190,0.06)');
    _vignetteGrad.addColorStop(0.55, 'rgba(0,0,0,0)');
    _vignetteGrad.addColorStop(1, 'rgba(8,6,18,0.55)');
  }
  ctx.fillStyle = _vignetteGrad;
  ctx.fillRect(0, 0, cw, ch);

  // Edge indicators pointing at off-screen points of interest — the down-stairs
  // (gold) and any remaining foes (small red). Drawn over the vignette so they
  // stay bright even at the darkened border.
  drawStairsArrow(offX, offY, tw, th, W, H);
  drawMonsterArrows(offX, offY, tw, th, W, H);

  drawMinimap();
}

// ── MINIMAP ──────────────────────────────────────────────────────────────────
// A small top-down sketch of the whole current floor, painted into the #minimap
// canvas each frame. The canvas is sized to one device pixel per tile and CSS
// scales that box up with crisp, pixelated edges. Walls / floor / liquids /
// specials are read straight from mapData (same tile values gameState()'s ASCII
// map uses); the hero, foes, allies, chests, coins, NPCs and the stairs are
// dotted on top so the floor's shape and where everything sits read at a glance.
// Hidden in town and before a floor exists. Tap it to collapse to a small corner
// thumbnail (and tap again to expand); the choice is remembered.
let _mmCanvas = null, _mmCtx = null;
// Static terrain layer cache. Re-rasterizing every tile of the whole floor each
// frame was the minimap's entire cost, but the terrain rarely changes — so it's
// painted once into an offscreen canvas and blitted per frame. The cache key is
// the floor identity + pixel size + a cheap rolling hash of mapData, because
// terrain CAN change mid-floor (smashed cracked walls, unlocked vault doors,
// spent shrines/fountains, boss wall-digging): any tile edit changes the hash
// and forces a rebuild, so the output stays pixel-identical. The dynamic dots
// (hero/foes/allies/loot/NPCs) keep drawing on top every frame.
let _mmTerrain = null, _mmTerrainKey = '';
function _mmTerrainHash() {
  let h = 0;
  for (let y = 0; y < MAP_H; y++) {
    const row = mapData[y]; if (!row) continue;
    for (let x = 0; x < MAP_W; x++) h = (h * 31 + row[x]) | 0;
  }
  return h;
}
let minimapCollapsed = false;
try { minimapCollapsed = localStorage.getItem('dungeonLootMiniCollapsed') === '1'; } catch (e) {}
function toggleMinimap() {
  minimapCollapsed = !minimapCollapsed;
  const el = document.getElementById('minimap');
  if (el) el.classList.toggle('collapsed', minimapCollapsed);
  try { localStorage.setItem('dungeonLootMiniCollapsed', minimapCollapsed ? '1' : '0'); } catch (e) {}
  settingsChanged();
}
const MM_TCOL = {
  0:  '#5b566f',  // floor
  1:  '#272233',  // wall
  2:  '#7be06a',  // stairs down — the goal, bright green
  3:  '#5fd0c2',  // fountain
  5:  '#c79bff',  // shrine
  6:  '#3a6fb0',  // water
  7:  '#d6602f',  // lava
  9:  '#e069d6',  // teleporter
  10: '#2f2940',  // cracked wall
  11: '#9a6a3a',  // door
  12: '#6fc4ff',  // stairs up
};
function drawMinimap() {
  const el = _mmCanvas || (_mmCanvas = document.getElementById('minimap'));
  if (!el) return;
  // The minimap is a purchased HUD piece (the Cartographer's Map) — until it's owned,
  // keep the corner sketch dark. Nothing meaningful to show either (town, title
  // screen, between floors): hide it.
  if (!hudOwned('minimap') || inTown || !Array.isArray(mapData) || !mapData.length || !MAP_W || !MAP_H) {
    if (el.style.display !== 'none') el.style.display = 'none';
    // The touch header reserves the minimap's top-left slot; when it's absent that
    // slot is dead space, so flag it off (CSS re-centres the remaining readouts).
    if (document.body.classList.contains('hud-mm-on')) document.body.classList.remove('hud-mm-on');
    return;
  }
  if (el.style.display === 'none') el.style.display = 'block';
  if (!document.body.classList.contains('hud-mm-on')) document.body.classList.add('hud-mm-on');
  // Keep the collapsed thumbnail state in sync with the saved preference.
  if (el.classList.contains('collapsed') !== minimapCollapsed) el.classList.toggle('collapsed', minimapCollapsed);
  const PX = 3;                              // device pixels per tile
  const w = MAP_W * PX, h = MAP_H * PX;
  if (el.width !== w) el.width = w;           // a resize also clears, so only when it changes
  if (el.height !== h) el.height = h;
  const m = _mmCtx || (_mmCtx = el.getContext('2d'));
  m.clearRect(0, 0, w, h);

  // Terrain layer — blitted from the offscreen cache, rebuilt only when the
  // floor, the canvas size, or any terrain tile changes (see _mmTerrainHash).
  const tKey = floorSerial + ':' + w + 'x' + h + ':' + _mmTerrainHash();
  if (!_mmTerrain || _mmTerrainKey !== tKey) {
    _mmTerrainKey = tKey;
    if (!_mmTerrain) _mmTerrain = document.createElement('canvas');
    if (_mmTerrain.width !== w) _mmTerrain.width = w;
    if (_mmTerrain.height !== h) _mmTerrain.height = h;
    const tm = _mmTerrain.getContext('2d');
    tm.clearRect(0, 0, w, h);
    for (let y = 0; y < MAP_H; y++) {
      const row = mapData[y]; if (!row) continue;
      for (let x = 0; x < MAP_W; x++) {
        const c = MM_TCOL[row[x]];
        if (!c) continue;
        tm.fillStyle = c;
        tm.fillRect(x * PX, y * PX, PX, PX);
      }
    }
  }
  m.drawImage(_mmTerrain, 0, 0);

  // Markers, drawn a touch larger than a tile so they pop against the floor.
  const dot = (x, y, color, s) => {
    if (x == null || y == null) return;
    m.fillStyle = color;
    m.fillRect(Math.round(x * PX + PX / 2 - s / 2), Math.round(y * PX + PX / 2 - s / 2), s, s);
  };
  (groundGold || []).forEach(g => dot(g.x, g.y, '#caa83a', PX));                 // coins (dim gold)
  (groundItems || []).forEach(g => dot(g.x, g.y, '#fff3c4', PX + 1));            // chests (bright)
  (minions || []).forEach(a => dot(a.x, a.y, '#67d6ff', PX));                    // allies
  (enemies || []).forEach(e => { if (e && !e.dead) dot(e.x, e.y, e.isBoss ? '#ff3b3b' : '#ff5a5a', e.isBoss ? PX + 1 : PX); });
  if (merchant) dot(merchant.x, merchant.y, '#69e07a', PX + 1);
  if (mystic)   dot(mystic.x, mystic.y, '#9a8bff', PX + 1);
  if (quest && quest.npc) dot(quest.npc.x, quest.npc.y, '#ffd24b', PX + 1);
  // Hero last so it's always on top, ringed white so it reads on a busy floor.
  if (player) {
    dot(player.x, player.y, '#fff', PX + 1);
    dot(player.x, player.y, '#ffd24b', PX);
  }
}

// ── OFF-SCREEN STAIRS ARROW ───────────────────────────────────────────────────
// The down-stairs cell for the current floor, found once and cached by
// floorSerial — the exit never moves within a floor, so we scan mapData at most
// once per floor instead of every frame.
let _stairsDownCell = null, _stairsDownSerial = -1;
function stairsDownCell() {
  if (_stairsDownSerial === floorSerial) return _stairsDownCell;
  _stairsDownSerial = floorSerial;
  _stairsDownCell = null;
  if (Array.isArray(mapData)) {
    for (let y = 0; y < MAP_H && !_stairsDownCell; y++) {
      const row = mapData[y]; if (!row) continue;
      for (let x = 0; x < MAP_W; x++) {
        if (row[x] === 2) { _stairsDownCell = { x, y }; break; }
      }
    }
  }
  return _stairsDownCell;
}

// When the down-stairs sit outside the visible map, a small arrow rides the edge
// of the map panel — always on the ray from the hero to the stairs, so it sits
// exactly between them and points straight at the exit. It slides radially around
// the border as you move and vanishes the moment the stairs scroll into view.
// Every position is derived from the live camera (tile size `tw`, canvas size),
// so it tracks resolution, window size and zoom automatically.
function drawStairsArrow(offX, offY, tw, th, W, H) {
  if (!showStairsArrow) return;
  if (inTown || !player || !Array.isArray(mapData) || !mapData.length) return;
  const s = stairsDownCell();
  if (!s) return;

  // If any part of the stairs tile is on screen the player can already see it —
  // no arrow needed.
  const tileL = offX + s.x * tw, tileT = offY + s.y * th;
  if (tileL < W && tileL + tw > 0 && tileT < H && tileT + th > 0) return;

  // Hero and stairs centres, in canvas pixels, and the unit direction between.
  const psx = offX + player.fx * tw, psy = offY + player.fy * th;
  const stx = offX + (s.x + 0.5) * tw, sty = offY + (s.y + 0.5) * th;
  let dx = stx - psx, dy = sty - psy;
  const mag = Math.hypot(dx, dy);
  if (mag < 1e-3) return;
  dx /= mag; dy /= mag;

  // Cast the hero→stairs ray out to the nearest edge of a rectangle inset far
  // enough that the whole arrowhead (and its glow) stays inside the panel.
  const pad = Math.max(18, tw * 0.95);
  const minX = pad, minY = pad, maxX = W - pad, maxY = H - pad;
  let t = Infinity;
  if (dx > 1e-6) t = Math.min(t, (maxX - psx) / dx);
  else if (dx < -1e-6) t = Math.min(t, (minX - psx) / dx);
  if (dy > 1e-6) t = Math.min(t, (maxY - psy) / dy);
  else if (dy < -1e-6) t = Math.min(t, (minY - psy) / dy);
  if (!isFinite(t) || t < 0) t = 0;
  const ax = Math.max(minX, Math.min(maxX, psx + dx * t));
  const ay = Math.max(minY, Math.min(maxY, psy + dy * t));

  // Cleared stairs pulse gold ("descend here"); while sealed it's the same gold
  // but calmer, echoing the on-tile locked/open language. Colour is UI-semantic,
  // so it comes from the palette mirror rather than a hardcoded hex.
  const pulse = 0.5 + 0.5 * Math.sin(animNow() / 320);
  const open = (typeof floorCleared === 'undefined') || floorCleared;
  const alpha = open ? 0.9 + 0.1 * pulse : 0.5 + 0.12 * pulse;
  const size = Math.max(16, tw * 0.9);

  ctx.save();
  ctx.translate(ax, ay);
  ctx.rotate(Math.atan2(dy, dx));   // arrowhead points +x → toward the stairs
  ctx.beginPath();
  ctx.moveTo(size * 0.6, 0);
  ctx.lineTo(-size * 0.42, size * 0.5);
  ctx.lineTo(-size * 0.16, 0);
  ctx.lineTo(-size * 0.42, -size * 0.5);
  ctx.closePath();
  ctx.shadowColor = hexA(PALETTE.gold, open ? 0.9 : 0.5);
  ctx.shadowBlur = size * (open ? 0.4 + 0.35 * pulse : 0.25);
  ctx.fillStyle = hexA(PALETTE.gold, alpha);
  ctx.fill();
  // Dark keyline (a deeply shaded gold) so the arrow reads over lava, water and
  // bright floors alike.
  ctx.shadowBlur = 0;
  ctx.lineJoin = 'round';
  ctx.lineWidth = Math.max(1.5, size * 0.06);
  ctx.strokeStyle = shadeColor(PALETTE.gold, 0.12);
  ctx.stroke();
  ctx.restore();
}

// A cluster of small red arrows riding the map edge, one per off-screen living
// foe, so you can hunt down the last stragglers sealing the floor. Deliberately
// much smaller and calmer than the gold stairs arrow — and foes bunched in one
// direction collapse into a single arrow aimed at the nearest — so a busy floor
// doesn't drown in arrowheads. Danger-red (PALETTE.danger) reads as "threat over
// there". Off with the Monster Arrows setting; hidden in town. Geometry (which
// foes are off-screen, where each arrow sits, the merge) lives in the pure
// systems/offscreenArrows module; this just draws what it returns.
// Scratch target list reused across frames — offscreenArrows reads it
// synchronously and keeps no reference, so recycling the array and its slot
// objects avoids allocating per foe per frame on a busy floor.
const _arrowTargets = [];
function drawMonsterArrows(offX, offY, tw, th, W, H) {
  if (!showMonsterArrows) return;
  if (inTown || !player || !Array.isArray(mapData) || !mapData.length) return;
  if (typeof enemies === 'undefined' || !enemies.length) return;

  let nT = 0;
  for (const e of enemies) {
    // Skip the dead and fleeing treasure goblins: goblins never seal the floor
    // (see hostilesRemaining / floorCleared), so a red "threat" arrow at one would
    // contradict the "foes sealing the stairs" intent — chase them by eye instead.
    if (e.dead || e.isGoblin) continue;
    // On-screen foes get no arrow anyway (the module applies this exact test), so
    // skip them up front and don't build target entries for them at all.
    const span = e.size || 1;
    if (tileOnScreen(e.x, e.y, span, offX, offY, tw, th, W, H)) continue;
    // e.fx/fy is the smooth footprint CENTRE (may be null before its first render
    // tick); the module falls back to the footprint centre when cx/cy are absent.
    const t = _arrowTargets[nT] || (_arrowTargets[nT] = {});
    t.x = e.x; t.y = e.y; t.span = span; t.cx = e.fx; t.cy = e.fy;
    nT++;
  }
  _arrowTargets.length = nT;
  if (!nT) return;

  const size = Math.max(9, tw * 0.42);          // ~half the stairs arrowhead
  const pad = Math.max(10, tw * 0.55);          // keep the whole head inside the panel
  const arrows = offscreenArrows({
    hero: { fx: player.fx, fy: player.fy },
    targets: _arrowTargets, cam: { offX, offY, tw, th }, view: { W, H },
    pad, mergeDist: size * 1.6,                  // fold a same-direction pack into one arrow
    max: MONSTER_ARROW_CAP,                      // and never ring the whole screen (minimap has the rest)
  });
  if (!arrows.length) return;

  const pulse = 0.5 + 0.5 * Math.sin(animNow() / 260);
  const alpha = 0.7 + 0.14 * pulse;
  for (const a of arrows) {
    ctx.save();
    ctx.translate(a.x, a.y);
    ctx.rotate(a.angle);                          // arrowhead points +x → toward the foe
    ctx.beginPath();
    ctx.moveTo(size * 0.6, 0);
    ctx.lineTo(-size * 0.42, size * 0.5);
    ctx.lineTo(-size * 0.16, 0);
    ctx.lineTo(-size * 0.42, -size * 0.5);
    ctx.closePath();
    ctx.shadowColor = hexA(PALETTE.danger, 0.7);
    ctx.shadowBlur = size * 0.3;
    ctx.fillStyle = hexA(PALETTE.danger, alpha);
    ctx.fill();
    // Dark keyline so the little arrow reads over lava, water and bright floors.
    ctx.shadowBlur = 0;
    ctx.lineJoin = 'round';
    ctx.lineWidth = Math.max(1, size * 0.06);
    ctx.strokeStyle = shadeColor(PALETTE.danger, 0.12);
    ctx.stroke();
    ctx.restore();
  }
}

function spawnFloatingText(x, y, text, color, size, coin, duration) {
  // Canvas floating text can't host sprite spans, so just strip any emoji — the
  // number/word stays. (No emoji anywhere.) `size` scales the font (>1 = a big,
  // bold pop, used for crit / rampage damage numbers). `coin` draws the gold-coin
  // sprite to the left of the text so gold floaters read as "coin + amount", to
  // match the HUD/menus instead of a trailing "g". `duration` (ms) overrides the
  // 800ms default — word labels (shrine names) need longer to actually be read.
  // Big pop-up numbers (a deep-floor crit, a fat gold drop) would splash the tile
  // with a wall of digits, so abbreviate any 1000+ run the same way the HUD and
  // skill tooltips do (15230 → 15.2k). Labels, small numbers and prefixes like
  // "2×" / "+…MP" are left intact. See src/utils/format.js.
  text = abbreviateNumbersIn(text);
  const now = Date.now();
  // Anti-overlap: a kill or multi-hit can fire several floaters at almost the
  // same spot in one frame. Rather than let them pile into an unreadable blob,
  // start each new one higher than the ones already popping nearby so they read
  // as a clean rising stack. They all drift up at the same rate, so the spacing
  // holds for their whole life.
  let stack = 0;
  for (const ft of floatingTexts) {
    if (now - ft.start < 350 && Math.abs(ft.x - x) < 1.1) stack++;
  }
  floatingTexts.push({ x, y: y - stack * 0.5, text, color, start: now, duration: duration || 800, size: size || 1, coin: !!coin });
  // Safety net: never let a big burst wall the screen with text.
  if (floatingTexts.length > 16) floatingTexts.splice(0, floatingTexts.length - 16);
}

// ── COMBAT JUICE ────────────────────────────────────────────────────────────
// Lightweight feedback so hits feel weighty: a quick camera shake, burst
// particles, and a white hit-flash on struck foes. All purely visual and
// self-expiring; the pulse loop keeps repainting while any are live.
let particles = [];
const PARTICLE_CAP = 600;   // hard ceiling — past it the oldest spark is recycled, invisible in a big fight's chaos
const _particlePool = [];   // expired spark objects, reused by spawnParticles to kill allocation churn
let shakeMag = 0, shakeUntil = 0;
function addShake(mag) { shakeMag = Math.max(shakeMag, mag); shakeUntil = Date.now() + 200; }  // rAF loop redraws every frame — no forced draw() needed
// Burst of `n` little sparks at map-tile (x,y), drifting and fading.
function spawnParticles(x, y, color, n, speed) {
  const now = Date.now();
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2, s = (0.3 + Math.random()) * (speed || 0.06);
    // At the cap, recycle the oldest live spark; otherwise reuse a pooled dead
    // one (every field is reset below) before allocating fresh.
    let p;
    if (particles.length >= PARTICLE_CAP) p = particles.shift();
    else p = _particlePool.pop() || {};
    p.x = x + 0.5; p.y = y + 0.5;
    p.vx = Math.cos(a) * s; p.vy = Math.sin(a) * s - 0.02;
    p.born = now; p.life = 280 + Math.random() * 220; p.color = color;
    particles.push(p);
  }
  // No draw() here: the rAF game loop already redraws every frame, so forcing a
  // full extra redraw on every particle burst (several per frame in a big fight)
  // was pure duplicated work. The sparks still appear on the very next frame.
}
// Current camera-shake offset in pixels (decays to 0), used by draw(). Returns a
// reused two-slot scratch array — draw() destructures it immediately and never
// retains it, so recycling kills the per-frame allocation.
const _shakeXY = [0, 0];
// Global amplitude scale for ALL camera shake — dialled down so hits, crits and
// even boss finishers nudge the view gently instead of jolting it. One knob keeps
// every call site's relative weight; the SCREEN SHAKE setting can zero it entirely.
const SHAKE_SCALE = 0.55;
function shakeOffset() {
  if (!showScreenShake || Date.now() >= shakeUntil || shakeMag <= 0) { shakeMag = 0; _shakeXY[0] = _shakeXY[1] = 0; return _shakeXY; }
  const k = (shakeUntil - Date.now()) / 200, m = shakeMag * k * SHAKE_SCALE;
  _shakeXY[0] = (Math.random() * 2 - 1) * m;
  _shakeXY[1] = (Math.random() * 2 - 1) * m;
  return _shakeXY;
}
// A soft drop-shadow ellipse under an actor, for grounding/depth.
// ── Attack lunge animation ────────────────────────────────────────────────
// A quick "step forward and snap back" nudge that plays whenever an actor
// swings, so attacks read visually even though the damage itself resolves
// instantly. Any actor (hero, enemy, minion/merc) can carry `atkAnimAt` (the
// start time) and `atkAnimDir` (a unit-ish vector pointing at what it's
// hitting); draw() offsets that actor's sprite along the vector on a fast
// out-and-back curve. Purely cosmetic — no gameplay state depends on it.
const ATK_LUNGE_MS = 200;   // total lunge duration
function triggerAttackAnim(actor, tx, ty) {
  if (!actor) return;
  // Lunge FROM where the sprite is drawn (its render centre), not its logic tile —
  // so the nudge points true from the visible foe toward its target, matching where
  // the hero lunges from (player.fx/fy).
  const dx = tx - actorRenderCX(actor), dy = ty - actorRenderCY(actor);
  const len = Math.hypot(dx, dy) || 1;
  actor.atkAnimDir = { x: dx / len, y: dy / len };
  actor.atkAnimAt = Date.now();
}
// Pixel offset for the current frame of an actor's lunge, or null when idle.
function attackLungeOffset(actor, tw, th) {
  if (!actor || !actor.atkAnimAt) return null;
  const t = (Date.now() - actor.atkAnimAt) / ATK_LUNGE_MS;
  if (t < 0 || t >= 1) return null;
  const reach = Math.sin(t * Math.PI);          // 0 → 1 → 0 (out and back)
  const d = actor.atkAnimDir || { x: 0, y: -1 };
  const amt = 0.34;                              // peak nudge, as a fraction of a tile
  return { dx: d.x * amt * tw * reach, dy: d.y * amt * th * reach };
}

function drawActorShadow(cx, cyFeet, w) {
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath();
  ctx.ellipse(cx, cyFeet, w * 0.34, w * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

// ── CACHED SOFT-GLOW SPRITES ──
// A radial glow used to mean a fresh createRadialGradient every frame for every
// glowing thing on screen (pickups, vendor auras, the grave beacon, enemy elite
// halos, threat rings…). Instead each glow SHAPE is painted once into a small
// offscreen canvas keyed by its solid RGB, then blitted (scaled to the requested
// radius, with the caller's alpha applied via globalAlpha). A pulsing glow now
// re-blits the same texture at a new alpha instead of rebuilding a gradient, and
// the output matches the old gradient fills. Separating RGB (cache key) from
// alpha (globalAlpha) keeps the cache tiny — one texture per colour, not per frame.
const GLOW_TEX = 64;
const _discGlow = new Map();   // "r,g,b" → canvas: solid centre → transparent edge
const _ringGlow = new Map();   // "r,g,b" → canvas: transparent centre → colour → transparent edge
// _parseRGBA extracted to src/utils/color.js (imported at top).
function _glowSprite(cache, rgb, ring) {
  let cv = cache.get(rgb);
  if (cv) return cv;
  cv = document.createElement('canvas'); cv.width = cv.height = GLOW_TEX;
  const g = cv.getContext('2d'), c = GLOW_TEX / 2;
  const grd = g.createRadialGradient(c, c, ring ? c * 0.46 : 0, c, c, c);
  if (ring) { grd.addColorStop(0, `rgba(${rgb},0)`); grd.addColorStop(0.72, `rgba(${rgb},1)`); grd.addColorStop(1, `rgba(${rgb},0)`); }
  else      { grd.addColorStop(0, `rgba(${rgb},1)`); grd.addColorStop(1, `rgba(${rgb},0)`); }
  g.fillStyle = grd;
  g.beginPath(); g.arc(c, c, c, 0, Math.PI * 2); g.fill();
  // Safety cap: pathological colour churn could otherwise grow the cache without
  // bound — reset it rather than let it pass 128 entries (rebuilds are cheap).
  if (cache.size > 128) cache.clear();
  cache.set(rgb, cv);
  return cv;
}
// Red targeting reticle over the auto-attack's locked-on foe. A procedural UI
// marker (like the threat ring), not a sprite: a thin pulsing ring, four gapped
// N/E/S/W ticks and a centre dot, so the current target reads at a glance
// without hiding the enemy. `size` is the enemy footprint width in pixels.
function drawTargetCrosshair(cx, cy, size) {
  const t = 0.5 + 0.5 * Math.sin(animNow() / 260);   // gentle "active lock" pulse
  const r = size * 0.5;
  const red = 'rgba(255,48,58,';                       // bright targeting red
  ctx.save();
  ctx.globalAlpha = 0.35;                              // faint overlay — mark the foe without hiding it
  ctx.lineCap = 'round';
  ctx.lineWidth = Math.max(1.5, size * 0.05);
  ctx.strokeStyle = red + (0.7 + 0.25 * t) + ')';
  ctx.shadowColor = red + '0.9)';
  ctx.shadowBlur = Math.max(2, size * 0.12);
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);                  // ring
  ctx.stroke();
  const inR = r * 0.62, outR = r * 1.26;               // four ticks, gapped at centre
  ctx.beginPath();
  ctx.moveTo(cx, cy - inR); ctx.lineTo(cx, cy - outR);
  ctx.moveTo(cx, cy + inR); ctx.lineTo(cx, cy + outR);
  ctx.moveTo(cx - inR, cy); ctx.lineTo(cx - outR, cy);
  ctx.moveTo(cx + inR, cy); ctx.lineTo(cx + outR, cy);
  ctx.stroke();
  ctx.shadowBlur = 0;
  ctx.fillStyle = red + (0.85 + 0.15 * t) + ')';
  ctx.beginPath();
  ctx.arc(cx, cy, Math.max(1, size * 0.05), 0, Math.PI * 2);   // centre dot
  ctx.fill();
  ctx.restore();
}

// A soft CIRCULAR glow behind a pickup/actor: a cached radial-glow texture tinted
// by `color` and faded by its alpha, scaled to radius r.
function glowUnder(cx, cy, r, color) {
  const { rgb, a } = _parseRGBA(color);
  ctx.save();
  ctx.globalAlpha = a;
  ctx.imageSmoothingEnabled = true;   // keep the upscaled glow texture soft, not blocky
  ctx.drawImage(_glowSprite(_discGlow, rgb, false), cx - r, cy - r, r * 2, r * 2);
  ctx.restore();
}
// A soft ring glow (fades at both centre and edge), used for threat telegraphs.
// `alpha` is the peak opacity; the ring shape itself is cached per colour.
function ringGlow(cx, cy, r, rgb, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.imageSmoothingEnabled = true;   // keep the upscaled ring texture soft, not blocky
  ctx.drawImage(_glowSprite(_ringGlow, rgb, true), cx - r, cy - r, r * 2, r * 2);
  ctx.restore();
}

// ══════════════════════════════════════════
// ULTIMATE SPELL FX — cinematic capstone casts
// ══════════════════════════════════════════
// The long-cooldown ultimates at the bottom of each skill tree get a full-screen
// cinematic when cast — a meteor slamming down and radiating flames, a frost nova
// shattering outward, a lightning storm, a searing annihilation beam, a holy
// pillar, a summoning vortex, or a ground-shaking slam — themed to the spell's
// element and shape. Purely visual: the damage is resolved instantly by
// resolveCast; each effect is self-contained and time-driven (repainted every
// frame from draw()) and touches no game state except a decaying camera shake.
let ultFx = [];
// A camera-shake bump that does NOT repaint (safe to call from inside draw(),
// unlike addShake which calls draw() and would recurse).
function nudgeShake(mag, ms) {
  shakeMag = Math.max(shakeMag, mag);
  shakeUntil = Math.max(shakeUntil, Date.now() + (ms || 200));
}
// Which cinematic an ultimate uses, from its shape + element/theme.
function ultStyleFor(node, c) {
  if (c.summon) return 'summon';
  if (c.shape === 'line') return 'beam';
  const el = spellElement(node);
  if (el === 'fire') return 'meteor';
  if (el === 'ice') return 'frost';
  if (el === 'lightning') return 'storm';
  const t = (((node && node.icon) || '') + ' ' + ((node && node.name) || '')).toLowerCase();
  if (/holy|divine|smite|judg|sacred|consecr|radian|zeal|seraph|avatar|justice|angel|light/.test(t)) return 'holy';
  return 'generic';
}
const ULT_SND = { meteor: 'ult-fire', frost: 'ult-ice', storm: 'ult-lightning', beam: 'ult-beam', holy: 'ult-holy', summon: 'ult-summon', generic: 'ult' };
// Seed a cinematic for one ultimate cast. center/targets are in tile coords.
function spawnUltimateFx(node, c, center, targets) {
  const style = ultStyleFor(node, c);
  const color = castVisual(node);
  const R = Math.random;
  const tg = (targets || []).filter(o => o).map(o => ({ x: o.x + 0.5, y: o.y + 0.5 }));
  // Per-spell sigil so two ultimates of the same style (e.g. Judgment Day and Final
  // Judgment, both the 'holy' cinematic) still brand a distinct rune over the burst.
  const e = { style, color, born: Date.now(), x: (center.x || 0) + 0.5, y: (center.y || 0) + 0.5, targets: tg, flashed: false,
    sig: castSignature(node && node.id, node && node.name),
    sigPal: paletteFor(elementOf((node && node.name) || '', (node && node.icon) || '', 'gold')) };
  if (style === 'meteor') {
    e.dur = 1500; e.impactMs = 230;
    e.embers = Array.from({ length: 26 }, () => ({ a: R() * Math.PI * 2, spd: 0.4 + R() * 1.1, sz: 1 + R() * 2.4, rise: 0.5 + R() }));
    e.tongues = Array.from({ length: 12 }, (_, i) => ({ a: (i / 12) * Math.PI * 2 + R() * 0.3, len: 0.7 + R() * 0.5, w: 0.5 + R() * 0.6 }));
  } else if (style === 'frost') {
    e.dur = 1200; e.impactMs = 90;
    e.shards = Array.from({ length: 16 }, (_, i) => ({ a: (i / 16) * Math.PI * 2 + R() * 0.2, len: 0.8 + R() * 0.6 }));
    e.spark = Array.from({ length: 20 }, () => ({ a: R() * Math.PI * 2, d: R(), sz: 1 + R() * 2 }));
  } else if (style === 'storm') {
    e.dur = 1050; e.impactMs = 70;
    const pts = e.targets.length ? e.targets : [{ x: e.x, y: e.y }];
    e.bolts = pts.slice(0, 8).map(p => ({ x: p.x, y: p.y, jag: Array.from({ length: 7 }, () => (R() * 2 - 1)) }));
    e.arcs = Array.from({ length: 10 }, () => ({ a: R() * Math.PI * 2, len: 0.6 + R() * 0.7 }));
  } else if (style === 'beam') {
    e.dur = 900; e.impactMs = 130;
    const from = { x: player.x + 0.5, y: player.y + 0.5 };
    let to = e.targets[0] || { x: e.x, y: e.y };
    for (const p of e.targets) { if (Math.hypot(p.x - from.x, p.y - from.y) > Math.hypot(to.x - from.x, to.y - from.y)) to = p; }
    const dx = to.x - from.x, dy = to.y - from.y, m = Math.hypot(dx, dy) || 1;
    e.ax = from.x; e.ay = from.y; e.bx = to.x + dx / m * 1.5; e.by = to.y + dy / m * 1.5;
  } else if (style === 'holy') {
    e.dur = 1200; e.impactMs = 110;
    e.motes = Array.from({ length: 22 }, () => ({ a: R() * Math.PI * 2, d: 0.2 + R(), rise: 0.6 + R(), sz: 1 + R() * 2 }));
  } else if (style === 'summon') {
    e.dur = 1150; e.impactMs = 1e9;
    e.motes = Array.from({ length: 24 }, (_, i) => ({ a: (i / 24) * Math.PI * 2, d: 0.3 + R() * 0.9, sz: 1 + R() * 2 }));
  } else {
    e.dur = 1000; e.impactMs = 60;
    e.debris = Array.from({ length: 20 }, () => ({ a: R() * Math.PI * 2, spd: 0.6 + R() * 1.2, sz: 1.5 + R() * 2.5, rot: R() * Math.PI }));
    e.cracks = Array.from({ length: 9 }, (_, i) => ({ a: (i / 9) * Math.PI * 2 + R() * 0.2, len: 0.7 + R() * 0.6 }));
  }
  ultFx.push(e);
  sfx(ULT_SND[style] || 'ult');
  screenFlash(style === 'frost' ? '#bfe8ff' : style === 'storm' ? '#eaf2ff' : style === 'holy' ? '#fff0c0' : color);
}
// A glowing stroked ring (shockwave). r/w in px.
function _ultRing(cx, cy, r, w, color, alpha) {
  if (r <= 0 || w <= 0 || alpha <= 0) return;
  ctx.save();
  ctx.globalAlpha = Math.min(1, alpha); ctx.strokeStyle = color; ctx.lineWidth = w;
  ctx.shadowColor = color; ctx.shadowBlur = w * 2;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
  ctx.restore();
}
// A jagged lightning bolt from (x1,y1) to (x2,y2) with per-segment offsets `jag`.
function _ultBolt(x1, y1, x2, y2, jag, amp, color, w) {
  ctx.save();
  ctx.strokeStyle = color; ctx.lineWidth = w; ctx.lineCap = 'round';
  ctx.shadowColor = color; ctx.shadowBlur = w * 3;
  const nx = -(y2 - y1), ny = (x2 - x1), m = Math.hypot(nx, ny) || 1;
  ctx.beginPath(); ctx.moveTo(x1, y1);
  for (let i = 0; i < jag.length; i++) {
    const k = (i + 1) / (jag.length + 1);
    const off = jag[i] * amp * (1 + (Math.random() - 0.5) * 0.5);
    ctx.lineTo(x1 + (x2 - x1) * k + (nx / m) * off, y1 + (y2 - y1) * k + (ny / m) * off);
  }
  ctx.lineTo(x2, y2); ctx.stroke();
  ctx.restore();
}
