  cg.addColorStop(0, "rgba(255,240,200," + (0.9 * (1 - a)).toFixed(3) + ")");
  cg.addColorStop(0.5, "rgba(255,140,50," + (0.6 * (1 - a)).toFixed(3) + ")");
