  flurry:      { name: 'Flurry',       color: '#ffcf7a', desc: '+18% chance to strike twice.',          stats: { DBLSTRIKE: 18 } },
  frenzied:    { name: 'Frenzied',     color: '#ff8a5a', desc: 'You attack +20% faster.',               stats: { ATKSPD: 20 } },
  executioner: { name: 'Executioner',  color: '#d64a5a', desc: 'Finishes low-health foes (+16%).',      stats: { EXEC: 16 } },
