// Category display order + section labels for the grouped achievements popup.
const ACH_CATS = [
  { key: 'depth',    label: 'Depth' },
  { key: 'level',    label: 'Level' },
  { key: 'gold',     label: 'Gold' },
  { key: 'plunder',  label: 'Plunder' },
  { key: 'power',    label: 'Power' },
  { key: 'time',     label: 'Playtime' },
  { key: 'slay',     label: 'Slaying' },
  { key: 'skill',    label: 'Skills' },
  { key: 'mastery',  label: 'Mastery' },
  { key: 'cook',     label: 'Cooking' },
  { key: 'wardrobe', label: 'Wardrobe' },
  { key: 'mats',     label: 'Materials' },
  { key: 'gear',     label: 'Gear' },
  { key: 'clear',    label: 'Clearing' },
];
// A single achievement badge — shared by the normal (gold) and hardcore (crimson)
// rows. Reuses the game's styled hover/long-press tooltip (data-tip + showHoverTip).
function achBadgeHtml(a, got, isHc) {
  const ic = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + a.svg + '</svg>';
  const status = got
    ? `<div class='ht-sub' style='color:${isHc ? '#ff7a86' : 'var(--gold)'}'>✓ Unlocked</div>`
    : `<div class='ht-sub'><span data-spr=feat_door></span> Locked</div>`;
  const tip = `<div class='ht-name'>${a.name}</div><div class='ht-line'>${a.desc}</div>${status}`;
  return `<div class="ta-badge${isHc ? ' hc' : ''} ${got ? 'earned' : 'locked'}" data-tip="${tip}" onmouseenter="showHoverTip(event,this)" onmouseleave="hideHoverTip()"><span class="ta-ic">${ic}</span><span class="ta-nm">${a.name}</span></div>`;
}
// Build one mode's grouped sections + earned tally, given an "is this feat
// earned?" predicate. Shared by the Kitten Mode (gold) and Hardcore (crimson)
// tabs so both list the identical achievements — only their state differs.
function achModeHtml(isEarned, isHc) {
  let earned = 0, sections = '';
  for (const c of ACH_CATS) {
    const list = ACHIEVEMENTS.filter(a => a.cat === c.key);
    if (!list.length) continue;
    let ce = 0;
    const cells = list.map(a => { const got = !!isEarned(a); if (got) { earned++; ce++; } return achBadgeHtml(a, got, isHc); }).join('');
    sections += `<div class="ta-head ta-cat">${c.label} <b>${ce}</b> / ${list.length}</div><div class="ta-row">${cells}</div>`;
  }
  return { earned, sections };
}
// Which achievements tab is showing; remembered across opens. Defaults the first
// time to the hero's own mode (a Hardcore hero lands on the Hardcore tab).
let _achTab = null;
function selectAchTab(mode) {
  _achTab = mode;
  const body = document.getElementById('achievements-body');
  if (!body) return;
  body.querySelectorAll('.ach-tab').forEach(t => t.classList.toggle('active', t.dataset.mode === mode));
  const np = document.getElementById('ach-panel-normal');
  const hp = document.getElementById('ach-panel-hc');
  if (np) np.style.display = mode === 'hc' ? 'none' : '';
  if (hp) hp.style.display = mode === 'hc' ? '' : 'none';
}
// Build the two-tab badge popup (Kitten Mode + Hardcore) and refresh the title
// grid's Achievements tile count. The tile carries the active hero's own-mode
// progress ("5 / 100") so players see it without opening the popup.
function renderTitleAchievements() {
  const cnt = document.getElementById('title-ach-count');
  const body = document.getElementById('achievements-body');
  const p = (typeof player === 'object' && player) || {};
  const total = ACHIEVEMENTS.length;
  // Kitten (normal) feats persist account-wide in hcMeta.nach — earned on any hero or
  // slot, so the tally never diverges between saves — plus whatever the live active
  // hero currently qualifies for (shown instantly, before the next save grants it).
  const normal = achModeHtml(a => nAchHas(a.id) || !!a.test(p), false);
  // Hardcore feats persist account-wide (hcMeta.ach) and survive death; the live
  // hardcore hero also lights up anything it currently qualifies for.
  const hc = achModeHtml(a => hcHasAch(a.id) || (p.hardcore && !!a.test(p)), true);
  if (_achTab == null) _achTab = p.hardcore ? 'hc' : 'normal';
  // Kitten tab wears a paw (matches the badge line-icon style); Hardcore wears the
  // game's skull brand sprite, falling back to a shield outline before it loads.
  const pawIc = `<span class="ach-tab-ic"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${AI_PAW}</svg></span>`;
  const skullIc = `<span class="ach-tab-ic">${hcIcon(16) || `<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">${AI_SHIELD}</svg>`}</span>`;
  if (body) {
    body.innerHTML =
      `<div class="ach-tabs">`
      + `<button class="ach-tab" data-mode="normal" onclick="event.stopPropagation();selectAchTab('normal')">${pawIc} Kitten Mode</button>`
      + `<button class="ach-tab hc" data-mode="hc" onclick="event.stopPropagation();selectAchTab('hc')">${skullIc} Hardcore</button>`
      + `</div>`
      + `<div id="ach-panel-normal"><div class="ta-head ta-total">Kitten Mode <b>${normal.earned}</b> / ${total}</div>${normal.sections}</div>`
      + `<div id="ach-panel-hc"><div class="ta-head ta-total hc">Hardcore <b>${hc.earned}</b> / ${total}</div>${hc.sections}</div>`;
    selectAchTab(_achTab);
  }
  if (cnt) {
    // The tile carries a progress count so it reads at a glance without opening the
    // popup: the hardcore tally for a hardcore hero (or an account whose only progress
    // is hardcore — e.g. a fallen hero at the title screen), otherwise the account-wide
    // Kitten tally (which stands even at the title screen with no active hero). Always
    // gold — the tile never wears the hardcore crimson; the popup tabs mark the mode.
    const showHc = p.hardcore || (normal.earned === 0 && hc.earned > 0);
    cnt.textContent = `${showHc ? hc.earned : normal.earned} / ${total}`;
  }
}
// Bestiary tile count — discovered / total foes, so the codex reads at a glance
// from the title (mirrors the Achievements tile). bestiaryDex is account-wide, so
// the tally stands even at the title screen with no active hero. Always gold (the
// .tsb-count colour); the popup itself distinguishes creatures vs bosses.
function renderTitleBestiary() {
  const cnt = document.getElementById('title-bst-count');
  if (!cnt) return;
  const roster = bestiaryRoster();
  const discovered = roster.filter(s => speciesDiscovered(bestiaryKills(s))).length;
  cnt.textContent = roster.length ? `${discovered} / ${roster.length}` : '';
}
// Two-tap wipe of THIS device's title-screen progress stats — the achievement
// feats (Kitten hcMeta.nach + Hardcore hcMeta.ach) and the bestiary codex
// (bestiaryDex) — back to zero. First tap arms the button (auto-disarms after 3s);
// the second tap clears. The hardcore DEATH ledger (hcMeta.cids) is deliberately
// left intact, so this can never revive a permadead hero. Local only: while signed
// in the cloud still holds the master copy and re-syncs it (the ledgers only ever
// grow), so a player who wants it gone for good signs out first — the tooltip says
// as much. Wired to the Settings ▸ Progress ▸ Reset button.
let _statsWipeArmed = false;
let _statsWipeTimer = null;
function _setStatsWipeUi(state) {   // 'idle' | 'armed' | 'done'
  const btn = document.getElementById('reset-stats-action');
  const lbl = document.getElementById('reset-stats-label');
  if (btn) btn.classList.toggle('armed', state === 'armed');
  if (lbl) lbl.textContent = state === 'armed' ? 'TAP AGAIN TO WIPE'
    : state === 'done' ? 'CLEARED ✓'
    : 'CLEAR ACHIEVEMENTS & BESTIARY';
}
function resetTitleStats() {
  if (!_statsWipeArmed) {                 // first tap: arm, then auto-disarm
    _statsWipeArmed = true;
    _setStatsWipeUi('armed');
    if (_statsWipeTimer) clearTimeout(_statsWipeTimer);
    _statsWipeTimer = setTimeout(() => { _statsWipeArmed = false; _statsWipeTimer = null; _setStatsWipeUi('idle'); }, 3000);
    return;
  }
  if (_statsWipeTimer) { clearTimeout(_statsWipeTimer); _statsWipeTimer = null; }
  _statsWipeArmed = false;
  // Clear the achievement feat sets — keep the death ledger cids untouched so a
  // fallen hardcore hero stays fallen.
  hcMeta.ach = [];
  hcMeta.nach = [];
  hcMeta.ts = Date.now();
  _hcAchSet = new Set();
  _nAchSet = new Set();
  writeHcMeta();
  // Clear the bestiary codex back to empty.
  bestiaryDex = emptyDex();
  writeBestiaryDex();
  // Repaint the title tiles and any open Achievements/Bestiary popup so the wipe
  // shows instantly (renderTitleAchievements also rebuilds the achievements popup).
  try { renderTitleAchievements(); } catch (e) {}
  try { renderTitleBestiary(); } catch (e) {}
  try { const bo = document.getElementById('bestiary-overlay'); if (bo && bo.classList.contains('open')) renderBestiary(); } catch (e) {}
  // Confirm on the button, then settle back to the resting label.
  _setStatsWipeUi('done');
  _statsWipeTimer = setTimeout(() => { _statsWipeTimer = null; _setStatsWipeUi('idle'); }, 1600);
}
function showAchievements() {
  renderTitleAchievements();  // refresh in case progress changed
  // Opened from the settings popup (Progress tab) or the title — tuck the menu
  // away so this sits standalone and one Esc closes it (see handleEscape).
  const menu = document.getElementById('settings-menu');
  if (menu) menu.classList.remove('open');
  const ov = document.getElementById('achievements-overlay');
  if (ov) ov.classList.add('open');
}
function closeAchievements() { const ov = document.getElementById('achievements-overlay'); if (ov) ov.classList.remove('open'); }
// Builds the "who you're playing" card — name, class, level, deepest floor, gold,
// a HARDCORE tag, and a walking hero portrait. Shared by the title screen's
// #title-hero card and the pause menu's #settings-hero card. Returns '' when
// there's no active hero yet (a fresh save with no class chosen), so callers can
// simply hide the element.
function heroCardHtml() {
  if (!(player && player.class)) return '';
  const cls = (typeof CLASSES === 'object' && CLASSES[player.class]) || {};
  const nm = escapeHtml(player.name || 'Adventurer');
  const lvl = player.level || 1;
  const deepest = player.maxFloor || 1;
  const gold = fmtGold ? fmtGold(player.gold || 0) : (player.gold || 0);
  // Mode tags under the stats line — crimson HARDCORE, gold SOLO SELF-FOUND
  // (a hero can wear both).
  const modeTags = [
    player.hardcore ? `<span class="hc-tag">${hcIcon(11)} HARDCORE · ONE LIFE</span>` : '',
    player.ssf ? `<span class="hc-tag ssf">${ssfIcon(11)} SOLO SELF-FOUND</span>` : '',
  ].filter(Boolean).join(' ');
  const hcTag = modeTags ? `<div>${modeTags}</div>` : '';
  // An animated walking hero sprite sits to the RIGHT of the left-aligned text,
  // standing a bit taller than the stacked name/class/stats block so it reads big.
  // Falls back to the static face (then atlas tile) until the walk sheet has loaded.
  const heroPic = heroWalkIcon(player.class, player.sex, 102) || heroFaceIcon(player.class, player.sex, 102);
  return `<div class="th-info">`
    + `<div class="th-name" style="color:${cls.color || 'var(--xp)'}">${nm}</div>`
    + `<div class="th-sub">Level ${lvl} ${cls.name || 'Hero'}</div>`
    + `<div class="th-stats"><span><span data-spr=feat_gate_red></span><b>${floorTag(deepest)}</b></span><span><span data-spr=ic_money></span><b>${gold}</b></span></div>`
    + hcTag
    + `</div>`
    + (heroPic ? `<div class="th-portrait">${heroPic}</div>` : '');
}
// Paint the character card that sits above the settings card while paused. Mirrors
// the title screen's hero card; hidden before a hero exists (e.g. Settings opened
// from the title on a brand-new save).
function renderSettingsHero() {
  const el = document.getElementById('settings-hero');
  if (!el) return;
  const html = heroCardHtml();
  if (html) { el.innerHTML = html; el.style.display = ''; }
  else { el.innerHTML = ''; el.style.display = 'none'; }
}
function showTitle() {
  const ov = document.getElementById('title-overlay');
  if (!ov) return;
  // Never strand a world-pausing tutorial gate over the title (e.g. bailing to the
  // menu mid-lesson) — reset it so a fresh/continued run starts clean.
  _manaGateWanted = false; closeTutGate();
  // Seed the drifting-ember background once (decorative, behind the content).
  const emb = document.getElementById('title-embers');
  if (emb && !emb.childElementCount) {
    let html = '';
    for (let i = 0; i < 14; i++) {
      const left = Math.round(Math.random() * 100);
      const size = (2 + Math.random() * 2.5).toFixed(1);
      const dur = (6 + Math.random() * 7).toFixed(1);
      const delay = (Math.random() * 8).toFixed(1);
      const drift = Math.round(-30 + Math.random() * 60);
      html += `<span class="ember" style="left:${left}%;width:${size}px;height:${size}px;animation-duration:${dur}s;animation-delay:${delay}s;--drift:${drift}px"></span>`;
    }
    emb.innerHTML = html;
  }
  // Crest is the pixel sword tile (atlas), referenced directly by its key.
  const crest = document.getElementById('title-crest');
  if (crest) { const ic = (typeof dlIcon === 'function') ? dlIcon('w_sword', 46) : ''; crest.innerHTML = ic; }
  // A returning hero gets CONTINUE plus a New Run button underneath (start another
  // hero in a fresh slot without opening Save Slots first); a fresh save gets one
  // "enter the dungeon" ENTER button that flows straight into name/class onboarding
  // and needs no separate New Run. The current hero always stays saved in its own
  // slot, so New Run never discards it.
  const resuming = !!(player && player.class);
  const play = document.getElementById('title-play');
  if (play) play.innerHTML = `<span class="tp-label">${resuming ? 'CONTINUE' : 'ENTER'}</span>`;
  const newRun = document.getElementById('title-newrun');
  if (newRun) newRun.style.display = resuming ? '' : 'none';
  // Hero / journey card — identity + how far this hero has delved.
  const hero = document.getElementById('title-hero');
  if (hero) {
    const html = heroCardHtml();
    if (html) { hero.innerHTML = html; hero.style.display = ''; }
    else hero.style.display = 'none';
  }
  renderTitleAchievements();
  renderTitleBestiary();
  refreshTitleToggles();
  ov.classList.add('open');
}
function closeTitle() { const ov = document.getElementById('title-overlay'); if (ov) ov.classList.remove('open'); }
// Dismiss the boot splash (index.html #boot-overlay) once init has painted the
// real title underneath — showTitle() has already flipped ENTER → CONTINUE and
// filled the hero card, so fading the loader reveals the correct state with no
// new-game flash. Adds .boot-done (fades out, drops pointer-events immediately);
// idempotent, so the index.html failsafe re-adding it later is harmless.
function hideBootLoader() { const b = document.getElementById('boot-overlay'); if (b) b.classList.add('boot-done'); }
function titlePlay() {
  closeTitle();
  audioUnlock();
  // Run onboarding now (deferred from init). Class first, then name + body type:
  // a brand-new hero (no class) picks a class; a class-but-unnamed hero finishes
  // on the name screen.
  if (!player.class) showClassPick();
  else if (!player.name) showNameEntry();
  else updateObjectiveChip();   // returning hero resumes — surface any active bounty
}
// New Run — start a fresh hero in the LOWEST FREE save slot, so the returning hero
// on the title stays saved in its own slot (load them again any time via CONTINUE or
// Save Slots). Offered under CONTINUE so a player can begin another run without
// opening Save Slots first; newGameInSlot() reloads into name/class onboarding.
function titleNewRun() {
  audioUnlock();
  const used = new Set(allLocalSlotIndices());
  newGameInSlot(lowestFreeSlot(used));
}
function titleSound() { toggleSound(); refreshTitleToggles(); }

// ── Endgame-systems mutable state (wired up in the ENDGAME SYSTEMS BLOCK below) ──
// Declared HERE, ABOVE the boot sequence, on purpose. Boot runs generateMap()
// (whose egOnFloorEnter() hook writes _egFloorEnterMs) and loadHallDeeds() (which
// fills hallDeeds). Function declarations hoist, but `let` bindings stay in the
// temporal dead zone until evaluation reaches them — declared after the boot block
// these crashed every boot that had a save (a fresh save skips generateMap via the
// tutorial path, which is why tests and incognito checks kept passing while every
// returning player got a black screen). Keep them above the GUARDED BOOT below.
let _egCovDread = 0, _egCovMult = null, _egCovReward = null, _egCovMalaiseRate = 0, _egFloorEnterMs = 0;
let _egWeaveCache = null;
let _egMfSel = -1, _egMfDivineAether = false;
let _egPinnacleFight = null, _egPinnacleBoss = null, _egPinnacleFightStartMs = 0, _egPinnacleBossId = null;
let _egCycleCache = null;
let hallDeeds = { completed: [], renown: 0, title: null, frame: null, badge: null, claimed: [], classesPlayed: [], mirrored: 0, bountiesTotal: 0 };

// GUARDED BOOT — the whole first-run boot sequence lives at module top level, but
// the game-loop kickoff and the window handler bridge (which every inline on*=
// button needs) run LATER in this file. A synchronous throw here (e.g. a corrupt
// or older-shape localStorage save that trips a boot step) would abort module
// evaluation before either runs, leaving the title up with dead buttons AND a dead
// controller. Wrap it so a boot failure is logged and recovered from instead of
// stranding the player: execution always falls through to the loop + bridge below.
try {
  // Load the hardcore death ledger + earned feats BEFORE the save, so loadGame() can
  // recognise (and refuse to load) a hero who has already permanently died.
  loadHcMeta();
  // Load the account-wide bestiary ledger (kills + specimen lore), folding in any legacy
  // per-hero bestiary left on existing saves. Runs BEFORE the achievement backfill (whose
  // slay feats read the ledger) and before loadGame() (so the active hero's save is already
  // stripped of its legacy fields and its kills aren't double-counted).
  loadBestiaryDex();
  loadHallDeeds();   // account-wide Hall of Deeds / Renown ledger (mirrors the bestiary key)
  // Seed the account-wide (Kitten) feat set from every existing save on this device, so
  // achievements earned before this feature — or on a slot not yet replayed — are
  // unified into one account tally instead of appearing to differ between slots.
  backfillAccountAchievements();
  loadDelMeta();  // deletion tombstones, so a hero deleted on another device stays deleted here
  loadDaily();   // daily-goal streak (persists in localStorage, independent of saves)
  const hadSave = loadGame();
  // The Dev tuning tab was removed; wipe any saved slider overrides so every hero
  // reverts to the shipping balance defaults on load.
  try { localStorage.removeItem('dungeonLoot_devTune_v1'); } catch (e) {}
  // Load the account-wide shared stash (and, on first run, migrate any older
  // per-character stashes into the pool). It lives outside the save slots, so it
  // loads even when the active slot is empty.
  loadStash();
  // Resume in town if that's where the save left off; a brand-new hero who hasn't
  // done the beach tutorial gets it first — as does a hero whose save was taken ON
  // the shore (loading a slot reloads the page, so quitting mid-tutorial must come
  // back to the beach, not skip it for dungeon floor 1); otherwise build the floor.
  if (inTown) { buildTown(); }   // walkable town — no auto-opened hub menu; the map IS the town
  else if (resumeTutorial || (!hadSave && !player.tutorialDone)) buildTutorialMap();
  else generateMap();
  seedAmbientEmbers();
  draw();
  updateBars();
  renderPanel();
  updateObjectiveChip();   // paint the goal chip for the starting state

  // Show the title screen / landing page first. The game is already built behind
  // it; titlePlay() dismisses the title and runs onboarding (name then class) for
  // a brand-new or class-less hero. Returning heroes just resume on CONTINUE.
  showTitle();
  // The real title is now correct (CONTINUE + hero card for a returning hero), so
  // fade out the boot splash that has been masking the cold-load flash until here.
  hideBootLoader();

  // Paint the optional cloud-save callout, then — if already signed in — reconcile
  // this device's slots with the account in the background (may reload into a
  // newer save pulled from the cloud).
  refreshAccountUi();
  cloudBootSync();

  if (hadSave) {
    log(`Welcome back, level ${player.level} adventurer.`, 'important');
    if (inTown) log('In town. Pick a service, or take <span data-spr=feat_gate_red></span> Warp to Dungeon.');
    // The shore also runs at dungeonLevel 1, so say where they actually are —
    // "dungeon level 1" would read as the real floor 1 they haven't reached yet.
    else if (resumeTutorial) log('🏖️ Back on the shore. Clear the beach, then take the cave north.');
    else log(`Resuming on dungeon level ${dungeonLevel}.`);
  } else {
    log('Move with WASD or the arrow keys.', 'important');
    log('<span data-spr=feat_door></span> Clear a floor of foes to unseal the ▼ stairs, then descend.', 'important');
    log('⚠️ The deep scales fast — grind lower floors from <span data-spr=town_vault></span> TOWN when you hit a wall.');
  }
  log('Progress auto-saves as you play.');
  log('Open <span data-spr=chest></span> BAG to view loot; press the pad\'s USE button to grab items.');
  log(`Tap the <span data-spr=potion_r></span> or <span data-spr=potion_g></span> flask to quaff a ${logPotion('Potion')} — free, but they share a short cooldown.`);
  log('⌨️ Keys: Q health potion · E mana potion · R primary skill · 3–9 skills · T town · B open bag · Space/F use.');
  log('<span data-spr=ic_stun></span> You have a skill point — open <span data-spr=chest></span> BAG ▸ SKILLS to learn an active, then tap <span data-spr=ic_stun></span> (or press ' + skillKeyLabel(1) + ') to cast it.');
  log(PWR_GLYPH + ' Each item has Power; your total blends level, gear, and attributes.');
  log('<span data-spr=mat_glimmer></span> Level up for points, then raise attributes in the bag\'s HERO tab.');
  log('<span data-spr=w_dagger></span> Every weapon fights differently — axes cleave, daggers flurry, bows & staves strike at range, maces stun, scythes drain. Try them all!');
  log('<span data-spr=feat_gate_red></span> Tap TOWN (or press ' + kbLabel('portal') + ') to warp to the safe hub: craftsman, healer, trainer, enchanter, and a gate back to any floor you\'ve reached.');
  log('<span data-spr=chest></span> Foes drop crafting materials — <span data-spr=mat_scrap></span> Scrap & <span data-spr=mat_glimmer></span> Glimmer from the start, <span data-spr=mat_core></span> Core and <span data-spr=feat_portal></span> Chaos Orbs as you brave deeper tiers. The <span data-spr=ic_mallet></span> Craftsman forges blank gear; the <span data-spr=ic_wand></span> Enchanter fills in its modifiers.');
  log('<span data-spr=mat_scrap></span> Tap any loot in your <span data-spr=chest></span> BAG to Sell it for gold or Scrap it into materials — any time, no vendor needed. Use the <span data-spr=mat_scrap></span> Auto-Loot button on the LOOT tab to do it automatically by rarity on pickup.');
  log('<span data-spr=w_sword></span> Move in real time and auto-attack foes in reach — get surrounded and every foe piles on, so don\'t let them encircle you.');
  // Credit every terrain pack actually painting the world (registry-driven, so
  // attribution stays truthful automatically as packs are added — see
  // src/data/terrainPacks.js and docs/terrain-packs.md).
  for (const pack of terrainPacksInUse()) log(`🌍 Terrain tiles from "${pack.label}" by ${pack.credit} (${pack.license}).`);
  log('🌿 Decor (trees, plants, cacti, shells) from the "[LPC]" collections by bluecarrot16 & contributors (CC-BY-SA) — full credits in docs/asset-credits.md.');
} catch (bootErr) {
  // Never let a boot hiccup strand the player behind unresponsive controls. Log it
  // (so it's diagnosable in the console), lift the splash, and paint the landing
  // page — the handler bridge + game loop below still wire up, so the title's
  // buttons and the controller stay live for recovery.
  try { console.error('[boot] game boot failed — recovering to a usable title:', bootErr); } catch (_e) {}
  try { hideBootLoader(); } catch (_e) {}
  try { showTitle(); } catch (_e) {}
}

// PREVIEW ONLY — `?terrain=proc` swaps the dungeon ground to the procedural
// terrain-pack renderer; add `&preview=1` to auto-drop into a dungeon floor so
// the swap is visible immediately (used to screenshot a real level). Never fires
// in normal play.
try {
  const _q = new URLSearchParams(location.search);
  if (_q.get('terrain') === 'proc') PROC_TERRAIN = true;
  if (_q.get('preview') === '1') {
    setTimeout(() => {
      try {
        player.name = player.name || 'Preview';
        chooseClass(player.class || 'warrior');
        if (typeof closeTitle === 'function') closeTitle();
        enterDungeonAt(1, 6);
        if (typeof closeTitle === 'function') closeTitle();
      } catch (e) { console.error('preview bootstrap failed:', e); }
    }, 400);
    // Preview helper: jump to any raw dungeon depth (bypasses the unlock clamp)
    // and report its terrain mix, so a capture script can find water/lava floors.
    window.__previewFloor = function (lvl) {
      try {
        dungeonLevel = Math.max(1, lvl | 0);
        try { tutorialActive = false; } catch (e) {}
        try { floorThemeOverride = null; floorIslandTheme = null; previewForceIndoor = null; previewForceIsland = false; } catch (e) {}
        revivedInTown = false; closeTown(); recordDepth();
        statusEffects = []; setPlayerCell(5, 5); arrivalDir = 'down';
        generateMap();
        // keep the throwaway preview hero alive on deep floors long enough to
        // screenshot (deep enemies would one-shot a level-1 hero otherwise)
        player.hp = player.maxHp = 9999999; player.mp = player.maxMp = 9999999;
        if (typeof closeTitle === 'function') closeTitle();
        updateBars(); draw();
        let w = 0, l = 0, trees = 0, decor = 0;
        for (const k in decorMap) { decor++; if (DECOR_INDEX[decorMap[k]].ht >= 2.4) trees++; }
        for (let y = 0; y < MAP_H; y++) for (let x = 0; x < MAP_W; x++) { const t = mapData[y][x]; if (t === 6) w++; else if (t === 7) l++; }
        return { level: lvl, biome: (currentTheme().name || ''), indoor: !!currentTheme().indoor, island: !!floorIslandTheme, water: w, lava: l, trees, decor };
      } catch (e) { return { err: String(e) }; }
    };
    // Force an ISLAND floor and regenerate, so the sea-ringed layout can be
    // previewed deterministically (normally ~12% of outdoor floors, at random).
    window.__previewIsland = function (lvl) {
      try {
        dungeonLevel = Math.max(1, (lvl == null ? dungeonLevel : lvl) | 0);
        if (dungeonLevel % 5 === 0) dungeonLevel++;   // dodge boss floors (fixed arenas, no island)
        tutorialActive = false; floorThemeOverride = null; previewForceIndoor = null;
        previewForceIsland = true;
        revivedInTown = false; closeTown(); recordDepth();
        statusEffects = []; setPlayerCell(5, 5); arrivalDir = 'down';
        generateMap();
        previewForceIsland = false;
        player.hp = player.maxHp = 9999999; player.mp = player.maxMp = 9999999;
        if (typeof closeTitle === 'function') closeTitle();
        updateBars(); draw();
        let sea = 0;
        for (let y = 0; y < MAP_H; y++) for (let x = 0; x < MAP_W; x++) if (mapData[y][x] === 6) sea++;
        return { level: dungeonLevel, biome: (currentTheme().name || ''), island: !!floorIslandTheme, sea };
      } catch (e) { previewForceIsland = false; return { err: String(e) }; }
    };
    // Preview helper: stage a cracked wall (tile 10) on screen at a chosen hit
    // count, optionally pre-mask (raw full-tile fracture), park the hero a few
    // tiles off so its arrival beam never covers the crop, and report the wall's
    // on-screen rect — so a capture/smoke script can verify the fracture stays
    // locked to the rock instead of spilling onto the surrounding floor. Prefers
    // a lone rock (open floor on all four sides) — the worst case for spill.
    window.__previewCrackWall = function (hits, masked) {
      hits = (hits == null) ? MAX_CRACK_HITS - 1 : hits;
      previewNoCrackMask = (masked === false);
      let best = null, island = null;
      for (let y = 1; y < MAP_H - 1; y++) for (let x = 1; x < MAP_W - 1; x++) {
        if (mapData[y][x] !== 10) continue;
        const L = mapData[y][x - 1] === 0, R = mapData[y][x + 1] === 0;
        const U = mapData[y - 1][x] === 0, D = mapData[y + 1][x] === 0;
        if (L && R && U && D && !island) island = { x, y, L, R, U, D };
        if (((L && R) || (U && D)) && !best) best = { x, y, L, R, U, D };
      }
      best = island || best;
      if (!best) { for (let y = 1; y < MAP_H - 1 && !best; y++) for (let x = 1; x < MAP_W - 1; x++) if (mapData[y][x] === 10) best = { x, y, island: false }; }
      if (!best) return { err: 'no cracked wall' };
      let placed = false;
      for (const d of [4, 3, 2, 5]) { for (const [dx, dy] of [[d, 0], [-d, 0], [0, d], [0, -d]]) {
        const nx = best.x + dx, ny = best.y + dy;
        if (mapData[ny] && mapData[ny][nx] === 0) { setPlayerCell(nx, ny); placed = true; break; }
      } if (placed) break; }
      if (!placed) { const nb = [[best.x - 1, best.y], [best.x + 1, best.y], [best.x, best.y - 1], [best.x, best.y + 1]]; for (const [nx, ny] of nb) { if (mapData[ny] && mapData[ny][nx] === 0) { setPlayerCell(nx, ny); break; } } }
      wallCracks[best.y + ',' + best.x] = hits;
      updateBars(); draw();
      const tw = lastCam.tw, th = lastCam.th;
      const sx = Math.round(-lastCam.camX) + best.x * tw;
      const sy = Math.round(-lastCam.camY) + best.y * th;
      return { x: best.x, y: best.y, sx, sy, tw, th, sev: crackSeverity(hits), island: !!(best.L && best.R && best.U && best.D) };
    };
    // Position the hero just behind the TALLEST tree (prefer directly north) to
    // showcase occlusion. Clears the one-time depth banner for a clean shot.
    window.__previewBehindTree = function () {
      const open = (x, y) => mapData[y] && mapData[y][x] === 0 && furnitureMap[y + ',' + x] === undefined;
      const trees = [];
      for (const k in decorMap) { const d = DECOR_INDEX[decorMap[k]]; if (d && d.ht >= 2.0) { const c = k.split(','); trees.push({ tx: +c[1], ty: +c[0], ht: d.ht }); } }
      trees.sort((a, b) => b.ht - a.ht); // tallest first
      for (const T of trees) {
        const hx = T.tx, hy = T.ty - 1; // directly north → under the canopy
        if (open(hx, hy)) {
          setPlayerCell(hx, hy); player.fx = hx + 0.5; player.fy = hy + 0.5;
          draw();
          return { tx: T.tx, ty: T.ty, ht: T.ht, hx, hy, ok: true };
        }
      }
      draw(); return { ok: false };
    };
    // Preview A/B: toggle the clustered secondary/tertiary floor accents on the
    // CURRENT map (no regen) so a capture can shoot the same layout both ways.
    window.__previewMultiFloor = function (on) { previewFlatFloor = !on; draw(); return { multiFloor: on }; };
    // Render the EXACT terrain autotile set the current level composites (floor +
    // accents + wall + water + lava), straight from the live atlas — so what we
    // inspect always matches what's on screen. Returns a labeled contact sheet.
    window.__previewTileset = function () {
      const C = currentTheme();
      const B = terrainRoles(C);
      const roles = [];
      if (B.floor)  roles.push(['floor (primary)', B.floor]);
      if (B.floor2) roles.push(['floor accent 2', B.floor2]);
      if (B.floor3) roles.push(['floor accent 3', B.floor3]);
      if (B.wall)   roles.push(['WALL', B.wall]);
      if (B.water)  roles.push(['water', B.water]);
      roles.push(['lava', 'Lava']);
      const A = LPC_A, NC = LPC_NCOLS, Z = 4, order = [15, 1, 2, 4, 8, 3, 5, 10, 12, 7, 11, 13, 14, 6, 9];
      const rowH = A * Z + 26;
      const cv = document.createElement('canvas');
      cv.width = order.length * (A * Z + 3) + 16; cv.height = roles.length * rowH + 12;
      const g = cv.getContext('2d'); g.imageSmoothingEnabled = false;
      g.fillStyle = '#15131b'; g.fillRect(0, 0, cv.width, cv.height);
      roles.forEach(([label, name], ri) => {
        const tbl = LPC_TABLE.table[name] || {};
        const y = 10 + ri * rowH;
        g.fillStyle = '#e8c267'; g.font = 'bold 14px monospace';
        g.fillText(label + ':  ' + name, 10, y + 13);
        order.forEach((m, ci) => { const id = tbl[m]; if (id == null) return; const sx = (id % NC) * A, sy = ((id / NC) | 0) * A; g.drawImage(lpcSheet, sx, sy, A, A, 10 + ci * (A * Z + 3), y + 18, A * Z, A * Z); });
      });
      return { biome: C.name, indoor: !!C.indoor, roles: roles.map((r) => r[0] + '=' + r[1]), img: cv.toDataURL('image/png') };
    };
    // Debug overlay: paint each SOLID (furnitureMap) tile red over the current
    // frame, so a screenshot shows whether collision lines up with the sprites.
    window.__previewSolids = function (on) { previewDrawSolids = on !== false; draw(); return { solids: Object.keys(furnitureMap).length }; };
    // Put a status effect on the hero on demand, so the danger-halo smoke test can
    // raise a halo without waiting for a foe to land the right proc.
    window.__previewStatus = function (effect, secs) {
      applyStatusEffect('player', effect || 'poison', secs || 30, 'preview');
      return { effects: statusEffects.filter(s => s.target === 'player').map(s => s.effect) };
    };
    // The packed art sheets, for the atlas-blit smoke test: none of these may be
    // scaled onto the map straight from a source sub-rect (see atlasCell) — that
    // is what smeared a coloured box behind every sprite on iOS.
    window.__previewAtlasSheets = function () { return [spriteSheet, monsterSheet, bossSheet, decorSheet, furnSheet, terrSheet, intSheet]; };
    // Force a specific built-interior theme and regenerate, so indoor floors can be
    // previewed deterministically (normally they appear ~28% of floors at random).
    window.__previewIndoor = function (idx) {
      try {
        previewForceIndoor = (idx | 0);
        tutorialActive = false;
        revivedInTown = false; closeTown(); recordDepth();
        statusEffects = []; setPlayerCell(5, 5); arrivalDir = 'down';
        generateMap();
        player.hp = player.maxHp = 9999999; player.mp = player.maxMp = 9999999;
        if (typeof closeTitle === 'function') closeTitle();
        updateBars(); draw();
        let decor = 0, solid = 0;
        for (const k in decorMap) { decor++; if (DECOR_SOLID[decorMap[k]]) solid++; }
        const C = currentTheme();
        return { theme: C.name, floorStyle: C.floorStyle, wallStyle: C.wallStyle, decor, solid };
      } catch (e) { return { err: String(e) }; }
    };
    // __AUDIT__ (temporary): flood the REAL map from the player and report floor
    // tiles a decor piece walled off (full-map, no ASCII windowing artefacts).
    window.__connCheck = function () {
      // Flood treating every stationary OBJECT (solid decor/furniture + the two
      // shop NPCs) as a wall, then report any plain-floor tile it can't reach — a
      // stretch an object walled off. Breakable/openable TERRAIN is reachable in
      // play, so a cracked wall (10) and a vault door (11) count as passable here
      // (a floor pocket behind one is intended terrain, not an object block).
      // bad:0 means no object blocks a path.
      const pass = (x, y) => x >= 0 && y >= 0 && x < MAP_W && y < MAP_H && (isFloorPassable(mapData[y][x]) || mapData[y][x] === 10 || mapData[y][x] === 11) && !tileBlockedByObject(x, y);
      const seen = new Set([player.y + ',' + player.x]); const st = [[player.x, player.y]];
      while (st.length) { const [x, y] = st.pop(); for (const [dx, dy] of [[1,0],[-1,0],[0,1],[0,-1]]) { const nx = x+dx, ny = y+dy, k = ny+','+nx; if (seen.has(k) || !pass(nx, ny)) continue; seen.add(k); st.push([nx, ny]); } }
      let bad = 0; const detail = [];
      for (let y = 1; y < MAP_H-1; y++) for (let x = 1; x < MAP_W-1; x++) {
        if (mapData[y][x] === 0 && !tileBlockedByObject(x, y) && !seen.has(y+','+x)) {
          bad++;
          if (detail.length < 4) { const nb = [[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy]) => tileBlockedByObject(x+dx, y+dy) ? 'D' : mapData[y+dy][x+dx]).join(','); detail.push({ x, y, nb }); }
        }
      }
      // solids: how many tiles a stationary object makes solid (furniture + NPCs),
      // so a caller can tell the audit actually had objects to reason about.
      const npcs = (merchant ? 1 : 0) + (mystic ? 1 : 0);
      const solids = Object.keys(furnitureMap).length + npcs;
      return { bad, detail, solids, furniture: Object.keys(furnitureMap).length, npcs };
    };
    // __PATH_BLOCK_TEST__ (preview only): build a deterministic two-room floor
    // joined by a single 1-wide corridor, seal the corridor with a stationary
    // object, and prove the map-build guarantee (clearObjectBlockedPaths) reopens
    // it. Exercises both repair paths — stripping a solid decor piece and shoving a
    // shop NPC aside. Returns before/after counts so a smoke test can assert the heal.
    window.__pathBlockTest = function () {
      const out = { cases: [] };
      const solidBase = DECOR_INDEX.findIndex((d) => d.block === 'base'); // 1-tile solid decor
      const build = () => {
        MAP_W = 7; MAP_H = 5;
        mapData = [];
        for (let y = 0; y < MAP_H; y++) { mapData[y] = []; for (let x = 0; x < MAP_W; x++) mapData[y][x] = 1; }
        for (let x = 1; x <= 5; x++) { mapData[1][x] = 0; mapData[3][x] = 0; } // two rooms
        mapData[2][3] = 0;                                                     // sole join: corridor (3,2)
        furnitureMap = {}; decorMap = {}; teleporters = {}; merchant = null; mystic = null;
        floorSerial++; bumpMapEpoch(); pathGridDirty();
        player.x = 1; player.y = 1;
      };
      // Case 1 — solid decor plugging the corridor.
      try {
        build();
        decorMap['2,3'] = solidBase; furnitureMap['2,3'] = 1;
        const before = window.__connCheck().bad;
        clearObjectBlockedPaths();
        const after = window.__connCheck().bad;
        out.cases.push({ kind: 'decor', before, after, freed: furnitureMap['2,3'] === undefined, anchorGone: decorMap['2,3'] === undefined });
      } catch (e) { out.cases.push({ kind: 'decor', err: String(e) }); }
      // Case 2 — a shop NPC (mystic) standing on the corridor.
      try {
        build();
        mystic = { x: 3, y: 2 };
        const before = window.__connCheck().bad;
        clearObjectBlockedPaths();
        const after = window.__connCheck().bad;
        out.cases.push({ kind: 'npc', before, after, moved: !mystic || mystic.x !== 3 || mystic.y !== 2 });
      } catch (e) { out.cases.push({ kind: 'npc', err: String(e) }); }
      // Case 3 — two regions joined by a TERMINAL stair (top) and an object (bottom).
      // Once the object seals the bottom branch, the right region is reachable only
      // by walking PAST the stairs — impossible on foot. __connCheck can't see this
      // (it treats stairs as passable), so verify with the game's own foot-reach:
      // the right region must go from unreachable → reachable, by clearing the object.
      try {
        MAP_W = 7; MAP_H = 5;
        mapData = [];
        for (let y = 0; y < MAP_H; y++) { mapData[y] = []; for (let x = 0; x < MAP_W; x++) mapData[y][x] = 1; }
        mapData[1][1] = 0; mapData[1][2] = 0; mapData[1][3] = 2; mapData[1][4] = 0; mapData[1][5] = 0; // stair(2) at (3,1)
        mapData[2][1] = 0; mapData[2][5] = 0;
        mapData[3][1] = 0; mapData[3][2] = 0; mapData[3][3] = 0; mapData[3][4] = 0; mapData[3][5] = 0; // bottom branch
        furnitureMap = {}; decorMap = {}; teleporters = {}; merchant = null; mystic = null;
        floorSerial++; bumpMapEpoch(); pathGridDirty();
        player.x = 1; player.y = 1;
        decorMap['3,3'] = solidBase; furnitureMap['3,3'] = 1;                     // object on the bottom branch
        // Object-AWARE foot reachability (objects solid, stairs terminal) — the real
        // in-play walkability. reachableOnFoot ignores objects, so it can't see this.
        const objFoot = () => footReach(MAP_W, MAP_H, player.x, player.y,
          (x, y) => isEnterable(mapData[y][x]) && !tileBlockedByObject(x, y),
          (x, y) => isWalkThrough(mapData[y][x]) && !tileBlockedByObject(x, y));
        const rightBefore = objFoot().has('3,4');                                 // right region tile (4,3)
        clearObjectBlockedPaths();
        const rightAfter = objFoot().has('3,4');
        out.cases.push({ kind: 'terminal', rightBefore, rightAfter, freed: furnitureMap['3,3'] === undefined });
      } catch (e) { out.cases.push({ kind: 'terminal', err: String(e) }); }
      // Case 4 — a shop NPC standing on a 1-wide corridor that a DETOUR keeps
      // connected. Two rooms joined by a top AND a bottom 1-wide corridor form a
      // loop; an NPC on the top corridor (4,1) fully blocks that hall, yet every
      // tile stays reachable via the bottom one — so __connCheck sees nothing
      // (bad stays 0). The guarantee must still shove the NPC off the corridor.
      try {
        MAP_W = 9; MAP_H = 5;
        mapData = [];
        for (let y = 0; y < MAP_H; y++) { mapData[y] = []; for (let x = 0; x < MAP_W; x++) mapData[y][x] = 1; }
        for (let x = 1; x <= 7; x++) { mapData[1][x] = 0; mapData[3][x] = 0; }      // top + bottom halls (join the rooms)
        for (const x of [1, 2, 3, 5, 6, 7]) mapData[2][x] = 0;                       // room middles; (4,2) stays wall → a real loop
        furnitureMap = {}; decorMap = {}; teleporters = {}; merchant = null; mystic = null;
        floorSerial++; bumpMapEpoch(); pathGridDirty();
        player.x = 2; player.y = 2;                                                  // left room
        mystic = { x: 4, y: 1 };                                                     // top-corridor through-tile
        const connBefore = window.__connCheck().bad;                                 // 0 — detour keeps it connected
        const plugBefore = window.__corridorPlugCheck().plugged;                     // 1 — NPC in a 1-wide hall
        clearObjectBlockedPaths();
        const plugAfter = window.__corridorPlugCheck().plugged;
        const connAfter = window.__connCheck().bad;
        out.cases.push({ kind: 'detour-npc', connBefore, connAfter, plugBefore, plugAfter,
          moved: !mystic || mystic.x !== 4 || mystic.y !== 1 });
      } catch (e) { out.cases.push({ kind: 'detour-npc', err: String(e) }); }
      return out;
    };
    // __DECOR_PLUG_CHECK__ (preview only): a SOLID multi-tile piece (bed/table/
    // sofa) must sit wholly inside a room, never bridging a doorway or corridor —
    // otherwise it plugs a hall you can't walk down (and a detour keeps the floor
    // connected, so __connCheck can't see it). Reports pieces whose footprint is
    // NOT inside any room, plus (independently of the room test) pieces whose
    // footprint straddles a true 1-wide through-corridor tile, so a smoke test can
    // assert both are zero. outside:0 && corridor:0 means no piece plugs a path.
    window.__decorPlugCheck = function () {
      // Judge a 1-wide passage by what the hero can walk THROUGH (isWalkThrough) —
      // matching the heal (clearCorridorPlugs/onThroughCorridor), __corridorPlugCheck,
      // and isThroughCorridor's own contract. A walkable perpendicular neighbour
      // (spike/shrine/fountain/lava) means a detour exists, so the tile isn't truly
      // 1-wide: a room piece merely adjacent to such a hazard is NOT a plug. (Judging
      // by strict floor flagged those as false positives — the sweep's flake.)
      const walk = (x, y) => isWalkThrough(mapData[y][x]);
      const throughTile = (x, y) => isThroughCorridor(x, y, MAP_W, MAP_H, walk);
      let outside = 0, corridor = 0; const detail = [];
      for (const k in decorMap) {
        const id = decorMap[k]; if (!DECOR_SOLID[id]) continue;
        const c = k.indexOf(','); const ay = +k.slice(0, c), ax = +k.slice(c+1);
        const foot = decorFootprint(id, ax, ay);
        if (foot.length <= 1) continue;                       // single-tile clutter can't plug
        const inRoom = footprintInsideRoom(foot, floorRooms);
        const onCorridor = foot.some(([fx, fy]) => throughTile(fx, fy));
        if (!inRoom) outside++;
        if (onCorridor) corridor++;
        if ((!inRoom || onCorridor) && detail.length < 4) detail.push({ ax, ay, id, footLen: foot.length, inRoom, onCorridor });
      }
      return { outside, corridor, detail, decor: Object.keys(decorMap).length, solid: Object.keys(furnitureMap).length };
    };
    // __CORRIDOR_PLUG_CHECK__ (preview only): the GENERAL guarantee — NO impassable
    // object (solid decor/furniture OR a shop NPC), single- or multi-tile, may sit
    // on a 1-wide through-corridor tile, on ANY floor (outdoor caves included, not
    // just built interiors). Such a tile fully blocks that hall even when a detour
    // keeps the floor connected, so __connCheck (a disconnection flood) can't see
    // it. Judged by what the hero walks THROUGH (isWalkThrough), so a passable
    // perpendicular neighbour means the tile isn't really 1-wide. plugged:0 = clean.
    window.__corridorPlugCheck = function () {
      const walk = (x, y) => isWalkThrough(mapData[y][x]);
      const onCorr = (x, y) => isThroughCorridor(x, y, MAP_W, MAP_H, walk);
      let plugged = 0; const detail = [];
      for (const k in furnitureMap) {
        const c = k.indexOf(','); const y = +k.slice(0, c), x = +k.slice(c + 1);
        if (onCorr(x, y)) { plugged++; if (detail.length < 4) detail.push({ x, y, kind: 'furniture' }); }
      }
      for (const [name, npc] of [['merchant', merchant], ['mystic', mystic]]) {
        if (npc && npc.x >= 0 && onCorr(npc.x, npc.y)) { plugged++; if (detail.length < 4) detail.push({ x: npc.x, y: npc.y, kind: name }); }
      }
      const npcs = (merchant ? 1 : 0) + (mystic ? 1 : 0);
      return { plugged, detail, objects: Object.keys(furnitureMap).length + npcs, furniture: Object.keys(furnitureMap).length, npcs };
    };
  }
} catch (e) {}

// Reflect any saved mute preference on the SOUND button, then arm the audio:
// browsers won't let sound start until the player interacts, so the first
// gesture resumes the context and kicks off the looping music.
updateSoundButtons();
updateMixButtons();
updateSprintButton();
updateHeroBarsButton();
updateCrosshairButton();
updatePathLineButton();
updateStairsArrowButton();
updateMonsterArrowsButton();
updateScreenShakeButton();
updateScreenFlashButton();
['pointerdown', 'keydown'].forEach(ev =>
  window.addEventListener(ev, audioUnlock, { passive: true }));

// Redraw once layout has settled so the camera fits the real canvas size, and
// open + populate the permanent loot drawer.
syncWebPanel();
requestAnimationFrame(() => { resizeCanvas(); draw(); });
window.addEventListener('load', () => { syncWebPanel(); resizeCanvas(); draw(); });
// Once the emoji/icon fonts have finished loading, repaint so any glyphs that
// weren't yet resident on the first frame bake into the sprite cache and show.
if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => draw());

// ══════════════════════════════════════════
// REAL-TIME GAME LOOP
// ══════════════════════════════════════════
// One requestAnimationFrame loop drives the whole game. Every frame the hero
// moves freely, auto-attacks foes in reach, enemy sprites glide toward their
// logic cells, and a fixed-step "world clock" advances the old per-turn upkeep
// (status, regen, cooldowns, enemy actions, hazards, quests). The canvas is
// repainted every frame.

// Movement / combat / hazards all freeze while a menu or overlay is up, in town,
// or once the hero has fallen. The persistent web-layout sidebar (panelOpen always
// true) must NOT count, or web players could never move. The WORLD CLOCK is gated
// separately (clockPaused) so time keeps flowing in town — see gameLoop.
const RT_BLOCKING_OVERLAYS = ['title-overlay','name-overlay','class-overlay','hc-death-overlay','death-overlay',
  'shop-overlay','mystic-overlay','town-overlay','settings-menu','version-overlay','howto-overlay','wiki-overlay',
  'autoloot-overlay','keybind-overlay',
  // Reachable mid-dungeon (e.g. from the menu or on a tier conquest) — these
  // close the settings menu, so they must pause the world on their own.
  'conquest-overlay','slots-overlay','account-overlay','lb-overlay','lb-hero-overlay','graveyard-overlay','slotpick-overlay',
  'greed-overlay',    // the risk/reward cursed-floor choice pauses the world while open
  'boss-gate-overlay'];   // the "are you ready?" boss-floor threshold prompt pauses the world too
  // (Beach-tutorial nudges are non-blocking pills now — see refreshTutorialCues — so they no longer pause play.)
// The blocking overlays are all static shell divs (only their 'open' class
// toggles), so resolve id → element ONCE and reuse — rtPaused/clockPaused run
// several times per frame and were re-querying every id on every call.
// townRest marks the town hub/shop/mystic menus the clock ignores while resting
// in town (see clockPaused / TOWN_REST_OVERLAYS below).
let _rtOverlayEls = null;
function rtOverlayEls() {
  if (!_rtOverlayEls) {
    _rtOverlayEls = [];
    for (const id of RT_BLOCKING_OVERLAYS) {
      const el = document.getElementById(id);
      if (el) _rtOverlayEls.push({ el, townRest: TOWN_REST_OVERLAYS.includes(id) });
    }
  }
  return _rtOverlayEls;
}
// ── Touch-only pause: bag drawer + pop-up menus ──
// On the touch layout, opening the bag/loot drawer or a menu that isn't already a
// world-freezing modal (the achievements popup, the bestiary/codex) should still
// freeze play — a phone player can't watch the field behind a full-screen sheet.
// Desktop is deliberately untouched: its loot drawer is a permanent sidebar
// (panelOpen always true) that must never pause, and every check here is gated on
// isTouchMode(), so a mouse machine is byte-identical. These menus pause ONLY here,
// never via RT_BLOCKING_OVERLAYS, so desktop keeps playing behind them as before.
const TOUCH_ONLY_OVERLAYS = ['achievements-overlay', 'bestiary-overlay'];
let _touchOverlayEls = null;
function touchOnlyOverlayEls() {
  if (!_touchOverlayEls) {
    _touchOverlayEls = [];
    for (const id of TOUCH_ONLY_OVERLAYS) {
      const el = document.getElementById(id);
      if (el) _touchOverlayEls.push(el);
    }
  }
  return _touchOverlayEls;
}
function touchMenuOpen() {
  if (!isTouchMode()) return false;
  if (document.body.classList.contains('bag-open')) return true;   // the touch loot/bag drawer sheet
  for (const el of touchOnlyOverlayEls()) {
    if (el.classList.contains('open')) return true;
  }
  return false;
}
function rtPaused() {
  if (gameHalted || player.hp <= 0) return true;
  if (_tutGate) return true;             // a tutorial spotlight gate freezes play until its lesson is done
  // The town is walkable now: movement runs while the hero roams the plaza, and
  // pauses only when a service overlay (shop/mystic/town) is opened on top — those
  // are in rtOverlayEls() below, so no explicit inTown freeze is needed. (Combat,
  // skills and hazards stay inert in town via the gameLoop's !inTown gate.)
  if (touchLandscapeBlock) return true;  // portrait-only on touch — frozen while the rotate notice is up
  if (portalTransiting()) return true;   // hero is mid-teleport (off the map) — no moving/fighting/being hit
  if (mapWarping()) return true;         // walking through a teleporter pad — frozen mid-traversal
  for (const o of rtOverlayEls()) {
    if (o.el.classList.contains('open')) return true;
  }
  if (touchMenuOpen()) return true;      // touch only: bag drawer / pop-up menu freezes play (desktop sidebar never does)
  return false;
}

// The town's own hub / shop / mystic menus are the RESTING state in town — with one
// of them topmost the hero is simply idling in the safe haven, so time still flows.
const TOWN_REST_OVERLAYS = ['town-overlay', 'shop-overlay', 'mystic-overlay'];
// Whether the WORLD CLOCK (HP/MP regen, skill & potion cooldowns, status & buff
// timers) should hold. Outside town this mirrors rtPaused. In town the clock keeps
// ticking — time passes just like standing still in the dungeon — pausing only for
// a hard stop (death / halt) or a generic modal (settings, bag, version…) opened on
// top of the hub, exactly as those same menus pause the world down below.
function clockPaused() {
  if (gameHalted || player.hp <= 0) return true;
  if (_tutGate) return true;             // freeze regen/cooldowns too, so the gated flask stays quaffable
  if (portalTransiting()) return true;   // freeze the scene (and ambient anim) while the hero teleports
  if (mapWarping()) return true;         // freeze the scene while the hero walks through a teleporter pad
  for (const o of rtOverlayEls()) {
    if (inTown && o.townRest) continue;   // resting in town → clock runs
    if (o.el.classList.contains('open')) return true;
  }
  if (touchMenuOpen()) return true;       // touch only: an open bag/menu holds the clock too
  return false;
}

// ── AUTO-ATTACK TARGET PRIORITY ──
// Which in-reach foe the hero's auto-attack locks onto. Cycled from the gear menu
// and saved per character. Lower score = higher priority; distance breaks ties.
const TARGET_MODES = [
  { id: 'closest',  short: 'CLOSEST',  label: 'Closest',         desc: 'Strike the nearest foe (default).' },
  { id: 'lowest',   short: 'WEAKEST',  label: 'Weakest',         desc: 'Focus the foe with the least health — finish kills fast.' },
  { id: 'highest',  short: 'TOUGHEST', label: 'Toughest',        desc: 'Focus the beefiest foe (highest max HP).' },
  { id: 'farthest', short: 'FARTHEST', label: 'Farthest',        desc: 'Strike the furthest foe in range — good for kiting.' },
  { id: 'elite',    short: 'ELITES',   label: 'Elites & bosses', desc: 'Prioritize elites and bosses, then the closest foe.' },
];
function targetMode() { return (player && player.targetMode) || 'closest'; }
function autoTargetScore(e, d, mode) {
  switch (mode) {
    case 'lowest':   return e.hp;
    case 'highest':  return -(e.maxHp || e.hp);
    case 'farthest': return -d;
    case 'elite':    return (e.isBoss ? 0 : e.isElite ? 1e6 : 2e6) + d;
    case 'closest':
    default:         return d;
  }
}
function cycleTargetMode() {
  const i = TARGET_MODES.findIndex(m => m.id === targetMode());
  player.targetMode = TARGET_MODES[(i + 1) % TARGET_MODES.length].id;
  updateTargetModeUi();
  if (typeof sfx === 'function') sfx('click');
  if (typeof saveGame === 'function') saveGame();
}
function updateTargetModeUi() {
  const m = TARGET_MODES.find(x => x.id === targetMode()) || TARGET_MODES[0];
  const el = document.getElementById('target-mode-label');
  if (el) el.textContent = m.short;
  const btn = document.getElementById('target-mode-action');
  if (btn) btn.dataset.tip = "<div class='ht-name'><span data-spr=ui_agility></span> Auto-attack focus: " + m.label + "</div><div class='ht-line'>" + m.desc + "</div><div class='ht-sub'>Click to cycle</div>";
}

// Pick the in-reach foe the auto-attack should strike, honoring the player's
// focus mode (closest/weakest/…). Returns null when nothing is in weapon reach
// (ranged/reach weapons need line of sight). Kept separate from the swing gating
// so the crosshair can track the target even mid-cooldown.
function pickAutoTarget() {
  if (typeof enemies === 'undefined' || !player || inTown) return null;
  const style = weaponStyle();
  const range = weaponRangeOf(equipped.weapon) || STYLE_RANGE[style] || 1;
  const ranged = range >= 2;
  const mode = targetMode();
  let best = null, bestScore = Infinity, bestD = Infinity;
  for (const e of enemies) {
    if (e.dead) continue;
    const d = footReachDist(e);                    // fractional reach from the body centre
    if (d > range + MELEE_REACH_BONUS) continue;   // …plus a half-tile of forgiveness
    if (ranged && !hasLineToPlayer(e)) continue;  // can't shoot through walls
    const score = autoTargetScore(e, d, mode);    // pick by the player's target priority
    if (score < bestScore || (score === bestScore && d < bestD)) { bestScore = score; bestD = d; best = e; }
  }
  return best;
}

// Auto-attack: when the cooldown is up, strike the nearest foe in weapon reach
// (ranged/reach weapons need line of sight). Mirrors the old per-turn swing, just
// fired on a timer instead of a key press. Rooted while channeling / stunned.
function updatePlayerCombat(dt) {
  if (player.atkCd > 0) player.atkCd -= dt;
  autoAttackTarget = pickAutoTarget();   // keep the crosshair fresh even between swings
  if (player.atkCd > 0 || portalChanneling() || isPlayerStunned()) return;
  const best = autoAttackTarget;
  if (!best) return;
  const style = weaponStyle();
  const range = weaponRangeOf(equipped.weapon) || STYLE_RANGE[style] || 1;
  const ranged = range >= 2;
  if (style === 'bolt') { if (player.mp < 4) return; player.mp -= 4; } // staff bolt spends a little MP
  if (best.x > player.x) player.facing = 'right'; else if (best.x < player.x) player.facing = 'left';
  entryGuard = false;   // swinging ends arrival grace
  attackEnemy(best, { ranged, style });
  player.atkCd = playerAttackInterval();
}

// Skill & potion cooldowns burn down in real seconds (the same dt clock the
// attack cooldown uses), so their on-screen numbers read as a plain seconds
// countdown instead of abstract world-turns. Floored at 0 so they never undershoot.
function tickCooldowns(dt) {
  if (player.potionCd > 0) { player.potionCd -= dt; if (player.potionCd < 0) player.potionCd = 0; }
  if (player.skillCds) for (const k in player.skillCds) {
    if (player.skillCds[k] > 0) { player.skillCds[k] -= dt; if (player.skillCds[k] < 0) player.skillCds[k] = 0; }
  }
}

// Drive the live cooldown dials each frame: sweep the grey overlay from full to
// empty and show the countdown (whole seconds, then one decimal under 1s). When
// a skill/potion finishes recharging, refresh the bar so it reads as ready.
function updateCooldownDials() {
  const bar = hudEl('skill-bar');
  if (!bar) return;
  let finished = false;
  // The dials live inside the markup renderSkillBar caches — re-resolve them only
  // after a rebuild (_sbCdEls is nulled there) instead of querying every frame.
  if (!_sbCdEls) {
    _sbCdEls = [];
    bar.querySelectorAll('.sb-cd').forEach(el =>
      _sbCdEls.push({ el, btn: el.parentNode, id: el.getAttribute('data-cd') }));
  }
  for (const d of _sbCdEls) {
    const el = d.el, btn = d.btn, id = d.id;
    let rem = 0, total = 1;
    if (id === 'pot') { rem = player.potionCd || 0; total = POTION_CD; }
    else if (id && id.indexOf('sk:') === 0) { const sid = id.slice(3); rem = skillCd(sid); total = skillCdMax[sid] || rem || 1; }
    if (rem > 0.05) {
      if (!btn.classList.contains('cooling')) btn.classList.add('cooling');
      const frac = total > 0 ? Math.max(0, Math.min(1, rem / total)) : 0;
      // Skip the CSSOM/text writes when the displayed value hasn't changed (the
      // expando last-values die with the element on any bar rebuild).
      const fracTxt = frac.toFixed(3);
      if (el._cdFrac !== fracTxt) { el._cdFrac = fracTxt; el.style.setProperty('--cd-frac', fracTxt); }
      const txt = rem >= 1 ? String(Math.ceil(rem)) : rem.toFixed(1);
      if (el._cdNum !== txt) { el._cdNum = txt; el.textContent = txt; }
    } else if (btn.classList.contains('cooling')) {
      finished = true; // came off cooldown — rebuild so it reads as ready
    }
  }
  if (finished) renderSkillBar();
}

// Slide every enemy sprite toward its logic cell each frame so cell-to-cell steps
// read as smooth motion. Big displacements (knockback, blink, a 2-tile dash) snap
// rather than drift through walls. Lazy-inits fx/fy for foes spawned mid-floor.
// Glide an actor's render centre (a.fx/a.fy) toward its logic cell (tx,ty) at a
// CONSTANT velocity — the way the hero moves — instead of an ease-in that
// decelerates on arrival (which read as a tile-to-tile hop). When the logic cell
// steps to a new tile, we set a speed that covers the gap in exactly one world
// beat, so the sprite arrives just as the next step begins: seamless, continuous
// 8-direction motion, never a pop. A large jump (blink/teleport/floor rebuild)
// snaps rather than sliding across the room. Render-only: logic positions,
// collision and completion checks are untouched. `gx0/gy0` cache the last target
// tile; `gsp` is the glide speed (tiles/sec). Returns the heading for facing.
function glideActor(a, tx, ty, dt) {
  if (a.fx == null) { a.fx = tx; a.fy = ty; a._gx0 = tx; a._gy0 = ty; a._gsp = 0; return; }
  // Only a real teleport (blink, floor rebuild) snaps; a normal 1-2 tile step — even
  // a swift foe's double step or a diagonal — glides. (1.6 used to snap those.)
  if (Math.abs(tx - a.fx) > 3.2 || Math.abs(ty - a.fy) > 3.2) { a.fx = tx; a.fy = ty; a._gx0 = tx; a._gy0 = ty; a._gsp = 0; return; }
  if (tx !== a._gx0 || ty !== a._gy0) {                 // stepped to a new tile
    const gap = Math.hypot(tx - a.fx, ty - a.fy);
    a._gsp = gap / WORLD_TICK_SECONDS;                  // cover it in one beat → constant speed
    a._gx0 = tx; a._gy0 = ty;
  }
  const dx = tx - a.fx, dy = ty - a.fy, dist = Math.hypot(dx, dy);
  if (dist > 1e-4) {
    const stepLen = Math.min(dist, (a._gsp || (1 / WORLD_TICK_SECONDS)) * dt);
    a.fx += dx / dist * stepLen; a.fy += dy / dist * stepLen;
    a.faceDx = dx; a.faceDy = dy;                       // remember heading (for facing)
  }
}
// Slowly stroll the wandering town keepers around their own patch of the clearing,
// and keep each keeper's LOGIC tile (n.x/n.y — what interaction, the walk-up prompt
// and click-to-interact all key off) locked to where its sprite actually is. Cheap
// (≤ a dozen keepers, neighbours only picked at a dwell boundary — no per-frame
// allocation) and only runs while the walkable town is on screen.
function updateTownNpcs(dt) {
  if (!inTown || !townNpcs.length) return;
  // A legal wander tile is a reachable free tile that is NOT inside the endgame
  // sanctum — the free-set already excludes the grove, but re-checking here keeps
  // the strolling keepers out of the endgame room even if that set ever drifts.
  const isFree = (x, y) => townFreeSet != null && townFreeSet.has(x + ',' + y) && !inSanctum(x, y, TOWN_SANCTUM);
  for (const n of townNpcs) {
    if (!n.wander) continue;
    const dx = n.tx - n.fx, dy = n.ty - n.fy;
    const dist = Math.hypot(dx, dy);
    if (dist < 0.05) {
      // Arrived on the target tile — snap, then pause a beat before the next step so
      // the amble reads as unhurried rather than a constant shuffle.
      n.fx = n.tx; n.fy = n.ty; n.x = n.tx; n.y = n.ty;
      n.dwell -= dt;
      if (n.dwell <= 0) {
        // Every OTHER keeper's tile is off-limits — both where it stands now (x,y) and
        // where it's headed (tx,ty) — so two townsfolk never amble onto the same tile
        // or cross straight through each other. Includes the standing (stall) keepers
        // and the fixed endgame keepers, so a wanderer never overlaps them either.
        const taken = new Set();
        for (const o of townNpcs) {
          if (o === n) continue;
          taken.add(o.x + ',' + o.y);
          taken.add(o.tx + ',' + o.ty);
        }
        const isBlocked = (x, y) => taken.has(x + ',' + y);
        const next = pickWanderTarget({ x: n.x, y: n.y }, { x: n.homeX, y: n.homeY }, TOWN_WANDER.radius, isFree, Math.random, isBlocked);
        if (next) { n.tx = next.x; n.ty = next.y; }
        n.dwell = TOWN_WANDER.dwellMin + Math.random() * (TOWN_WANDER.dwellMax - TOWN_WANDER.dwellMin);
      }
    } else {
      const step = Math.min(dist, TOWN_WANDER.speed * dt);
      n.fx += dx / dist * step; n.fy += dy / dist * step;
      n.faceDx = dx; n.faceDy = dy;
      n.x = Math.round(n.fx); n.y = Math.round(n.fy);   // keep the interaction tile under the sprite
    }
  }
}

function updateActorRender(dt) {
  for (const e of enemies) {
    if (e.atkCd > 0) e.atkCd -= dt;               // real-time attack cooldown
    const s = e.size || 1;
    // Every foe — aggro vermin, lumbering brute, or multi-tile boss — glides its
    // sprite toward its OWN logic cell (e.x/e.y), the tile the AI, collision and
    // attacks all key off. This is the hero's model, inverted: the hero derives its
    // cell from its smooth position; a foe derives its smooth position from its
    // cell. Either way the sprite and the logic tile stay locked together, so the
    // sprite never drifts a tile away from — or across a wall from — where the foe
    // actually is, and a bolt or lunge launched from the sprite lands true. (Foes
    // used to beeline the sprite at the hero's live sub-tile position, letting it
    // lead its cell by up to ~0.85 tiles — the source of "the animation came from
    // the tile next to the enemy.") glideActor covers each cell-to-cell step in one
    // world beat at constant velocity, so a pursuit still reads as smooth, unbroken
    // motion; a real teleport (blink, floor rebuild) snaps instead of sliding.
    glideActor(e, e.x + s / 2, e.y + s / 2, dt);  // footprint centre
  }
  // The quest NPC (an escorted follower, or a wandering lost pet) glides toward its
  // logic cell in the same top-left convention as npc.x/npc.y (the draw code adds
  // the +0.5 centre offset), so it reads as fluid follow movement, not a snap.
  if (quest && quest.npc) glideActor(quest.npc, quest.npc.x, quest.npc.y, dt);
}

// ── Attack speed ──
// Baseline ~1 swing / 1.5s for the hero, faster for light weapons (daggers) and
// slower for heavy ones (mauls/axes), then sped up by the ATKSPD gear stat AND by
// your Agility (agiAtkSpeedPct), both pooled into the same speed % so a nimble
// hero swings noticeably faster than a sluggish one.
const PLAYER_ATK_BASE = 1.5;
const STYLE_ATK_MULT = { flurry: 0.7, slash: 1, cleave: 1.25, crush: 1.4, reap: 1.2, thrust: 1.05, shot: 1.05, bolt: 1.15, fist: 0.85 };
function playerAttackSpeedPct() { return Math.max(0, totalStat('ATKSPD')) + agiAtkSpeedPct() + shrineFx('atkSpdPct') * 100; } // + Haste shrine
function playerAttackInterval() {
  const m = STYLE_ATK_MULT[weaponStyle()] || 1;
  return PLAYER_ATK_BASE * m / (1 + playerAttackSpeedPct() / 100);
}
// Foes swing on their own clock too, varied by type so a pack doesn't strike in
// lockstep: swift vermin jab fast, brutes are slow, casters middling. A per-foe
// jitter spreads them out further.
const ENEMY_ATK_BASE = 1.5;
function enemyAttackInterval(e) {
  const beh = BEHAVIORS[e.behavior] || BEHAVIORS.chaser;
  if (e._atkJit == null) e._atkJit = 0.85 + Math.random() * 0.3;
  // ÷ the season affix's attack-speed multiplier: a Frenzied season shortens every
  // foe's wind-up. 1 (no change) unless an enrolled hero's Cycle says otherwise.
  return ENEMY_ATK_BASE * (beh.atkMult || 1) * (e.isBoss ? 0.8 : 1) * e._atkJit / egSeasonAtkSpeed();
}
let _worldAcc = 0, _saveTick = 0, _worldTicks = 0;
// One beat of world upkeep, on a fixed real-time cadence (every WORLD_TICK_MS).
function worldTick() {
  _worldTicks++;   // world-beat serial — lets per-frame checks (unstickPlayer) skip re-testing a still world
  // Transient combat buffs (War Cry, Sanctuary, …) age out in real seconds on the
  // world clock. Skill and potion cooldowns burn down in real seconds too — see
  // tickCooldowns().
  for (const k in combatBuffs) { const b = combatBuffs[k]; if (b && b.secs > 0) { b.secs -= WORLD_TICK_SECONDS; if (b.secs <= 0) delete combatBuffs[k]; } }
  // The hero's own upkeep first (DoT, regen) — this damage never breaks a portal.
  tickStatusEffects();
  applyRegen();
  const hpBeforeEnemies = player.hp;   // only foe/hazard damage past here shatters a channel
  portalStruck = false;                // clear the "blow landed" flag; only this tick's foe/hazard hits count
  // Allies, then foes, then hazards age — guarded against the floor being rebuilt
  // mid-pass (a death-warp or boss kill swaps the enemies array).
  runMinionTurn();
  const serial = floorSerial;
  // Snapshot the living foes: a boss that summons mid-pass must NOT let the fresh
  // minions act on this same tick (matches the old turn loop).
  const acting = enemies.filter(e => !e.dead);
  for (const e of acting) {
    if (floorSerial !== serial) break;
    if (!e.dead) enemyAct(e);
  }
  if (floorSerial === serial) tickBossHazards();
  moveQuestEntities();
  tickPortalChannel(hpBeforeEnemies);
  renderSkillBar();
  updateBars();
  // Endgame per-tick drivers: advance an active Pantheon fight (phases/adds/enrage)
  // and tick the seasonal Cycle journey. Both guard themselves when inactive.
  if (_egPinnacleFight) { try { egPinnacleTick(); } catch (e) {} }
  try { egCycleTick(); } catch (e) {}
  if ((++_saveTick % 8) === 0) saveGame();   // persist every ~8 ticks instead of every action
}
// Advance the world clock by dt seconds, running whole ticks. Capped at 2 catch-up
// ticks per frame so a long stall (tab-out) can't drain many turns at once.
function stepWorldClock(dt) {
  _worldAcc += dt * 1000;
  let n = 0;
  while (_worldAcc >= WORLD_TICK_MS && n < 2) { _worldAcc -= WORLD_TICK_MS; worldTick(); n++; }
  if (_worldAcc > WORLD_TICK_MS) _worldAcc = WORLD_TICK_MS;
}

// ── PERF HUD (dev tool) ──
// Console-toggled frame profiler: type perfHud() to show/hide a small fixed
// overlay (top-right, click-through) with fps, worst frame, and entity/DOM
// counts. Hidden by default and, while hidden, perfFrameSample() bails on its
// first check — zero per-frame cost for players.
let _perfHudEl = null;
let _perfHudOn = false;
let _perfLastTs = 0;                     // own delta — the loop's dt is clamped, this sees real stalls
let _perfFrames = 0, _perfDtSum = 0, _perfWorst = 0;
let _perfWinStart = 0;                   // start of the rolling 1s sample window
let _perfAvgMs = 0, _perfWorstMs = 0;    // last completed window's numbers
let _perfNextPaint = 0;                  // overlay repaints at most every ~500ms
let _perfDomCount = 0, _perfNextDomScan = 0;  // querySelectorAll('*') is pricey — at most 1/s
// Called once per frame from gameLoop with the rAF timestamp (dt unused: the
// loop clamps it at 100ms, which would hide exactly the stalls we're hunting).
function perfFrameSample(ts, dt) {
  if (!_perfHudOn) return;               // hidden → free
  if (_perfLastTs) {
    const ms = ts - _perfLastTs;
    _perfFrames++; _perfDtSum += ms;
    if (ms > _perfWorst) _perfWorst = ms;
  } else {
    _perfWinStart = ts;                  // first sample after toggle-on anchors the window
  }
  _perfLastTs = ts;
  if (ts - _perfWinStart >= 1000) {
    _perfAvgMs = _perfFrames ? _perfDtSum / _perfFrames : 0;
    _perfWorstMs = _perfWorst;
    _perfFrames = 0; _perfDtSum = 0; _perfWorst = 0; _perfWinStart = ts;
  }
  if (ts < _perfNextPaint) return;
  _perfNextPaint = ts + 500;
  if (ts >= _perfNextDomScan) {
    _perfDomCount = document.querySelectorAll('*').length;
    _perfNextDomScan = ts + 1000;
  }
  const logEl = _logEl || document.getElementById('log');
  const fps = _perfAvgMs > 0 ? Math.round(1000 / _perfAvgMs) : 0;
  _perfHudEl.textContent =
    `fps ${fps}  avg ${_perfAvgMs.toFixed(1)}ms  worst ${_perfWorstMs.toFixed(1)}ms\n` +
    `enemies ${enemies.length}  particles ${particles.length}  projectiles ${projectiles.length}\n` +
    `log ${logEl ? logEl.childElementCount : 0}  dom ${_perfDomCount}`;
}
function perfHud() {
  if (!_perfHudEl) {                     // built lazily — players never pay for it
    _perfHudEl = document.createElement('div');
    _perfHudEl.className = 'perf-hud';
    document.body.appendChild(_perfHudEl);
  }
  _perfHudOn = !_perfHudOn;
  _perfHudEl.style.display = _perfHudOn ? 'block' : 'none';
  // Reset the window so a fresh toggle-on doesn't average across the gap.
  _perfLastTs = 0; _perfFrames = 0; _perfDtSum = 0; _perfWorst = 0;
  _perfWinStart = 0; _perfNextPaint = 0; _perfNextDomScan = 0;
  return _perfHudOn ? 'perf HUD on' : 'perf HUD off';
}

// Run one frame step in isolation. A thrown error in any subsystem (movement,
// combat, the world clock, draw…) must NOT cascade and freeze the whole game —
// otherwise a single bad frame becomes a permanent hang where movement, enemy
// AI, cooldowns and the canvas all stop (which reads as "spells stuck on
// cooldown"). Each step is guarded; the first error of each kind is logged once
// so the real culprit is diagnosable without spamming the console.
const _loopErr = {};
function safeStep(name, fn) {
  try { fn(); }
  catch (e) { if (!_loopErr[name]) { _loopErr[name] = 1; console.error('[gameLoop] ' + name + ' failed:', e); } }
}

let _lastTs = null;
function gameLoop(ts) {
  requestAnimationFrame(gameLoop);
  if (_lastTs == null) _lastTs = ts;
  let dt = (ts - _lastTs) / 1000;
  _lastTs = ts;
  if (dt > 0.1) dt = 0.1;          // clamp after a stall so nothing teleports
  perfFrameSample(ts, dt);         // dev perf HUD sampling — a single boolean check while hidden
  safeStep('pad', () => pollGamepads(ts, dt));   // controller: poll + route (menus work while paused)
  tickAnimClock(ts);               // advance the looping-animation clock (frozen while paused)
  // The teleport fade/beam animation runs on its own even while the world is paused
  // by it (rtPaused → true during transit) — it must keep playing to reach the warp.
  safeStep('portalFx', () => updatePortalFx(dt));
  // The map-portal traversal (swallow → pan → emerge) likewise runs on its own even
  // while it pauses the world — it must keep playing to reach the arrival and hand
  // control back.
  safeStep('warpFx', () => updateWarpFx(dt));
  if (!rtPaused()) {
    safeStep('move', () => updatePlayer(dt));              // 8-dir movement may trigger stairs/town/death…
    // Town is a safe, walkable hub: the hero strolls (updatePlayer above) and time
    // flows (cooldowns + world clock), but combat, auto-cast and hazards stay inert
    // — there are no foes/traps here, and firing autocast would just spam the
    // "save your skills for the dungeon" refusal. updatePlayer regens stamina itself.
    if (!inTown) {
      if (!rtPaused()) safeStep('combat', () => updatePlayerCombat(dt));
      if (!rtPaused()) safeStep('cooldowns', () => tickCooldowns(dt));  // skill/potion cooldowns burn in seconds
      if (!rtPaused()) safeStep('autocast', () => tickAutoCast(dt));    // fire any auto-cast skills that are ready
      if (!rtPaused()) safeStep('world', () => stepWorldClock(dt));
      if (!rtPaused()) safeStep('hazards', () => { updateTraps(dt); updateProjectiles(dt); stepBossTelegraphs(dt); });
    } else {
      safeStep('cooldowns', () => tickCooldowns(dt));
      safeStep('world', () => stepWorldClock(dt));
    }
  } else if (inTown && !clockPaused()) {
    // A service overlay is open on top of the town (rtPaused → the hero is idling in
    // it): movement/combat stay paused, but time still flows — HP/MP AND Stamina
    // regen, skill & potion cooldowns, and status/buff timers all keep ticking, just
    // like standing still down in the dungeon. Stamina regen normally rides in
    // updatePlayer() (skipped here), so refill it or it would freeze while HP/MP recover.
    safeStep('cooldowns', () => tickCooldowns(dt));
    safeStep('world', () => stepWorldClock(dt));
    safeStep('stamRegen', () => regenStamina(dt));
  }
  safeStep('actorRender', () => updateActorRender(dt));
  if (inTown && !clockPaused()) safeStep('townNpcs', () => updateTownNpcs(dt));  // townsfolk stroll while the walkable hub is on screen
  safeStep('hudFlush', () => flushHudDirty());     // damage events mark the HUD dirty; one updateBars() lands here same-frame
  safeStep('stamina', () => renderStaminaBar());   // stamina drains/refills continuously — keep the END bar live
  safeStep('vitalBars', () => updateVitalFills(dt)); // ease HP/MP fills so over-time recovery climbs fluidly
  safeStep('counterRolls', () => updateCounterRolls(dt)); // roll the gold chip + XP bar up to their new values
  safeStep('cdDials', () => updateCooldownDials()); // animate the skill/potion cooldown dials in real time
  safeStep('halo', () => updateHaloVignette());     // the danger halo is a DOM overlay — pulse it every frame
  safeStep('panel', () => flushPanel());            // rebuild the bag at most once per frame, only while it's on-screen
  if (_tutGate) safeStep('tutGate', () => positionTutGate());   // keep the spotlight hole tracking its live target
  // While a side panel is sliding open/closed its column width animates, so the
  // map's on-screen box changes every frame. Re-fit the backing buffer right
  // before the draw (same frame → guaranteed order, no blank flash) so the map
  // stays crisp through the slide instead of stretching. One re-fit + one draw
  // per frame keeps the slide smooth (see refitMapDuringSlide).
  if (performance.now() < _slideRefitUntil) safeStep('slideRefit', () => resizeCanvas());
  safeStep('draw', () => draw());
}
requestAnimationFrame(gameLoop);

// ===================================================================
// TRANSITIONAL window BRIDGE (strangler migration — see docs/DECISIONS.md D6)
// The 253 inline on*= handlers in the markup (static + JS-generated) resolve
// names against the GLOBAL scope. In the original classic <script> every
// top-level function was a window property and inline handlers could read
// top-level bindings. As an ES module nothing is global, so we re-expose:
//  (a) every top-level function as a plain window property (they are never
//      reassigned), and
//  (b) the mutable/state globals the handlers touch as LIVE accessors backed
//      by the module bindings, so reads see the current value and writes
//      (e.g. onclick="selectedSkillId=null") update the real variable.
// This shrinks as handlers move to delegated listeners during extraction.
// ===================================================================

/* ═══ ENDGAME SYSTEMS BLOCK ═══ */
// Pure cores live in src/systems + src/data (unit-tested); this block wires them
// into the live game — town panels, in-run hooks, gameState()/gameGuide(). It is
// assembled from per-system function sets. Its mutable run/UI state (_eg*,
// hallDeeds) is declared ABOVE the guarded boot block — boot-path code writes it,
// so it must be initialized before boot runs (TDZ); see the comment there.
// Current Endless-tier depth (0 in the finite tiers) — the faucet gate for radiant
// affixes, Aether and Pantheon ubers.
function endlessDepthNow() { return (typeof isEndless === 'function' && isEndless()) ? (dungeonLevel - FINITE_DEPTH) : 0; }
// Called from generateMap() when a floor is (re)built: stamp the floor-enter clock
// (malaise ramp) and refresh the per-descent covenant caches.
function egOnFloorEnter() { _egFloorEnterMs = Date.now(); try { egDeriveCovenantRun(); } catch (e) {} }
// Live malaise multiplier for the CURRENT floor age — the "Ashen Tide" tempo
// covenant ramps enemy damage the longer you dawdle. 1 (no-op) when no malaise
// covenant is sworn. Applied to real incoming damage in takePlayerDamage().
function egMalaiseNow() {
  try {
    if (!_egCovMalaiseRate) return 1;
    return malaiseMult(Math.max(0, (Date.now() - (_egFloorEnterMs || Date.now())) / 1000), _egCovMalaiseRate);
  } catch (e) { return 1; }
}
// Safe wrappers so a bug in an endgame block can never make gameState()/gameGuide()
// throw (they are the AI-play contract the smoke test pins).
function egSafe(fn) { try { return fn(); } catch (e) { return null; } }
function egGuide(fn) { try { const a = fn(); return Array.isArray(a) ? a : []; } catch (e) { return []; } }


// ── COVENANTS ──
// ── Dread Covenants: altar UI + run-hook glue ────────────────────────────────────
// Pasted verbatim into src/legacy/game.js module scope. Function declarations only —
// no imports/exports, no module-level state (those globals are pre-declared by the
// orchestrator). The pure cores (activeDread, covenantMultipliers, dreadRewardMult,
// recordDreadClear, malaiseMult, …) and the game's shell helpers are already in scope.

// Recompute the whole live covenant run-state from the hero's active set. Called on
// every toggle and at descent so the spawn/loot/boss hooks read a fresh bundle.
function egDeriveCovenantRun() {
  try {
    const ids = (player && Array.isArray(player.covenantsActive)) ? player.covenantsActive : [];
    _egCovDread = activeDread(ids);
    _egCovMult = covenantMultipliers(ids);
    _egCovReward = dreadRewardMult(_egCovDread);
    _egCovMalaiseRate = combinedMalaiseRate(ids);
  } catch (e) {
    // A corrupt set must never break boot or a descent — fall back to the neutral run.
    _egCovDread = 0;
    _egCovMult = null;
    _egCovReward = null;
    _egCovMalaiseRate = 0;
    if (typeof log === 'function') log('Covenant state failed to derive — running unbound.', 'important');
  }
}

// How many account completion marks the hero holds (drives covenant unlocks).
function egCovMarks() {
  try { return dreadMarksEarned(player.dreadGrid); }
  catch (e) { return 0; }
}

// ── spawn-side hooks (called from spawnEnemies) ──────────────────────────────────
function egCovSpawnHp(base, floorElapsedSec) {
  const hp = _egCovMult ? _egCovMult.enemyHpMult : 1;
  return base * hp * malaiseMult(floorElapsedSec, _egCovMalaiseRate || 0);
}
function egCovSpawnDmg(base, floorElapsedSec) {
  const dmg = _egCovMult ? _egCovMult.enemyDmgMult : 1;
  return base * dmg * malaiseMult(floorElapsedSec, _egCovMalaiseRate || 0);
}
function egCovDensity(count) {
  return Math.round((count || 0) * (_egCovMult ? _egCovMult.densityMult : 1));
}
function egCovEliteAdd() {
  return _egCovMult ? _egCovMult.eliteChanceAdd : 0;
}
function egCovHeal(amount) {
  return Math.round((amount || 0) * (_egCovMult ? _egCovMult.healingMult : 1));
}

// ── loot / boss-point hooks ──────────────────────────────────────────────────────
// Intrinsic (per-covenant sweetener) folds with the Dread-curve reward multiplier.
function egCovLootQtyMult() {
  const intrinsic = _egCovMult ? _egCovMult.dropQtyMult : 1;
  const curve = _egCovReward ? _egCovReward.lootQty : 1;
  return intrinsic * curve;
}
function egCovRarityMult() {
  const intrinsic = _egCovMult ? _egCovMult.rarityMult : 1;
  const curve = _egCovReward ? _egCovReward.rarity : 1;
  return intrinsic * curve;
}
function egCovMaterialMult() {
  return _egCovReward ? _egCovReward.material : 1;
}
function egCovBossPointMult() {
  const intrinsic = _egCovMult ? _egCovMult.bossPointMult : 1;
  const curve = _egCovReward ? _egCovReward.bossPoint : 1;
  return intrinsic * curve;
}
// A boss point is DERIVED (one per distinct boss floor first-cleared), so a ×1.6
// sweetener can't simply multiply it. The fraction is BANKED on the hero instead and
// pays out a whole extra point every time the bank crosses 1 — which is why the
// pool the Weave spends from is bossPointsPool(), not the raw ledger count. Returns
// how many WHOLE points this clear just handed over (0 for an un-sworn hero).
function egCovBankBossPoint() {
  try {
    const mult = egCovBossPointMult();
    if (!(mult > 1)) return 0;
    const before = egCovBankedBossPoints();
    player.dreadBossPoints = Math.max(0, (Number(player.dreadBossPoints) || 0) + (mult - 1));
    return egCovBankedBossPoints() - before;
  } catch (_e) { return 0; }
}
// Whole boss points the covenant bank has paid out so far.
function egCovBankedBossPoints() {
  const v = Math.floor(Number(player && player.dreadBossPoints) || 0);
  return v > 0 ? v : 0;
}
// The boss-point POOL the Ascendant Weave draws on: one per boss floor first-cleared,
// plus whatever the covenant sweetener has banked. (bossesBeaten() stays the raw
// ledger count — it answers "how many boss floors have you beaten", which gates the
// town keepers' arrival ladder and must not move with a covenant.)
function bossPointsPool() {
  return pointsEarned(player.bossFirstKills) + egCovBankedBossPoints();
}

// ── boss-kill hook ───────────────────────────────────────────────────────────────
// Record the clear on the per-class/per-boss Dread grid, then — for any completion
// mark newly earned by this clear whose reward banks collection pity — nudge the
// shared attunement targeting toward a still-missing artifact slot.
function egCovRecordBossClear(cls, bossKey) {
  try {
    const marksNow = egCovMarks();
    if (!_egCovDread || _egCovDread <= 0) return { marks: marksNow };
    const beforeGrid = player.dreadGrid;
    const marksBefore = marksNow;
    const newGrid = recordDreadClear(beforeGrid, cls, bossKey, _egCovDread);
    player.dreadGrid = newGrid;
    const marksAfter = egCovMarks();

    // For each targetBias milestone that flipped from unmet → met on THIS clear, bank
    // one point of collection pity (and lock a target if none is chosen yet).
    for (const m of MARK_MILESTONES) {
      if (!m || !m.reward || m.reward.type !== 'targetBias') continue;
      let wasMet = false, nowMet = false;
      try { wasMet = dreadMarksEarned(beforeGrid, [m]) >= 1; nowMet = dreadMarksEarned(newGrid, [m]) >= 1; }
      catch (e) { wasMet = false; nowMet = false; }
      if (wasMet || !nowMet) continue;
      if (!player.attuneTarget) {
        try {
          const owned = acquiredKeySet(groupStoredArtifacts((stash && stash.items) || [], itemPower));
          const keys = (_COLL_CATALOG || []).map(e => e && e.key).filter(Boolean);
          const tgt = pickMissingTarget(keys, owned, Math.random);
          if (tgt) player.attuneTarget = tgt;
        } catch (e) { /* collection unavailable — still bank the pity below */ }
      }
      player.attunePity = nextPity(player.attunePity, false);
    }

    if (marksAfter > marksBefore) {
      if (typeof sfx === 'function') sfx('levelup');
      log(`<span data-spr=cov_altar></span> <b>Covenant mark earned</b> — a deeper oath opens at the altar.`, 'important');
    }
    saveGameSoon();
    return { marks: marksAfter };
  } catch (e) {
    if (typeof log === 'function') log('Covenant boss-clear record failed.', 'important');
    return { marks: egCovMarks() };
  }
}

// ── altar UI ─────────────────────────────────────────────────────────────────────
function openCovenants() {
  try {
    openTownModal('Covenant Altar', 'cov_altar');
    setTownContent(renderCovenants());
  } catch (e) {
    if (typeof log === 'function') log('The Covenant Altar failed to open.', 'important');
  }
}

// Format a difficulty/reward multiplier for the preview (e.g. 1.25 → "×1.25").
function _egCovFmtMult(n) {
  const v = (typeof n === 'number' && isFinite(n)) ? n : 1;
  return '×' + v.toFixed(2);
}

function renderCovenants() {
  try {
    const ids = (player && Array.isArray(player.covenantsActive)) ? player.covenantsActive : [];
    const marks = egCovMarks();
    const summary = covProjectedSummary(ids);
    const M = summary.multipliers, R = summary.rewards;

    let html = `<div class="town-blurb">Swear <b>afflictions</b> before you descend — each raises the danger AND, by your total <b>Dread</b>, the loot, boss points and crafting materials you haul back. Toggles apply to your <b>next</b> descent; beating a boss under Dread earns account <b>marks</b> that open deeper oaths.</div>`;

    // Live "if you descend now…" preview.
    const eff = {
      loot: (M.dropQtyMult || 1) * (R.lootQty || 1),
      rarity: (M.rarityMult || 1) * (R.rarity || 1),
      boss: (M.bossPointMult || 1) * (R.bossPoint || 1),
      mat: (R.material || 1),
    };
    const dreadColor = summary.dread > 0 ? 'var(--gold)' : 'var(--text)';
    html += `<div class="shop-row no-icon">
      <div class="shop-row-info">
        <div class="shop-row-name">Total Dread <span style="color:${dreadColor}">${summary.dread}</span></div>
        <div class="shop-row-stats">Danger — enemy HP ${_egCovFmtMult(M.enemyHpMult)} · damage ${_egCovFmtMult(M.enemyDmgMult)} · density ${_egCovFmtMult(M.densityMult)} · healing ${_egCovFmtMult(M.healingMult)} · elites +${Math.round((M.eliteChanceAdd || 0) * 100)}%</div>
        <div class="shop-row-stats">Reward — loot ${_egCovFmtMult(eff.loot)} · rarity ${_egCovFmtMult(eff.rarity)} · boss pts ${_egCovFmtMult(eff.boss)} · materials ${_egCovFmtMult(eff.mat)}</div>
        ${malaiseActive(ids) ? `<div class="shop-row-sub" style="color:var(--danger)">A malaise clock ticks — enemies strengthen the longer you linger on a floor. Descend quickly.</div>` : ''}
      </div>
    </div>`;

    // Per-class checklist summary against the canonical boss roster.
    try {
      const roster = (typeof BOSSES !== 'undefined' && Array.isArray(BOSSES)) ? BOSSES.map(b => b.type) : [];
      const cls = player && player.class;
      if (cls && roster.length) {
        const cp = dreadClassProgress(player.dreadGrid, cls, roster);
        html += `<div class="cook-sec">This class</div>`;
        html += `<div class="town-blurb" style="opacity:0.85"><b>${cp.cleared}/${cp.total}</b> bosses beaten under Dread · best Dread reached <b>${cp.bestDread}</b> · <b>${marks}</b> mark${marks === 1 ? '' : 's'} earned account-wide.</div>`;
      }
    } catch (e) { /* checklist is optional flavor */ }

    // The affliction list — unlocked ones toggle; locked ones show their mark gate.
    html += `<div class="cook-sec">Afflictions</div>`;
    html += '<div class="shop-grid">';
    for (const c of sortedCovenants()) {
      if (!c || !c.id) continue;
      const unlocked = covIsUnlocked(c.id, marks);
      const on = ids.includes(c.id);
      const rowCls = `shop-row ${on ? 'picked' : ''} ${unlocked ? '' : 'locked'}`;
      const click = unlocked ? `onclick="covToggle('${c.id}')"` : '';
      const border = on ? 'border-color:var(--gold)' : '';
      // Gold "Dread N" for a swearable oath (matches the Total Dread number);
      // red is reserved for the "Locked" gate so the two never read alike.
      const gate = unlocked
        ? `<span style="color:var(--gold)">Dread ${c.dread}</span>`
        : `<span style="color:var(--danger)">Locked — needs ${c.unlockOrder} mark${c.unlockOrder === 1 ? '' : 's'} (Dread ${c.dread})</span>`;
      html += `<div class="${rowCls}" ${click} style="${border}">
        <span class="loot-icon">${dlIcon(c.sprite || 'cov_altar', 30)}</span>
        <div class="shop-row-info">
          <div class="shop-row-name">${escapeHtml(c.name || c.id)}${on ? ' <span style="color:var(--gold)">✓</span>' : ''}</div>
          <div class="shop-row-sub">${gate}</div>
          <div class="shop-row-stats">${escapeHtml(c.desc || '')}</div>
        </div>
      </div>`;
    }
    html += '</div>';

    // Clear-all — only useful when something is sworn.
    html += `<div class="cook-actions cov-clear"><button class="cook-btn ghost" ${ids.length ? '' : 'disabled'} onclick="covClearAll()">Clear all oaths</button></div>`;
    return html;
  } catch (e) {
    if (typeof log === 'function') log('The altar could not be rendered.', 'important');
    return `<div class="town-blurb">The altar stands silent — try again.</div>`;
  }
}

function covToggle(id) {
  try {
    if (!id) return;
    if (!Array.isArray(player.covenantsActive)) player.covenantsActive = [];
    if (!covIsUnlocked(id, egCovMarks())) { if (typeof sfx === 'function') sfx('error'); return; }
    const i = player.covenantsActive.indexOf(id);
    if (i >= 0) player.covenantsActive.splice(i, 1);
    else player.covenantsActive.push(id);
    player.covenantsActive = sanitizeActiveSet(player.covenantsActive);
    egDeriveCovenantRun();
    if (typeof sfx === 'function') sfx('click');
    saveGameSoon();
    setTownContent(renderCovenants());
  } catch (e) {
    if (typeof log === 'function') log('That oath could not be sworn.', 'important');
  }
}

function covClearAll() {
  try {
    player.covenantsActive = [];
    egDeriveCovenantRun();
    if (typeof sfx === 'function') sfx('click');
    saveGameSoon();
    setTownContent(renderCovenants());
  } catch (e) {
    if (typeof log === 'function') log('Could not clear your oaths.', 'important');
  }
}

// ── AI-play API glue ─────────────────────────────────────────────────────────────
function egCovGameStateBlock() {
  try {
    const ids = (player && Array.isArray(player.covenantsActive)) ? player.covenantsActive : [];
    const marks = egCovMarks();
    if (!ids.length && !marks) return null;
    return {
      dread: _egCovDread || 0,
      active: ids.slice(),
      multipliers: _egCovMult ? {
        enemyHpMult: _egCovMult.enemyHpMult,
        enemyDmgMult: _egCovMult.enemyDmgMult,
        densityMult: _egCovMult.densityMult,
        healingMult: _egCovMult.healingMult,
        eliteChanceAdd: _egCovMult.eliteChanceAdd,
        lootQtyMult: egCovLootQtyMult(),
        rarityMult: egCovRarityMult(),
        materialMult: egCovMaterialMult(),
        bossPointMult: egCovBossPointMult(),
      } : null,
      malaise: { active: malaiseActive(ids), rate: _egCovMalaiseRate || 0 },
      marks,
    };
  } catch (e) { return null; }
}

function egCovGuideTopic() {
  return [
    'Dread Covenants: opt-in curses you swear at the Covenant Altar in town BEFORE a descent. Each is worth some Dread; your total Dread is the number the whole system pivots on.',
    'Every covenant only ever makes enemies tougher, deadlier, denser, more elite, or your healing weaker — never a hard lockout. It is always pressure you can out-gear, out-skill or out-run.',
    'Swearing raises danger AND reward: higher total Dread multiplies loot quantity, drop rarity, boss points and crafting materials along soft-capped curves (generous early, bending to a ceiling).',
    'Where each reward lands: loot quantity thins the per-kill NoDrop, rarity scales every tier chance AND its cap in the drop roll, materials scale the per-kill material odds, and boss points — being one-per-boss-floor and derived from the first-clear ledger — BANK their fraction on the hero instead, paying a whole extra point each time the bank crosses 1 (gameState().menu.bossPointsEarned already includes it).',
    'The healing debuff scales every heal you receive — potions, leech, skill heals, on-kill top-ups — as they are applied, so a healing covenant is felt on the very next sip, not just on paper.',
    'Oaths apply to your NEXT descent. Toggle them on the altar; the live preview shows the exact danger and reward multipliers for the set you have chosen.',
    'Beating a boss while bound by Dread records the clear on a per-class, per-boss checklist at the highest Dread you beat it. Reaching milestones earns account-wide marks.',
    'Marks unlock deeper covenants — each covenant needs a certain mark count to become available. Some marks also bank collection targeting (attunement) pity toward a missing artifact.',
    'Tempo covenants (Haste, Relentless) add a malaise clock: enemies grow steadily stronger the longer you linger on a floor, then plateau. Descend quickly to keep it low.',
  ];
}

// ── WEAVE ──
// ══════════════════════════════════════════════════════════════════════════
// THE ASCENDANT WEAVE — shell integration (board UI + live stat hooks)
// ══════════════════════════════════════════════════════════════════════════
// Top-level function declarations only. Runs inside game.js's module scope, so
// it calls game.js globals + the imported pure-core aliases directly. No import/
// export, no module-level state (those globals are pre-declared elsewhere).
//
// The pure math (systems/ascendantWeave.js) is imported into game.js under:
// weaveSpent, weaveAvail, weaveNodes, weaveInArm, weaveCanAllocate, weaveDoAllocate,
// weaveRefundNode, weaveRefundAll, weaveKeystones, weaveStatContribution,
// weaveDepthRank, sanitizeWeaveBoard, plus the WEAVE table.

// ── live stat contribution (memoized) ────────────────────────────────────────

// The board's whole aggregated contribution: { flat:{key:sum}, mult:{stat:prod} }.
// Memoized on _egWeaveCache keyed by a cheap signature so the hot totalStat /
// totalAttr path only recomputes when the board actually changes. An empty board
// returns a true no-op.
// NOTE: attrs = player.attributes (the ALLOCATED block) — never totalAttr, which
// would recurse (totalAttr calls back into the weave hooks).
function egWeaveContrib() {
  try {
    const board = (typeof player === 'object' && player && player.weaveBoard) || { nodes: {} };
    const nodesObj = (board && board.nodes) || {};
    const attrs = (player && player.attributes) || {};
    // Signature: the lit-node map (a few dozen keys, tiny) plus a fingerprint of the
    // five allocated attributes, since attribute-gated keystones ignite off those —
    // so crossing a gate on level-up recomputes without needing a board edit.
    const asig = `${attrs.might || 0},${attrs.vitality || 0},${attrs.agility || 0},${attrs.spirit || 0},${attrs.luck || 0}`;
    const sig = JSON.stringify(nodesObj) + '#' + asig;
    if (_egWeaveCache && _egWeaveCache.sig === sig) return _egWeaveCache.val;
    const val = weaveStatContribution(board, attrs) || { flat: {}, mult: {} };
    if (!val.flat) val.flat = {};
    if (!val.mult) val.mult = {};
    _egWeaveCache = { sig: sig, val: val };
    return val;
  } catch (e) {
    return { flat: {}, mult: {} };
  }
}

// Flat additive contribution for a stat/attribute key (0 if none). Called from
// the orchestrator's totalStat/totalAttr — kept allocation-free and never throws.
function egWeaveFlat(key) {
  try { return (egWeaveContrib().flat[key]) || 0; } catch (e) { return 0; }
}

// Multiplicative contribution for a stat key (1 if none). Same hot-path contract.
function egWeaveMult(key) {
  try { const m = egWeaveContrib().mult[key]; return (typeof m === 'number' && isFinite(m)) ? m : 1; } catch (e) { return 1; }
}

// Drop the memo — call after ANY board mutation, BEFORE bumpLoadout().
function egWeaveInvalidate() { _egWeaveCache = null; }

// ── small render helpers ─────────────────────────────────────────────────────

// A node payload ({ might:2 } / { ATK:4 }) → a short, art-bearing label. Attribute
// keys use the attribute's own icon+label; every other key is a gear stat code.
function _egWeavePayloadLabel(payload) {
  const parts = [];
  const p = (payload && typeof payload === 'object') ? payload : {};
  for (const k in p) {
    const v = p[k];
    const sign = (typeof v === 'number' && v < 0) ? '' : '+';
    if (typeof ATTRIBUTES === 'object' && ATTRIBUTES && ATTRIBUTES[k]) {
      parts.push(`${sign}${v} ${attrLabelIcon(k)}`);
    } else {
      const lab = (typeof STAT_LABELS === 'object' && STAT_LABELS && STAT_LABELS[k]) || k;
      parts.push(`${sign}${v} ${escapeHtml(String(lab))}`);
    }
  }
  return parts.join(', ');
}

// ── panel ────────────────────────────────────────────────────────────────────

function openWeave() {
  try {
    openTownModal('Ascendant Weave', 'weave_star');
    setTownContent(renderWeave());
  } catch (e) {
    if (typeof log === 'function') log('The Weave could not be opened.');
  }
}

// Build the whole board panel as an HTML string (setTownContent consumes it).
function renderWeave() {
  try {
    const board = (player && player.weaveBoard) || { nodes: {} };
    const attrs = (player && player.attributes) || {};
    const earned = bossPointsPool();
    const avail = weaveAvail(earned, board);
    const lit = weaveNodes(board) || [];
    const activeKs = weaveKeystones(board, attrs) || [];

    let html = '';

    // Intro + point budget. The board is an independent drawer from the boss-point
    // pool — spending here never touches gear-slot points, and vice-versa.
    html += `<div class="town-blurb">The Weave pours boss points into a bounded constellation board — five attribute arms, four rings deep. It draws its own pool from the same points, <b>separate</b> from your gear slots. Light nodes for modest bonuses, then cross a keystone's gate for a build-defining boost — the deepest keystones demand a dedicated, heavily-invested arm. Nodes refund freely, so experiment.</div>`;
    html += `<div class="shop-row"><div class="shop-row-info"><div class="shop-row-name">${dlIcon('weave_star', 18)} <b>${avail}</b> boss point${avail === 1 ? '' : 's'} free to weave</div><div class="shop-row-sub">${earned} earned in total · lit nodes: ${lit.length}</div></div><button class="act-btn" onclick="weaveRespecUI()">RESPEC ALL</button></div>`;

    // Cosmetic Weave Depth prestige bar — grants NO power, label says so.
    const dr = weaveDepthRank((player && player.weaveDepthPoints) || 0);
    const span = dr.span > 0 ? dr.span : 1;
    const pct = Math.max(0, Math.min(100, Math.round((dr.into / span) * 100)));
    html += `<div class="ench-group">${dlIcon('weave_star', 16)} Weave Depth</div>`;
    html += `<div class="shop-row"><div class="shop-row-info"><div class="shop-row-name">Rank ${dr.rank} · ${escapeHtml(dr.title || '')}</div><div class="shop-row-sub">${dr.into} / ${span} depth to next rank · cosmetic, grants no power</div><div style="margin-top:4px;height:10px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--panel);overflow:hidden"><div style="height:100%;width:${pct}%;background:var(--gold)"></div></div></div></div>`;

    // The five constellation arms, each a section header + a responsive grid of its
    // seven nodes. Node grids reuse .shop-grid (fluid auto-fill columns).
    const consts = (WEAVE && Array.isArray(WEAVE.constellations)) ? WEAVE.constellations : [];
    const allNodes = (WEAVE && Array.isArray(WEAVE.nodes)) ? WEAVE.nodes : [];
    for (const c of consts) {
      const inArm = weaveInArm(board, c.id);
      html += `<div class="ench-group">${attrLabelIcon(c.attr)} ${escapeHtml(c.name)} <span style="opacity:0.7;font-weight:normal">— ${inArm} pt${inArm === 1 ? '' : 's'} spent</span></div>`;
      html += '<div class="shop-grid">';
      const armNodes = allNodes.filter((n) => n && n.constellation === c.id);
      for (const n of armNodes) {
        const isLit = lit.includes(n.id);
        const canA = !isLit && weaveCanAllocate(n.id, board, earned);
        const label = _egWeavePayloadLabel(n.payload) || 'Node';
        let cls = 'shop-row has-actions';
        let btn;
        if (isLit) {
          cls += ' upgrade';
          btn = `<button class="act-btn" onclick="weaveRefundUI('${n.id}')">REFUND</button>`;
        } else if (canA) {
          btn = `<button class="act-btn" onclick="weaveAllocateUI('${n.id}')">LIGHT</button>`;
        } else {
          cls += ' cant-afford';
          btn = `<button class="act-btn" disabled>LOCKED</button>`;
        }
        html += `<div class="${cls}"><div class="shop-row-info"><div class="shop-row-name">${label}</div><div class="shop-row-sub">Ring ${n.band}${isLit ? ' · lit' : (canA ? ' · ready' : ' · locked')}</div></div>${btn}</div>`;
      }
      html += '</div>';
    }

    // Keystones — build-definers, dormant until their arm is entered AND their gate
    // (attribute total, points in the arm, and/or total board spend) is crossed.
    const keystones = (WEAVE && Array.isArray(WEAVE.keystones)) ? WEAVE.keystones : [];
    if (keystones.length) {
      html += `<div class="ench-group">${dlIcon('weave_star', 16)} Keystones</div>`;
      html += '<div class="shop-grid">';
      for (const ks of keystones) {
        const active = activeKs.includes(ks.id);
        const arm = consts.find((x) => x && x.id === ks.constellation);
        const armName = arm ? arm.name : ks.constellation;
        const gate = ks.gate || {};
        // A gate can carry several conditions — list every one so the requirement reads
        // honestly (e.g. "Enter The Ferocity · reach 150 Might · 24 pts on the board").
        const reqs = [`Enter ${escapeHtml(armName)}`];
        if (gate.attr != null && gate.total != null) reqs.push(`reach ${gate.total} ${attrLabelIcon(gate.attr)}`);
        if (gate.n != null) reqs.push(`spend ${gate.n} pts here`);
        if (gate.boardPts != null) reqs.push(`${gate.boardPts} pts on the board`);
        const gateStr = reqs.join(' · ');
        const cls = active ? 'shop-row upgrade' : 'shop-row cant-afford';
        const nameStyle = active ? 'color:var(--gold)' : '';
        html += `<div class="${cls}"><div class="shop-row-info"><div class="shop-row-name" style="${nameStyle}">${escapeHtml(ks.name)}${active ? ' ✦' : ''}</div><div class="shop-row-sub">${escapeHtml(ks.desc || '')}</div><div class="shop-row-stats">${gateStr} · ${active ? '<b style="color:var(--gold)">ACTIVE</b>' : 'dormant'}</div></div></div>`;
      }
      html += '</div>';
    }

    return html;
  } catch (e) {
    if (typeof log === 'function') log('The Weave could not be drawn.');
    return `<div class="town-blurb">The Weave could not be drawn.</div>`;
  }
}

// ── mutation follow-up (shared) ──────────────────────────────────────────────
// Invalidate the memo, refresh derived stats, clamp resources, save, re-render.
function _egWeaveApply() {
  egWeaveInvalidate();
  if (typeof bumpLoadout === 'function') bumpLoadout();
  if (typeof recomputeMaxStats === 'function') recomputeMaxStats();
  if (player) {
    if (player.hp > player.maxHp) player.hp = player.maxHp;
    if (player.mp > player.maxMp) player.mp = player.maxMp;
  }
  if (typeof saveGameSoon === 'function') saveGameSoon();
  setTownContent(renderWeave());
}

// ── inline-onclick handlers (defensive) ──────────────────────────────────────

function weaveAllocateUI(nodeId) {
  try {
    const board = (player && player.weaveBoard) || { nodes: {} };
    const earned = bossPointsPool();
    if (!weaveCanAllocate(nodeId, board, earned)) { sfx('error'); return; }
    player.weaveBoard = weaveDoAllocate(board, nodeId);
    sfx('levelup');
    _egWeaveApply();
  } catch (e) {
    log('Weave: could not light that node.');
  }
}

function weaveRefundUI(nodeId) {
  try {
    const board = (player && player.weaveBoard) || { nodes: {} };
    player.weaveBoard = weaveRefundNode(board, nodeId);
    sfx('click');
    _egWeaveApply();
  } catch (e) {
    log('Weave: could not refund that node.');
  }
}

function weaveRespecUI() {
  try {
    player.weaveBoard = weaveRefundAll();
    sfx('click');
    log('The Weave unravels — every node refunded.');
    _egWeaveApply();
  } catch (e) {
    log('Weave: could not respec the board.');
  }
}

// ── AI-play API blocks ───────────────────────────────────────────────────────

function egWeaveGameStateBlock() {
  try {
    const board = (player && player.weaveBoard) || { nodes: {} };
    const attrs = (player && player.attributes) || {};
    return {
      available: weaveAvail(bossPointsPool(), board),
      spent: weaveSpent(board),
      nodes: weaveNodes(board) || [],
      keystones: weaveKeystones(board, attrs) || [],
      depth: weaveDepthRank((player && player.weaveDepthPoints) || 0),
    };
  } catch (e) {
    return { available: 0, spent: 0, nodes: [], keystones: [], depth: weaveDepthRank(0) };
  }
}

function egWeaveGuideTopic() {
  return [
    'THE ASCENDANT WEAVE — an endgame choice board fed by the SAME boss points as your gear slots, but as an INDEPENDENT drawer: points lit here never reduce what your gear slots can spend, and vice-versa.',
    'Points free to the board = boss points earned minus points already lit on the board. Every node costs 1 and refunds for free (Respec all), so you can freely re-plan a build.',
    'Five arms, one per attribute — Ferocity (Might), Aegis (Vitality), Zephyr (Agility), Oracle (Spirit), Fortune (Luck) — each FOUR rings deep, seven nodes per arm. Light an arm\'s entry node first; band-2 branches need the entry, band-3 tips need either branch, and each band-4 apex needs its own side\'s tip.',
    'KEYSTONES are build-definers that stay dormant until you ENTER their arm (light at least one node there) AND cross their gate. A gate can combine a hero attribute TOTAL, a number of points spent in that arm, and a total number of points lit across the whole board — ALL parts must hold. They ladder up: a cheap keystone lights early, an apex keystone demands a deep, dedicated, board-wide investment. Each folds a multiplier or flat bonus into one stat.',
    'WEAVE DEPTH is a purely cosmetic prestige rank — an ever-receding badge that grants NO power, only a title.',
    'An untouched board is a true no-op: with no nodes lit, no keystone can ignite, so the hero is byte-identical to having no Weave at all.',
  ];
}

// ── MIRRORFORGE ──
// ── THE MIRRORFORGE — legacy-shell integration (pasted verbatim into game.js) ──
// Bench UI + real-item adapter over the pure Mirrorforge core (systems/mirrorforge.js)
// and the shared collection-targeting pity (systems/collectionTargeting.js). Real
// gear stores rolls in item.stats{}/item.attrs{}; the core operates on a minimal
// {tier,rank,ilvl,affixes[]} contract, so egMfToContract/egMfFromContract map both
// ways. Every onclick body is try/catch-guarded so a stray error logs instead of
// breaking the frame; optional helpers are typeof-guarded.

// ── ADAPTER: real item → minimal Mirrorforge contract ──
function egMfToContract(item) {
  const it = item || {};
  const ilvl = it.ilvl || 1;
  const mult = (typeof tierMult === 'function') ? tierMult(it.tier) : 1;
  const locked = (typeof lockedStats === 'function') ? (lockedStats(it) || []) : [];
  const affixes = [];
  const stats = it.stats || {};
  for (const key in stats) {
    if (locked.indexOf(key) >= 0) continue;                 // headline/native/curse rolls aren't sculptable
    const r = (typeof affixStatRange === 'function') ? (affixStatRange(key, ilvl, mult) || {}) : {};
    affixes.push({ key, val: stats[key], min: r.min || 0, max: (r.max != null ? r.max : (r.min || 0)), kind: 'stat' });
  }
  const attrs = it.attrs || {};
  for (const key in attrs) {
    const r = (typeof affixAttrRange === 'function') ? (affixAttrRange(ilvl, mult) || {}) : {};
    affixes.push({ key, val: attrs[key], min: r.min || 0, max: (r.max != null ? r.max : (r.min || 0)), kind: 'attr' });
  }
  return {
    tier: it.tier,
    rank: Math.max(0, Object.keys(TIERS).indexOf(it.tier)),
    ilvl,
    affixes,
    mirrored: !!it.mirrored,
    sealed: !!it.sealed,
    radiant: !!it.radiant,
    _fpSpent: it._fpSpent || 0,
    _src: it,
  };
}

// ── ADAPTER: sculpted contract → real item (shallow clone, fold affixes back) ──
function egMfFromContract(item, contract) {
  const src = item || {};
  const c = contract || {};
  const out = Object.assign({}, src);
  out.stats = Object.assign({}, src.stats || {});
  out.attrs = Object.assign({}, src.attrs || {});
  const affs = Array.isArray(c.affixes) ? c.affixes : [];
  for (const a of affs) {
    if (!a || a.key == null) continue;
    // A curse penalty (negative val, key 'CURSE') brands the item cursed. Redirect it
    // onto a REAL stat whose negative is felt in combat — writing a nonexistent 'CURSE'
    // stat would be an invisible drawback (see cursePenaltyStats). Prefer a felt stat
    // the item already has, excluding the boosted stat (contract.curseStat).
    if (a.key === 'CURSE' || (a.curse && a.val < 0)) {
      const cpool = (typeof itemStatPool === 'function') ? (itemStatPool(out) || []) : [];
      const cpos = Object.keys(out.stats).filter(k => typeof out.stats[k] === 'number' && out.stats[k] > 0);
      const pen = pick(cursePenaltyStats(cpool, c.curseStat, cpos));
      if (pen) { out.stats[pen] = (out.stats[pen] || 0) + a.val; out.curseStat = pen; }
      out.cursed = true;
      continue;
    }
    // A corrupt addAffix new key (e.g. 'MIRRORFORGE') writes to stats; attrs to attrs; everything else to stats.
    if (a.kind === 'attr') out.attrs[a.key] = a.val;
    else out.stats[a.key] = a.val;
  }
  out.mirrored = !!c.mirrored;
  out.sealed = !!c.sealed;
  out.radiant = !!c.radiant;
  out._fpSpent = c._fpSpent || 0;
  if (c.signature) out.signature = c.signature;
  if (c._corrupt) out._corrupt = c._corrupt;
  if (c.cursed) out.cursed = true;
  return out;
}

// ── WALLET snapshot the core's canApply/spend understand (+ Aether from the hero) ──
function egMfWallet() {
  const m = (typeof heroMaterials === 'function') ? (heroMaterials() || {}) : {};
  return { scrap: m.scrap || 0, glimmer: m.glimmer || 0, core: m.core || 0, chaos: m.chaos || 0, aether: player.aether || 0 };
}

// ── Spend an action's bill: staples via spendCost, Aether off the hero directly ──
function egMfSpend(action) {
  const c = mfMatCost(action) || {};
  const pay = {};
  if (c.gold) pay.gold = c.gold;
  if (c.scrap) pay.scrap = c.scrap;
  if (c.glimmer) pay.glimmer = c.glimmer;
  if (c.core) pay.core = c.core;
  if (c.chaos) pay.chaos = c.chaos;
  spendCost(pay);
  if (c.aether) player.aether = Math.max(0, (player.aether || 0) - c.aether);
}

// ── Open the bench ──
function openMirrorforge() {
  try {
    openTownModal('Mirrorforge', 'mf_anvil');
    _egMfSel = -1;
    setTownContent(renderMirrorforge());
    if (typeof sfx === 'function') sfx('click');
  } catch (e) { if (typeof log === 'function') log('Mirrorforge failed to open'); }
}

// ── Render the whole bench (returns an HTML string for setTownContent) ──
function renderMirrorforge() {
  try {
    const endlessDepth = (typeof isEndless === 'function' && isEndless()) ? (dungeonLevel - FINITE_DEPTH) : 0;
    const REASONS = {
      unknown: 'Not available here', mirrored: 'Already perfected — locked',
      sealed: 'Sealed by a Corrupt', fp: 'Not enough Forging Potential',
      mats: 'Not enough materials', noitem: 'No item selected',
    };
    const reasonLine = (r) => `<div style="color:var(--danger);font-size:1.2rem;margin:2px 0">${REASONS[r] || 'Unavailable'}</div>`;
    const aetherTag = (n) => n ? ` ${n}<span data-spr=mat_aether></span>` : '';

    // ── LEFT: gear picker (only wearable pieces) ──
    let left = `<div class="section-header"><span data-spr=chest></span> Your Gear</div>`;
    const picks = [];
    for (let i = 0; i < inventory.length; i++) {
      const it = inventory[i];
      if (it && it.slot) picks.push({ i, it });
    }
    if (!picks.length) {
      left += `<div class="town-blurb" style="opacity:0.75">No wearable gear in your bag to sculpt. Bring back a piece with a slot.</div>`;
    } else {
      for (const p of picks) {
        const it = p.it, sel = (p.i === _egMfSel);
        const col = rarityHex(it.tier, (TIERS[it.tier] && TIERS[it.tier].color) || 'var(--text)');
        const slotLabel = (typeof SLOTS === 'object' && SLOTS && it.slot && SLOTS[it.slot]) ? SLOTS[it.slot].label : (it.slot || '');
        const tags = [];
        if (it.mirrored) tags.push('Perfected');
        if (it.sealed) tags.push('Sealed');
        if (it.radiant) tags.push('Radiant');
        if (it.cursed) tags.push('Cursed');
        const tagStr = tags.length ? ` · ${escapeHtml(tags.join(' · '))}` : '';
        left += `<div class="shop-row has-actions${sel ? ' picked' : ''}">
          <span class="loot-icon">${dlIcon(it.icon || 'mf_gem', 30)}</span>
          <div class="shop-row-info">
            <div class="shop-row-name" style="color:${col}">${escapeHtml(it.name || 'Item')}</div>
            <div class="shop-row-sub">${escapeHtml(slotLabel)} · ilvl ${it.ilvl || 1}${tagStr}</div>
          </div>
          <button class="act-btn" onclick="mfPick(${p.i})">${sel ? 'WORKING' : 'PICK'}</button>
          <button class="act-btn sm" onclick="mfShatter(${p.i})">Shatter</button>
        </div>`;
      }
    }

    // ── RIGHT: bench + status ──
    let right = `<div class="section-header"><span data-spr=mf_anvil></span> Mirrorforge Bench</div>`;

    // Attunement / target / pity status (always shown).
    const attunement = player.attunement || 0;
    const aether = player.aether || 0;
    let targetName = 'none';
    if (player.attuneTarget) {
      const e = _COLL_CATALOG.find(x => x.key === player.attuneTarget);
      targetName = e ? e.name : player.attuneTarget;
    }
    const pityLeft = pityRemaining(player.attunePity || 0);
    const spendNeed = (MIRRORFORGE.attunement && MIRRORFORGE.attunement.spendCost) || 50;
    const canAim = attunement >= spendNeed && !player.attuneTarget;
    right += `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 140px),1fr));gap:var(--space-2);align-items:center;margin-bottom:var(--space-2)">
      <div style="font-size:1.2rem"><span data-spr=mat_glimmer></span> Attunement <b style="color:var(--gold)">${attunement}</b></div>
      <div style="font-size:1.2rem"><span data-spr=mat_aether></span> Aether <b style="color:var(--gold)">${aether}</b></div>
      <div style="font-size:1.2rem">Target <b>${escapeHtml(targetName)}</b></div>
      <div style="font-size:1.2rem">Pity <b>${pityLeft}</b> to guaranteed</div>
      <button class="act-btn sm" ${canAim ? '' : 'disabled'} onclick="egMfSpendAttunement()">Aim farm (${spendNeed})</button>
    </div>`;

    const item = (_egMfSel >= 0 && _egMfSel < inventory.length) ? inventory[_egMfSel] : null;
    if (!item || !item.slot) {
      right += `<div class="town-blurb" style="opacity:0.75">Pick a piece on the left to sculpt its Forging Potential.</div>`;
    } else {
      const c = egMfToContract(item);
      const wallet = egMfWallet();
      const budget = fpBudget(c), rem = fpRemaining(c), spent = mfSpent(c);
      const pct = budget > 0 ? Math.max(0, Math.min(100, Math.round(rem / budget * 100))) : 0;
      const col = rarityHex(item.tier, (TIERS[item.tier] && TIERS[item.tier].color) || 'var(--text)');
      const fixed = !!item.fixed;
      const aetherOK = (player.aether > 0) && aetherUnlocked(endlessDepth);

      right += `<div class="shop-row">
        <span class="loot-icon">${dlIcon(item.icon || 'mf_gem', 30)}</span>
        <div class="shop-row-info">
          <div class="shop-row-name" style="color:${col}">${escapeHtml(item.name || 'Item')}</div>
          <div class="shop-row-sub">ilvl ${item.ilvl || 1} · rank ${c.rank}${item.radiant ? ' · Radiant' : ''}${item.sealed ? ' · Sealed' : ''}${item.mirrored ? ' · Perfected' : ''}</div>
        </div></div>`;

      // FP meter.
      right += `<div style="margin:var(--space-2) 0">
        <div style="font-size:1.2rem;margin-bottom:4px">Forging Potential <b style="color:var(--gold)">${rem}</b> / ${budget} FP left <span style="opacity:0.7">(${spent} spent)</span></div>
        <div style="height:10px;border:1px solid var(--border);border-radius:var(--radius-1);background:var(--panel);overflow:hidden"><div style="height:100%;width:${pct}%;background:var(--gold)"></div></div>
      </div>`;

      // Affix readout.
      if (c.affixes.length) {
        let al = '';
        for (const a of c.affixes) {
          al += `<div style="font-size:1.2rem;padding:1px 0"><b>${escapeHtml(a.key)}</b> ${a.val} <span style="opacity:0.6">(${a.min}–${a.max})</span></div>`;
        }
        right += `<div style="margin-bottom:var(--space-2)">${al}</div>`;
      } else {
        right += `<div class="town-blurb" style="opacity:0.7">This piece has no sculptable bonus affixes.</div>`;
      }

      if (fixed) right += `<div style="font-size:1.2rem;opacity:0.75;margin-bottom:var(--space-2)">Fixed item — only Exalt, Divine, Mirror and Shatter are available.</div>`;

      // Build the affix-key buttons (Attune) and affix-index buttons (Exalt/Divine).
      const keyBtns = (action, ok) => {
        if (!c.affixes.length) return `<span style="opacity:0.6;font-size:1.2rem">no affixes</span>`;
        return c.affixes.map(a => {
          const ak = String(a.key).replace(/[^\w]/g, '');
          return `<button class="act-btn sm" ${ok ? '' : 'disabled'} onclick="mfDo('${action}','${ak}')">${escapeHtml(a.key)}</button>`;
        }).join('');
      };
      const idxBtns = (action, ok) => {
        if (!c.affixes.length) return `<span style="opacity:0.6;font-size:1.2rem">no affixes</span>`;
        return c.affixes.map((a, ai) =>
          `<button class="act-btn sm" ${ok ? '' : 'disabled'} onclick="mfDo('${action}',${ai})">${escapeHtml(a.key)}</button>`
        ).join('');
      };
      const actionBlock = (title, desc, action, body) => {
        const cost = mfMatCost(action);
        const g = mfCanApply(action, c, rem, wallet);
        return `<div style="border:1px solid var(--border);border-radius:var(--radius-2);padding:var(--space-2);margin-bottom:var(--space-2)">
          <div style="font-size:1.3rem"><b>${title}</b> <span style="font-size:1.2rem;opacity:0.85">${costLabel(cost)}${aetherTag(cost.aether)} · ${fpCost(action, c)} FP</span></div>
          <div style="font-size:1.2rem;opacity:0.8;margin:2px 0">${desc}</div>
          ${g.ok ? '' : reasonLine(g.reason)}
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px">${body(g.ok)}</div>
        </div>`;
      };

      // ATTUNE — reforge affixes, chosen key rolls strong (off for fixed items).
      if (!fixed) {
        right += actionBlock('Attune', 'Reforge the bonus affixes; the stat you pick is guaranteed to roll in the top half of its band.', 'attune', (ok) => keyBtns('attune', ok));
      }
      // EXALT — deterministic push toward ceiling.
      right += actionBlock('Exalt', 'Push one affix halfway to its ceiling. No RNG — repeat to converge on max.', 'exalt', (ok) => idxBtns('exalt', ok));
      // DIVINE — reroll one value, optional Aether top-decile snap.
      {
        const cost = mfMatCost('divine');
        const g = mfCanApply('divine', c, rem, wallet);
        right += `<div style="border:1px solid var(--border);border-radius:var(--radius-2);padding:var(--space-2);margin-bottom:var(--space-2)">
          <div style="font-size:1.3rem"><b>Divine</b> <span style="font-size:1.2rem;opacity:0.85">${costLabel(cost)}${aetherTag(cost.aether)} · ${fpCost('divine', c)} FP</span></div>
          <div style="font-size:1.2rem;opacity:0.8;margin:2px 0">Reroll one affix's value in-band${_egMfDivineAether ? ' — snapped into its top decile (Aether)' : ''}.</div>
          <div style="margin:4px 0"><button class="act-btn sm${_egMfDivineAether && aetherOK ? ' on' : ''}" ${aetherOK ? '' : 'disabled'} onclick="mfToggleAether()"><span data-spr=mat_aether></span> Use Aether: ${(_egMfDivineAether && aetherOK) ? 'ON' : 'OFF'}</button></div>
          ${g.ok ? '' : reasonLine(g.reason)}
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px">${idxBtns('divine', g.ok)}</div>
        </div>`;
      }
      // CORRUPT — irreversible gamble that seals (off for fixed items).
      if (!fixed) {
        const cost = mfMatCost('corrupt');
        const g = mfCanApply('corrupt', c, rem, wallet);
        right += `<div style="border:1px solid var(--danger);border-radius:var(--radius-2);padding:var(--space-2);margin-bottom:var(--space-2)">
          <div style="font-size:1.3rem"><b style="color:var(--danger)">Corrupt</b> <span style="font-size:1.2rem;opacity:0.85">${costLabel(cost)}${aetherTag(cost.aether)} · ${fpCost('corrupt', c)} FP</span></div>
          <div style="font-size:1.2rem;opacity:0.8;margin:2px 0">Irreversible — SEALS the item. May bless it, brand a signature, make it radiant, or lay a heavy curse.</div>
          ${g.ok ? '' : reasonLine(g.reason)}
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px"><button class="act-btn sm" ${g.ok ? '' : 'disabled'} onclick="if(confirm('Corrupt is irreversible and seals this item. Proceed?'))mfDo('corrupt')">Corrupt this item</button></div>
        </div>`;
      }
      // MIRROR — lock a flawless copy (Aether-gated).
      {
        const cost = mfMatCost('mirror');
        const g = mfCanApply('mirror', c, rem, wallet);
        right += `<div style="border:1px solid var(--border);border-radius:var(--radius-2);padding:var(--space-2);margin-bottom:var(--space-2)">
          <div style="font-size:1.3rem"><b style="color:var(--gold)">Mirror</b> <span style="font-size:1.2rem;opacity:0.85">${costLabel(cost)}${aetherTag(cost.aether)}</span></div>
          <div style="font-size:1.2rem;opacity:0.8;margin:2px 0">Lock a flawless copy into your Perfected collection (Owned → Perfected).</div>
          ${g.ok ? '' : reasonLine(g.reason)}
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px"><button class="act-btn sm" ${g.ok ? '' : 'disabled'} onclick="mfDo('mirror')">Mirror this item</button></div>
        </div>`;
      }
    }

    return `<div class="town-blurb">The Mirrorforge sculpts your gear against a finite <b>Forging Potential</b> budget, then <b>Mirrors</b> a flawless copy into a second collection axis. Every spend is permanent, so plan the layers. <b>Shatter</b> a worked piece for <b>Attunement</b> to aim a farm at a still-missing artifact.</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 320px),1fr));gap:var(--space-3);align-items:start">
      <div style="min-width:0">${left}</div>
      <div style="min-width:0">${right}</div>
    </div>`;
  } catch (e) {
    return `<div class="town-blurb" style="color:var(--danger)">The Mirrorforge could not render right now.</div>`;
  }
}

// ── Pick an item to work on ──
function mfPick(i) {
  try {
    _egMfSel = i;
    setTownContent(renderMirrorforge());
    if (typeof sfx === 'function') sfx('click');
  } catch (e) { if (typeof log === 'function') log('Mirrorforge action failed'); }
}

// ── Perform an action on the selected item ──
function mfDo(action, arg) {
  try {
    const item = inventory[_egMfSel];
    if (!item) { log('No item selected.'); return; }
    const gate = mfCanApply(action, egMfToContract(item), fpRemaining(egMfToContract(item)), egMfWallet());
    if (!gate || !gate.ok) { log('Cannot ' + action + ' this item right now.'); return; }
    egMfSpend(action);
    const c = egMfToContract(item);
    let res;
    if (action === 'attune') res = applyAttune(c, arg, Math.random);
    else if (action === 'exalt') res = applyExalt(c, arg);
    else if (action === 'divine') res = applyDivine(c, arg, _egMfDivineAether, Math.random);
    else if (action === 'corrupt') res = applyCorrupt(c, Math.random);
    else if (action === 'mirror') { res = applyMirror(c); if (typeof egHallBumpMirror === 'function') egHallBumpMirror(); }
    else res = c;
    inventory[_egMfSel] = egMfFromContract(item, res);
    if (typeof bumpLoadout === 'function') bumpLoadout();
    if (typeof recomputeMaxStats === 'function') recomputeMaxStats();
    saveGameSoon();
    if (typeof sfx === 'function') sfx(action === 'corrupt' ? 'loot' : 'levelup');
    log('<span data-spr=mf_anvil></span> Mirrorforge: ' + action + ' applied.', 'loot');
    setTownContent(renderMirrorforge());
  } catch (e) { log('Mirrorforge action failed'); }
}

// ── Toggle the Divine "use Aether" top-decile snap ──
function mfToggleAether() {
  try {
    _egMfDivineAether = !_egMfDivineAether;
    setTownContent(renderMirrorforge());
  } catch (e) { if (typeof log === 'function') log('Mirrorforge action failed'); }
}

// ── Shatter a bag piece into Attunement (the pity currency) ──
function mfShatter(i) {
  try {
    const it = inventory[i];
    if (!it) return;
    const gain = shatterToAttunement(egMfToContract(it));
    player.attunement = (player.attunement || 0) + gain;
    inventory.splice(i, 1);
    if (_egMfSel >= i) _egMfSel = -1;
    saveGameSoon();
    if (typeof sfx === 'function') sfx('loot');
    setTownContent(renderMirrorforge());
    log('<span data-spr=mf_anvil></span> Shattered for +' + gain + ' Attunement.', 'important');
  } catch (e) { }
}

// ── Spend Attunement to aim the farm at a still-missing artifact ──
function egMfSpendAttunement() {
  try {
    const need = (MIRRORFORGE.attunement && MIRRORFORGE.attunement.spendCost) || 50;
    if ((player.attunement || 0) < need) { log('Not enough Attunement (need ' + need + ').'); return; }
    if (player.attuneTarget) { log('A target is already set.'); return; }
    const owned = acquiredKeySet(groupStoredArtifacts((stash && stash.items) || [], itemPower));
    const keys = _COLL_CATALOG.map(e => e.key);
    const target = pickMissingTarget(keys, owned, Math.random);
    if (!target) { log('Your collection is already complete — nothing to aim for.'); return; }
    player.attuneTarget = target;
    player.attunement = (player.attunement || 0) - need;
    saveGameSoon();
    if (typeof sfx === 'function') sfx('levelup');
    const e = _COLL_CATALOG.find(x => x.key === target);
    log('<span data-spr=mf_anvil></span> Farm aimed at <b>' + escapeHtml(e ? e.name : target) + '</b>.', 'important');
    setTownContent(renderMirrorforge());
  } catch (err) { log('Mirrorforge action failed'); }
}

// ── Drop-time hook: flag an affix radiant in deep Endless ──
function egMfRadiantOnAffix(item, endlessDepth) {
  try {
    if (rollRadiant(Math.random, endlessDepth)) { if (item) item.radiant = true; return true; }
    return false;
  } catch (e) { return false; }
}

// ── Drop-time hook: roll an Aether drop (deep-Endless-gated) ──
function egMfAetherDrop(endlessDepth) {
  try { return (aetherUnlocked(endlessDepth) && Math.random() < 0.10) ? 1 : 0; }
  catch (e) { return 0; }
}

// ── Count of Perfected (mirrored) copies in the stash ──
function egMfPerfectedCount() {
  try {
    const items = (stash && stash.items) || [];
    let n = 0;
    for (const it of items) if (it && it.mirrored) n++;
    return n;
  } catch (e) { return 0; }
}

// ── gameState() live block ──
function egMfGameStateBlock() {
  return {
    aether: player.aether || 0,
    attunement: player.attunement || 0,
    target: player.attuneTarget || null,
    perfected: egMfPerfectedCount(),
  };
}

// ── gameGuide() reference lines ──
function egMfGuideTopic() {
  return [
    'Mirrorforge: a deep-crafting bench that turns your late-game material glut into a bounded, planned climb toward perfect gear.',
    'Forging Potential (FP): each item has a finite budget = 100 + 20*rank + 2*ilvl. Every sculpt spends FP, so perfection must be planned, not brute-forced.',
    'Attune: reforge the bonus affixes; the stat you choose is guaranteed to roll in the top half of its band. The cheap, repeatable aim.',
    'Exalt: deterministically shove one affix halfway to its ceiling each cast (no RNG) — converges on max with diminishing returns.',
    'Divine: reroll one affix value in-band; toggle Use Aether to snap it into the top decile for a near-perfect roll.',
    'Corrupt: a one-shot, irreversible gamble that SEALS the item — may add an affix, make it radiant, brand a signature, or lay a heavy curse.',
    'Mirror: lock a flawless copy into the Perfected collection axis (Owned -> Perfected). Costs heavy materials plus the deep material Aether.',
    'Radiant affixes are greater rolls that appear on drops deep in Endless (chance climbs with depth) and from a lucky Corrupt.',
    'Aether: a deep-Endless material that only starts dropping at Endless depth 90; it fuels Mirror and the Aether Divine.',
    'Shatter: retire a worked item for Attunement, the pity currency. Spend Attunement to aim your farm at a still-missing artifact; a dry streak bends toward it.',
  ];
}

// ── PANTHEON ──
// ─────────────────────────────────────────────────────────────────────────────
// PANTHEON OF THE DEEP — shell integration (pasted verbatim into src/legacy/game.js)
//
// Top-level function declarations only. Runs INSIDE game.js scope, so it calls
// game.js globals (player, inventory, enemies, log, sfx, dlIcon, …) and the already
// imported pure-core pinnacle aliases (pinnacleBossById, baseBosses, uberFor,
// pinnacleSummonCost, pinnacleCanSummon, previewLootPool, rollPinnacleDrop,
// nextBossPity, firstClearReward, uberUnlocked, PANTHEON, PANTHEON_SHARDS,
// pinnacleUniqueById, pinnacleInitFight, pinnacleStepFight, pinnacleCurrentPhase,
// pinnaclePendingTelegraphs) directly.
//
// Every handler body is wrapped in try/catch and every optional internal API is
// typeof-guarded, so a missing shell helper no-ops rather than breaking boot. The
// summit fight is REAL and playable: the summoned god is force-spawned into a live
// dungeon floor with a real, telegraphed boss moveset cloned from an existing
// guardian, and the phase/enrage/add-wave overlay rides on top of it.
// ─────────────────────────────────────────────────────────────────────────────

// The hero's live purse in the exact shape pinnacleCanSummon expects.
function egPinnacleWallet() {
  try {
    var mats = (typeof heroMaterials === 'function') ? (heroMaterials() || {}) : {};
    return {
      gold: (typeof spendableGold === 'function') ? (spendableGold() || 0) : ((player && player.gold) || 0),
      chaos: mats.chaos || 0,
      scrap: mats.scrap || 0,
      glimmer: mats.glimmer || 0,
      core: mats.core || 0,
      shards: (player && player.pinnacleShards) || {},
    };
  } catch (e) {
    return { gold: 0, chaos: 0, scrap: 0, glimmer: 0, core: 0, shards: {} };
  }
}

// The Endless depth the hero has reached (0 while inside the finite ladder).
function egPinnacleEndlessDepth() {
  try {
    var endless = (typeof isEndless === 'function') ? isEndless() : false;
    var floor = (typeof FINITE_DEPTH === 'number') ? FINITE_DEPTH : 75;
    var dl = (typeof dungeonLevel === 'number') ? dungeonLevel : 0;
    return endless ? Math.max(0, dl - floor) : 0;
  } catch (e) {
    return 0;
  }
}

// A short, readable label for a shard currency id ('tideheartShard' -> 'Tideheart').
function egShardLabel(type) {
  try {
    if (!type) return 'Shard';
    var s = String(type).replace(/Shard$/, '');
    return s.charAt(0).toUpperCase() + s.slice(1);
  } catch (e) {
    return 'Shard';
  }
}
// The per-lineage Effigy-shard sprite for a shard currency id; each god-lineage has
// its own coloured shard art ('tideheartShard' -> 'pin_shard_tide'). Falls back to
// the generic 'pin_shard' for an unknown type.
const EG_SHARD_ICON = {
  tideheartShard: 'pin_shard_tide', voidcinderShard: 'pin_shard_void',
  emberscaleShard: 'pin_shard_ember', thornseedShard: 'pin_shard_thorn',
  stormglassShard: 'pin_shard_storm', hollowechoShard: 'pin_shard_hollow',
};
function egShardIcon(type) { return EG_SHARD_ICON[type] || 'pin_shard'; }

// One line summarising an Effigy recipe ({shards:{type,count}, gold, chaos?}).
function egPinnacleRecipeLine(recipe) {
  try {
    if (!recipe) return 'no recipe';
    var parts = [];
    if (recipe.shards && recipe.shards.type) {
      parts.push(dlIcon(egShardIcon(recipe.shards.type), 14) + (recipe.shards.count || 0) + ' ' + egShardLabel(recipe.shards.type));
    }
    if (recipe.gold) {
      var g = (typeof fmtGold === 'function') ? fmtGold(recipe.gold) : recipe.gold;
      parts.push(dlIcon('ic_money', 14) + g);
    }
    if (recipe.chaos) parts.push(dlIcon('mat_chaos', 14) + recipe.chaos + ' chaos');
    return parts.join(' &nbsp;·&nbsp; ');
  } catch (e) {
    return '';
  }
}

// The Mythic pool of a god as a readable name list.
function egPinnaclePoolLine(bossId) {
  try {
    var pv = (typeof previewLootPool === 'function') ? (previewLootPool(bossId) || {}) : {};
    var pool = pv.pool || [];
    var names = pool.map(function (mid) {
      var d = (typeof pinnacleUniqueById === 'function') ? pinnacleUniqueById(mid) : null;
      return (d && d.name) || mid;
    });
    if (!names.length) return 'no Mythic pool';
    return 'Mythics: ' + names.join(', ');
  } catch (e) {
    return '';
  }
}

// The styled hover-card for a Summon button (the gear-card look via hoverTip()).
// A Summon button is DISABLED when you can't yet forge the Effigy, so on desktop it
// shows the browser's not-allowed cursor with no hint why. This tip — raised by the
// .ench-tipwrap wrapper even over the disabled button — explains what summoning does
// and, when short, spells out exactly which shards / gold / chaos are still missing.
function egPinnacleSummonTip(bossName, recipe, wallet) {
  try {
    var w = wallet || {};
    var name = (typeof escapeHtml === 'function') ? escapeHtml(bossName || 'this god') : (bossName || 'this god');
    var html = '<div class="ht-name">Forge the Effigy</div>' +
      '<div class="ht-line">Spend the recipe below to forge a single-use Effigy and drag ' + name + ' into a bespoke arena.</div>';
    var missing = [];
    if (recipe && recipe.shards && recipe.shards.type) {
      var t = recipe.shards.type;
      var haveSh = (w.shards && w.shards[t]) || 0;
      var needSh = recipe.shards.count || 0;
      if (haveSh < needSh) {
        var short = needSh - haveSh;
        missing.push(short + ' ' + egShardLabel(t) + ' shard' + (short === 1 ? '' : 's'));
      }
    }
    if (recipe && recipe.gold && (w.gold || 0) < recipe.gold) {
      var goldShort = recipe.gold - (w.gold || 0);
      missing.push(((typeof fmtGold === 'function') ? fmtGold(goldShort) : goldShort) + ' gold');
    }
    if (recipe && recipe.chaos && (w.chaos || 0) < recipe.chaos) {
      missing.push((recipe.chaos - (w.chaos || 0)) + ' chaos');
    }
    if (missing.length) {
      html += '<div class="ht-sub" style="color:var(--danger)">Still need: ' + missing.join(', ') + '.</div>';
    } else {
      html += '<div class="ht-sub" style="color:var(--success)">You have enough to forge this now.</div>';
    }
    return html;
  } catch (e) {
    return 'Forge the Effigy to summon this god.';
  }
}

// ── PANTHEON MODAL ───────────────────────────────────────────────────────────

function openPantheon() {
  try {
    if (typeof openTownModal === 'function') openTownModal('Pantheon of the Deep', 'pin_altar');
    if (typeof setTownContent === 'function') setTownContent(renderPantheon());
  } catch (e) {
    try { log('The altar will not open.'); } catch (_e) {}
  }
}

function renderPantheon() {
  try {
    var wallet = egPinnacleWallet();
    var shardBag = (player && player.pinnacleShards) || {};
    var cleared = (player && player.pinnacleCleared) || {};
    var pity = (player && player.pinnaclePity) || {};
    var endlessDepth = egPinnacleEndlessDepth();

    // ── Shard wallet strip (top) ──
    var shardCells = '';
    try {
      if (typeof PANTHEON_SHARDS === 'object' && PANTHEON_SHARDS) {
        shardCells = Object.keys(PANTHEON_SHARDS).map(function (k) {
          var type = PANTHEON_SHARDS[k];
          var n = shardBag[type] || 0;
          return '<span class="cos-chip">' + dlIcon(egShardIcon(type), 16) + ' ' + egShardLabel(type) + ' <b>' + n + '</b></span>';
        }).join('');
      }
    } catch (_e) {}
    var wchaos = wallet.chaos || 0;
    var walletStrip =
      '<div class="town-blurb" style="margin-bottom:4px">Effigy shards you have banked:</div>' +
      '<div class="cos-chips" style="margin-bottom:10px">' + shardCells +
      '<span class="cos-chip">' + dlIcon('mat_chaos', 16) + ' Chaos <b>' + wchaos + '</b></span></div>';

    // ── Per-god summon cards ──
    var bosses = (typeof baseBosses === 'function') ? (baseBosses() || []) : [];
    var rows = bosses.map(function (boss) {
      var id = boss.id;
      var recipe = (typeof pinnacleSummonCost === 'function') ? pinnacleSummonCost(id) : null;
      var afford = (typeof pinnacleCanSummon === 'function') ? !!pinnacleCanSummon(recipe, wallet) : false;
      var clearedTag = cleared[id]
        ? '<span style="color:var(--success)">felled — now farmable</span>'
        : '<span style="color:var(--gold)">never cleared · first kill pays a bonus</span>';
      var pv = (typeof previewLootPool === 'function') ? (previewLootPool(id) || {}) : {};
      var thresh = pv.pityThreshold || 1;
      var pityLine = 'pity ' + (pity[id] || 0) + '/' + thresh;

      var stats =
        egPinnacleRecipeLine(recipe) + '<br>' +
        egPinnaclePoolLine(id) + '<br>' +
        clearedTag + ' &nbsp;·&nbsp; ' + pityLine;

      var card =
        '<div class="shop-row has-actions ' + (afford ? '' : 'cant-afford') + '">' +
          '<span class="loot-icon">' + dlIcon(boss.atlasKey || 'pin_boss', 40) + '</span>' +
          '<div class="shop-row-info">' +
            '<div class="shop-row-name">' + boss.name + '</div>' +
            '<div class="shop-row-stats">' + stats + '</div>' +
          '</div>' +
          '<span class="ench-tipwrap" ' + hoverTip(egPinnacleSummonTip(boss.name, recipe, wallet)) + '>' +
            '<button class="act-btn ' + (afford ? '' : 'short') + '" ' + (afford ? '' : 'disabled') +
            ' onclick="pantheonSummon(\'' + id + '\')">Summon</button></span>' +
        '</div>';

      // ── Uber staircase ──
      var uber = (typeof uberFor === 'function') ? uberFor(id) : null;
      if (uber) {
        var unlocked = (typeof uberUnlocked === 'function')
          ? !!uberUnlocked(uber, !!cleared[id], endlessDepth) : false;
        if (unlocked) {
          var urecipe = (typeof pinnacleSummonCost === 'function') ? pinnacleSummonCost(uber.id) : null;
          var uafford = (typeof pinnacleCanSummon === 'function') ? !!pinnacleCanSummon(urecipe, wallet) : false;
          var upv = (typeof previewLootPool === 'function') ? (previewLootPool(uber.id) || {}) : {};
          var upity = 'pity ' + (pity[uber.id] || 0) + '/' + (upv.pityThreshold || 1);
          card +=
            '<div class="shop-row has-actions ' + (uafford ? '' : 'cant-afford') + '" style="margin-left:16px">' +
              '<span class="loot-icon">' + dlIcon(uber.atlasKey || 'pin_boss', 36) + '</span>' +
              '<div class="shop-row-info">' +
                '<div class="shop-row-name">⇧ ' + uber.name + '</div>' +
                '<div class="shop-row-stats">' + egPinnacleRecipeLine(urecipe) + '<br>' +
                  egPinnaclePoolLine(uber.id) + '<br>' +
                  (cleared[uber.id] ? '<span style="color:var(--success)">felled</span>' : '<span style="color:var(--gold)">not yet cleared</span>') +
                  ' &nbsp;·&nbsp; ' + upity + '</div>' +
              '</div>' +
              '<span class="ench-tipwrap" ' + hoverTip(egPinnacleSummonTip(uber.name, urecipe, wallet)) + '>' +
                '<button class="act-btn ' + (uafford ? '' : 'short') + '" ' + (uafford ? '' : 'disabled') +
                ' onclick="pantheonSummon(\'' + uber.id + '\')">Summon</button></span>' +
            '</div>';
        } else {
          var need = Math.max(0, Math.floor(uber.uberMinEndlessDepth || 0));
          card +=
            '<div class="shop-row" style="margin-left:16px;opacity:0.72">' +
              '<span class="loot-icon">' + dlIcon('pin_locked', 36) + '</span>' +
              '<div class="shop-row-info">' +
                '<div class="shop-row-name">⇧ ' + uber.name + ' <span style="color:var(--danger)">(locked)</span></div>' +
                '<div class="shop-row-stats">Ascends once you have felled ' + boss.name +
                  ' and reached Endless depth ' + need + '.</div>' +
              '</div>' +
            '</div>';
        }
      }
      return card;
    }).join('');

    var clearedCount = 0;
    try { clearedCount = Object.keys(cleared).length; } catch (_e) {}
    var totalBosses = bosses.length;

    return (
      '<div class="town-blurb">Assemble a single-use Effigy from the shards deep foes leave behind, forge it at the Altar, and drag a god of the deep into a bespoke arena. Each is a multi-phase skill check that drops <b>Mythic</b> artifacts found nowhere else. Beat a god\'s base form and climb deep enough into Endless to summon its far deadlier Uber. Cleared ' + clearedCount + '/' + totalBosses + ' gods.</div>' +
      walletStrip +
      rows
    );
  } catch (e) {
    return '<div class="town-blurb">The Pantheon is silent.</div>';
  }
}

function pantheonSummon(bossId) {
  try {
    var recipe = (typeof pinnacleSummonCost === 'function') ? pinnacleSummonCost(bossId) : null;
    if (!recipe) { log('That god cannot be summoned.'); return; }
    if (!(typeof pinnacleCanSummon === 'function') || !pinnacleCanSummon(recipe, egPinnacleWallet())) {
      log('Not enough to summon.');
      return;
    }
    // Pay the Effigy cost.
    if (recipe.gold && typeof spendCost === 'function') spendCost({ gold: recipe.gold });
    if (recipe.chaos && typeof gainMaterial === 'function') gainMaterial('chaos', -recipe.chaos);
    if (recipe.shards && recipe.shards.type && player && player.pinnacleShards) {
      var t = recipe.shards.type;
      player.pinnacleShards[t] = Math.max(0, (player.pinnacleShards[t] || 0) - (recipe.shards.count || 0));
    }
    var bossDef = (typeof pinnacleBossById === 'function') ? pinnacleBossById(bossId) : null;
    egPinnacleEnterArena(bossDef);
    if (typeof closeTown === 'function') closeTown();
  } catch (e) {
    try { log('Summon failed'); } catch (_e) {}
  }
}

// ── ARENA / FIGHT ────────────────────────────────────────────────────────────

// Pick a real guardian `type` (with a live telegraphed moveset in BOSS_MOVESETS)
// to clone the fight AI from, chosen thematically per god-lineage.
function egPinnacleTemplateType(bossDef) {
  try {
    var base = (bossDef && (bossDef.uberOf || bossDef.id)) || '';
    var map = {
      thallor: 'tidewarden', nyxara: 'allseer', vorgrim: 'inferno',
      sylvaine: 'ratking', kaethon: 'cindra', umbriel: 'ourok',
    };
    return map[base] || 'inferno';
  } catch (e) {
    return 'inferno';
  }
}

// Drop the hero into a real dungeon floor and force-spawn the summoned god as a
// live, fully-telegraphed boss. Everything optional is guarded, so a missing
// internal API degrades to "marker only" rather than breaking boot.
function egPinnacleEnterArena(bossDef) {
  try {
    if (!bossDef) { log('The altar flickers — no god answers the call.'); return; }

    // 1 · Enter a real floor to fight on. Use the hero's deepest re-enterable depth,
    //     nudged off a boss floor (multiple of 5) so we neither trip the boss gate
    //     nor stack a floor guardian on top of our summoned god.
    var depth = Math.max(1, (player && player.maxFloor) || 1, (typeof dungeonLevel === 'number' ? dungeonLevel : 1) || 1);
    if (depth % 5 === 0) depth = Math.max(1, depth - 1);
    if (typeof enterDungeonAt === 'function') { try { enterDungeonAt(depth); } catch (_e) {} }

    // 2 · Force-spawn the god. Clone a real guardian's combat profile so the
    //     existing enemy AI drives a genuine, telegraphed boss fight.
    var e = null;
    if (typeof enemies !== 'undefined' && Array.isArray(enemies) &&
        typeof mapData !== 'undefined' && mapData && typeof MAP_W === 'number' && typeof MAP_H === 'number') {
      // Clean 1v1 arena: clear scattered mobs, minions and lingering hazards.
      enemies.length = 0;
      try { if (typeof minions !== 'undefined' && Array.isArray(minions)) minions.length = 0; } catch (_e) {}
      try { if (typeof bossHazards !== 'undefined' && Array.isArray(bossHazards)) bossHazards.length = 0; } catch (_e) {}
      try { if (typeof bossTelegraphs !== 'undefined' && Array.isArray(bossTelegraphs)) bossTelegraphs.length = 0; } catch (_e) {}

      var ttype = egPinnacleTemplateType(bossDef);
      var tmpl = null;
      try { if (typeof BOSSES !== 'undefined' && Array.isArray(BOSSES)) { tmpl = BOSSES.filter(function (b) { return b && b.type === ttype; })[0] || null; } } catch (_e) {}

      var size = (tmpl && tmpl.size) || 2;
      // Centre the god, keeping it off the hero's doorstep, then carve open arena.
      var cx = Math.floor(MAP_W / 2), cy = Math.floor(MAP_H / 2);
      var px = (player && player.x) || 5, py = (player && player.y) || 5;
      if (Math.abs(cx - px) + Math.abs(cy - py) < 7) { cx = MAP_W - 6; cy = MAP_H - 6; }
      cx = Math.max(2, Math.min(MAP_W - size - 2, cx));
      cy = Math.max(2, Math.min(MAP_H - size - 2, cy));
      try {
        var pad = 3;
        for (var ay = cy - pad; ay < cy + size + pad; ay++) {
          for (var ax = cx - pad; ax < cx + size + pad; ax++) {
            if (ax > 0 && ay > 0 && ax < MAP_W - 1 && ay < MAP_H - 1 && mapData[ay] && mapData[ay][ax] === 1) mapData[ay][ax] = 0;
          }
        }
        if (typeof bumpMapEpoch === 'function') bumpMapEpoch();
        if (typeof pathGridDirty === 'function') pathGridDirty();
      } catch (_e) {}

      // HP / damage on the same curve spawnEnemies uses for a guardian, then the
      // god's authored hp.mult on top.
      var bossLevel = (typeof dungeonLevel === 'number' ? dungeonLevel : 1) + 2;
      var baseHp, baseDmg;
      try {
        var threat = (typeof depthThreat === 'function') ? depthThreat(bossLevel) : 1;
        var bhm = (typeof bossHpMult === 'function') ? bossHpMult() : 1;
        var B = (typeof BALANCE === 'object' && BALANCE) ? BALANCE : {};
        baseHp = Math.round((50 + bossLevel * 23) * threat * (B.bossHpMult || 1) * (B.enemyHpMult || 1) * bhm);
        baseDmg = Math.round((9 + bossLevel * 2.1) * threat * (B.bossDmgMult || 1) * (B.enemyDmgMult || 1));
      } catch (_e) {}
      if (!(baseHp > 0)) baseHp = 500 + bossLevel * 120;
      if (!(baseDmg > 0)) baseDmg = 12 + bossLevel * 2;
      var mult = (bossDef.hp && typeof bossDef.hp.mult === 'number' && bossDef.hp.mult > 0) ? bossDef.hp.mult : 8;
      var finalHp = Math.max(1, Math.round(baseHp * mult));

      e = {
        x: cx, y: cy,
        hp: finalHp, maxHp: finalHp,
        type: (tmpl && tmpl.type) || ttype,
        name: bossDef.name || (tmpl && tmpl.name) || 'The Deep God',
        level: bossLevel,
        dmg: baseDmg,
        size: size,
        dead: false, isBoss: true,
        pinnacle: bossDef.id,
        statusChance: (tmpl && tmpl.ability === 'curse') ? 0.45 : 0.3,
        behavior: (tmpl && tmpl.behavior) || 'caster',
        bossAbility: (tmpl && tmpl.ability) || null,
        specials: (tmpl && tmpl.specials ? tmpl.specials.slice() : []),
        cd: 3, shieldT: 0,
        spawnT: Date.now(),
      };
      enemies.push(e);
      if (typeof bumpEnemyPos === 'function') bumpEnemyPos();
    }

    // 3 · Arm the pure phase state machine + start the fight clock.
    _egPinnacleBoss = e;
    _egPinnacleBossId = bossDef.id;
    _egPinnacleFight = (typeof pinnacleInitFight === 'function') ? pinnacleInitFight(bossDef) : null;
    _egPinnacleFightStartMs = Date.now();

    // 4 · Dramatic summon banner.
    try {
      log(dlIcon('pin_altar', 16) + ' <b>' + (bossDef.name || 'A god of the deep') + '</b> answers the Effigy and steps into the arena!', 'important');
      if (typeof sfx === 'function') sfx('bosskill');
      if (typeof screenFlash === 'function') screenFlash('#c87bff');
      if (typeof addShake === 'function') addShake(10);
    } catch (_e) {}

    try {
      if (typeof updateBars === 'function') updateBars();
      if (typeof draw === 'function') draw();
      if (typeof saveGameSoon === 'function') saveGameSoon();
    } catch (_e) {}
  } catch (err) {
    try { log('The summoning collapses.'); } catch (_e) {}
  }
}

// Called each worldTick: advance the phase overlay atop the live boss AI.
function egPinnacleTick() {
  try {
    if (!_egPinnacleFight) return;
    if (!_egPinnacleBoss || _egPinnacleBoss.dead) { _egPinnacleFight = null; _egPinnacleBoss = null; return; }

    var bossDef = (typeof pinnacleBossById === 'function') ? pinnacleBossById(_egPinnacleBossId) : null;
    var hpFrac = Math.max(0, _egPinnacleBoss.hp / (_egPinnacleBoss.maxHp || 1));
    var elapsedSec = (Date.now() - _egPinnacleFightStartMs) / 1000;
    if (typeof pinnacleStepFight !== 'function') return;

    var r = pinnacleStepFight(_egPinnacleFight, { hpFrac: hpFrac, elapsedSec: elapsedSec }, Math.random, bossDef);
    _egPinnacleFight = r.state;
    var events = (r && r.events) || [];
    for (var i = 0; i < events.length; i++) {
      var ev = events[i];
      try {
        if (ev.type === 'phase') {
          log('The ' + ((bossDef && bossDef.name) || 'guardian') + ' shifts — phase ' + (ev.phaseIndex != null ? (ev.phaseIndex + 1) : '') + (ev.phaseId ? ' (' + ev.phaseId + ')' : ''), 'important');
          if (typeof screenFlash === 'function') screenFlash('#c87bff');
          if (typeof addShake === 'function') addShake(5);
        } else if (ev.type === 'enrage') {
          _egPinnacleBoss.enraged = true;
          // A real DPS check: a modest permanent damage spike per phase-enrage.
          _egPinnacleBoss.dmg = Math.round((_egPinnacleBoss.dmg || 1) * 1.25);
          log('The ' + ((bossDef && bossDef.name) || 'guardian') + ' ENRAGES — its blows redouble!', 'important');
          if (typeof sfx === 'function') sfx('bosskill');
          if (typeof screenFlash === 'function') screenFlash('#ff3344');
        } else if (ev.type === 'addwave') {
          // Spawn ev.count adds near the god via the existing vermin-summon path.
          var n = Math.max(0, Math.floor(ev.count || 0));
          if (n > 0 && typeof spawnVerminAt === 'function' && typeof MAP_W === 'number') {
            var placed = 0;
            for (var d = 1; d <= 3 && placed < n; d++) {
              var ring = [[d, 0], [-d, 0], [0, d], [0, -d], [d, d], [-d, -d], [d, -d], [-d, d]];
              for (var k = 0; k < ring.length && placed < n; k++) {
                var sx = _egPinnacleBoss.x + ring[k][0], sy = _egPinnacleBoss.y + ring[k][1];
                try { if (spawnVerminAt(_egPinnacleBoss, sx, sy)) placed++; } catch (_e) {}
              }
            }
          }
        } else if (ev.type === 'telegraph') {
          // The cloned guardian moveset already lays down real, dodgeable telegraphs;
          // the pure overlay's telegraph events are advisory here — no-op to stay safe.
        }
      } catch (_e) {}
    }
  } catch (e) {
    // never let the overlay break the world tick
  }
}

// Called from onEnemyDefeated when e.pinnacle is set: roll the Mythic drop, pity,
// and first-clear rewards.
function egPinnacleOnBossKill(e) {
  try {
    var bossDef = (typeof pinnacleBossById === 'function') ? pinnacleBossById(e.pinnacle) : null;
    if (!bossDef) return;
    var pv = (typeof previewLootPool === 'function') ? (previewLootPool(bossDef.id) || {}) : {};
    var pool = pv.pool || [];
    if (!player.pinnaclePity) player.pinnaclePity = {};
    if (!player.pinnacleCleared) player.pinnacleCleared = {};
    if (!player.pinnacleShards) player.pinnacleShards = {};
    var pity = player.pinnaclePity[bossDef.id] || 0;

    var r = (typeof rollPinnacleDrop === 'function') ? rollPinnacleDrop(pool, pity, Math.random, bossDef) : null;
    if (r && r.itemId) {
      var def = (typeof pinnacleUniqueById === 'function') ? pinnacleUniqueById(r.itemId) : null;
      if (def && typeof buildUnique === 'function') {
        var lvl = Math.max((typeof dungeonLevel === 'number' ? dungeonLevel : 1), (player.maxFloor || 1));
        var it = buildUnique(def, lvl);
        if (it) {
          it.mythic = true;
          if (typeof acquireLoot === 'function') acquireLoot(it);
          log(dlIcon('mf_anvil', 16) + ' <b>Mythic:</b> ' + def.name + ' falls from the ' + (bossDef.name || 'god') + '!', 'loot');
          if (typeof sfx === 'function') sfx('loot');
          if (typeof screenFlash === 'function') screenFlash('#ff3344');
          if (typeof addShake === 'function') addShake(8);
        }
      }
    }
    if (typeof nextBossPity === 'function') {
      player.pinnaclePity[bossDef.id] = nextBossPity(pity, !!(r && r.itemId), bossDef);
    }

    if (!player.pinnacleCleared[bossDef.id]) {
      var fc = (typeof firstClearReward === 'function') ? firstClearReward(bossDef) : null;
      if (fc) {
        if (fc.gold) player.gold = (player.gold || 0) + fc.gold;
        if (fc.chaos && typeof gainMaterial === 'function') gainMaterial('chaos', fc.chaos);
        if (fc.shards && fc.shards.type) {
          player.pinnacleShards[fc.shards.type] = (player.pinnacleShards[fc.shards.type] || 0) + (fc.shards.count || 1);
        }
      }
      player.pinnacleCleared[bossDef.id] = 1;
      log('First clear of ' + (bossDef.name || 'the god') + '! The Deep remembers.', 'important');
      if (typeof sfx === 'function') sfx('levelup');
    }

    _egPinnacleFight = null;
    _egPinnacleBoss = null;
    if (typeof saveGameSoon === 'function') saveGameSoon();
  } catch (err) {
    // swallow — a botched reward must never break the kill flow
  }
}

// From a normal Endless boss kill, a small chance to drop one Effigy shard.
function egPinnacleShardDrop(endlessDepth) {
  try {
    if (typeof PANTHEON_SHARDS !== 'object' || !PANTHEON_SHARDS) return null;
    var types = Object.keys(PANTHEON_SHARDS).map(function (k) { return PANTHEON_SHARDS[k]; });
    if (!types.length) return null;
    if (Math.random() < 0.5) {
      var t = types[Math.floor(Math.random() * types.length)];
      if (!player.pinnacleShards) player.pinnacleShards = {};
      player.pinnacleShards[t] = (player.pinnacleShards[t] || 0) + 1;
      try { log(dlIcon(egShardIcon(t), 14) + ' An Effigy shard (' + egShardLabel(t) + ') glints among the spoils.', 'loot'); } catch (_e) {}
      return t;
    }
    return null;
  } catch (e) {
    return null;
  }
}

// Live-state block for gameState(): what the agent needs to fight a Pantheon god.
function egPinnacleGameStateBlock() {
  try {
    if (_egPinnacleFight) {
      var bd = (typeof pinnacleBossById === 'function') ? pinnacleBossById(_egPinnacleBossId) : null;
      var phase = null;
      try {
        var cp = (typeof pinnacleCurrentPhase === 'function') ? pinnacleCurrentPhase(_egPinnacleFight, bd) : null;
        phase = (cp && cp.id) || null;
      } catch (_e) {}
      var hpFrac = _egPinnacleBoss ? Math.round((_egPinnacleBoss.hp / (_egPinnacleBoss.maxHp || 1)) * 100) / 100 : 0;
      var teleg = [];
      try { if (typeof pinnaclePendingTelegraphs === 'function') teleg = pinnaclePendingTelegraphs(_egPinnacleFight); } catch (_e) {}
      return {
        active: true,
        boss: _egPinnacleBossId,
        bossName: (bd && bd.name) || null,
        phase: phase,
        enraged: !!(_egPinnacleBoss && _egPinnacleBoss.enraged),
        hpFrac: hpFrac,
        telegraphs: teleg,
      };
    }
    var clearedN = 0;
    try { clearedN = Object.keys((player && player.pinnacleCleared) || {}).length; } catch (_e) {}
    var total = (typeof baseBosses === 'function') ? (baseBosses() || []).length : 0;
    return {
      active: false,
      shards: (player && player.pinnacleShards) || {},
      cleared: clearedN,
      totalBosses: total,
    };
  } catch (e) {
    return { active: false, shards: {}, cleared: 0, totalBosses: 0 };
  }
}

// gameGuide() topic: how the Pantheon works, in plain player-facing terms.
function egPinnacleGuideTopic() {
  return [
    'PANTHEON OF THE DEEP: summon-on-demand capstone bosses that drop exclusive Mythic gear found nowhere else.',
    'Deep and Endless bosses sometimes drop an Effigy SHARD (six kinds, one per god-lineage). Bank them.',
    'At the Altar (Pantheon of the Deep), spend a fixed count of one shard type plus gold — and chaos for Ubers — to forge a single-use Effigy and summon that god.',
    'Summoning drops you into a bespoke arena for a multi-phase fight: the god shifts phase as you drain its HP, spawns adds in some phases, and soft-enrages if you are too slow (a DPS check). Dodge every telegraphed zone by MOVING out of it.',
    'Each god drops from a small pool of Mythic uniques with per-boss bad-luck protection (pity): every dry kill raises the counter, and at the threshold the next Mythic is GUARANTEED.',
    'The roster is a Base -> Uber staircase: six Base gods anyone can eventually summon, each with a deadlier Uber that unlocks only after you have felled its Base form AND reached a minimum Endless depth. Ubers cost more, hit harder, and drop a strictly better pool.',
    "A god's FIRST clear pays a one-time bonus (gold, shards, chaos) plus boss points; farming it afterward still drops Mythics but not the bonus.",
  ];
}

// ── CYCLES ──
// ══════════════════════════════════════════════════════════════════════════
// CYCLES — shell integration (seasonal ladder "Cycles & the Legacy Realm")
// Pasted verbatim into src/legacy/game.js; runs INSIDE game.js scope. Reads the
// pure-core cycle aliases (activeCycle / cycleJourneyProgress / resolveCycleModifier
// …) and wires them to the live hero, the town modal UI, and the AI-play API.
// Top-level function declarations only. Defensive: handler bodies try/catch + log;
// optional helpers guarded by typeof. `_egCycleCache` is pre-declared — never redeclare.
// ══════════════════════════════════════════════════════════════════════════

// Live cycle snapshot, recomputed only when the wall-clock MINUTE rolls over (the
// season windows change on the order of days, so a per-minute cache is plenty and
// keeps this off the hot path). Caches { min, res } on the pre-declared global.
function egCycleNow() {
  try {
    const min = Math.floor(Date.now() / 60000);
    if (_egCycleCache && _egCycleCache.min === min && _egCycleCache.res) return _egCycleCache.res;
    const res = activeCycle(Date.now());
    _egCycleCache = { min: min, res: res };
    return res;
  } catch (_e) {
    return { cycle: null, countdownMs: 0, phase: 'ended' };
  }
}

// The cycle that is LIVE right now, or null (pre-season / gap / ended).
function egCycleLive() {
  const n = egCycleNow();
  return (n && n.phase === 'live' && n.cycle) ? n.cycle : null;
}

// Is THIS hero enrolled in the live cycle? (tag must match the live season's id).
function egCycleEnrolled() {
  try {
    const c = egCycleLive();
    return !!(c && player && player.cycleId === c.id);
  } catch (_e) {
    return false;
  }
}

// The resolved headline-rule params for the live season IF this hero is enrolled;
// otherwise the neutral (no-change) shape so every call site can read a knob safely.
// MEMOIZED on (live cycle id | this hero's enrolment) because the knobs are read on
// hot paths — every kill's XP, every drop's tier, every foe's swing — and resolving
// allocated a fresh params object each call. egCycleLive() is itself cached per
// minute, so the signature check is a string compare; a season starting, ending, or
// the hero enrolling all change the signature and rebuild the bundle.
const EG_CYCLE_NEUTRAL = { lootTierShift: 0, bountyPayoutMult: 1, enemyAffix: null, densityMult: 1, xpMult: 1 };
let _egCycleModCache = null;
function egCycleMod() {
  try {
    const c = egCycleLive();
    const sig = (c ? c.id : '') + '|' + ((player && player.cycleId) || '');
    if (_egCycleModCache && _egCycleModCache.sig === sig) return _egCycleModCache.val;
    const val = (c && egCycleEnrolled()) ? resolveCycleModifier(c.headlineModifierId) : EG_CYCLE_NEUTRAL;
    _egCycleModCache = { sig: sig, val: val };
    return val;
  } catch (_e) { /* fall through to neutral */ }
  return EG_CYCLE_NEUTRAL;
}

// ── APPLY the headline rule at the shell's call sites ────────────────────────
// Each is a thin, no-throw wrapper: pass the base value, get the season-adjusted
// value (identity when not enrolled / no live cycle).
// The whole-tier nudge a season gives a DROP. The kill/chest loot roll walks per-tier
// chances rather than a weight array (see rollTier), so the season shifts the rolled
// RESULT instead — which is exactly what the rule promises ("+1 makes greens land
// where whites would"). 0 when un-enrolled / no live season.
function egCycleTierShift() {
  try { return egCycleMod().lootTierShift | 0; } catch (_e) { return 0; }
}
function egCycleDensity(count) {
  try { return applyDensityMult(count, egCycleMod().densityMult); } catch (_e) { return count; }
}
function egCyclePayout(gold) {
  try { return applyPayoutMult(gold, egCycleMod().bountyPayoutMult); } catch (_e) { return gold; }
}
function egCycleXp(xp) {
  try { return applyXpMult(xp, egCycleMod().xpMult); } catch (_e) { return xp; }
}
function egCycleEnemyAffix() {
  try { return egCycleMod().enemyAffix; } catch (_e) { return null; }
}
// ── The season affix, resolved at the three call sites that feel it ──────────
// A season affix is GLOBAL — every foe an enrolled hero meets carries it — so these
// read the cached bundle rather than stamping a field on each spawn.
function egSeasonAtkSpeed() {
  try { return seasonAtkSpeedMult(egCycleEnemyAffix()); } catch (_e) { return 1; }
}
function egSeasonArmorAdd() {
  try { return seasonArmorAdd(egCycleEnemyAffix()); } catch (_e) { return 0; }
}
// A foe's death burst: damage the hero if they are standing inside the blast. No-op
// unless the season's affix bursts. Non-lethal — like every other hazard in the game
// (lava, spikes, vents), it can hurt badly but never lands the killing blow.
function egSeasonDeathBurst(e) {
  try {
    const key = egCycleEnemyAffix();
    const radius = seasonBurstRadius(key);
    if (!radius || !e) return;
    const def = seasonAffixDef(key);
    spawnParticles(e.x, e.y, (def && def.color) || '#ffb04a', 14, 0.15);
    if (Math.max(Math.abs(e.x - player.x), Math.abs(e.y - player.y)) > radius) return;
    const dmg = seasonBurstDamage(key, e.dmg, player.maxHp);
    if (!dmg) return;
    const hpLost = takePlayerDamage(dmg, (def && def.name) || 'death burst', { lethal: false });
    if (hpLost > 0) {
      spawnFloatingText(player.x, player.y, `${hpLost}`, '#ff8a3a');
      log(`<span data-spr=ic_fire></span> The corpse bursts — ${clHurt(hpLost)} HP.`, 'important');
      screenFlash('#ff9040');
    }
  } catch (_e) { /* a season twist must never break a kill */ }
}

// Snapshot of this hero's live running totals in the shape cycleJourneyProgress reads.
// A fresh seasonal hero starts every counter at 0, so the live total IS the season delta.
function egCycleTotals() {
  try {
    return {
      kills: player.kills || 0,
      maxFloor: player.maxFloor || 1,
      clearedFloors: Object.keys(player.clearedFloors || {}).length,
      bossKills: player.bossKills || 0,
      eliteKills: player.eliteKills || 0,
      goldEarned: player.goldEarned || 0,
      journeyPoints: player.journeyPoints || 0
    };
  } catch (_e) {
    return { kills: 0, maxFloor: 1, clearedFloors: 0, bossKills: 0, eliteKills: 0, goldEarned: 0, journeyPoints: 0 };
  }
}

// Per-tick milestone check: grant any newly-completed Journey rewards exactly once
// (tracked in player.cycleRewardsClaimed). Rewards are kept small and mostly cosmetic —
// a milestone reward with a .gold or .mat field pays out; the rest is just the banner.
function egCycleTick() {
  try {
    if (!egCycleEnrolled()) return;
    const cyc = egCycleLive();
    if (!Array.isArray(player.cycleRewardsClaimed)) player.cycleRewardsClaimed = [];
    const prog = cycleJourneyProgress(egCycleTotals(), cyc);
    const earned = cycleRewardsEarned(prog, cyc);
    for (const e of earned) {
      if (!e || !e.id) continue;
      if (player.cycleRewardsClaimed.includes(e.id)) continue;
      player.cycleRewardsClaimed.push(e.id);
      if (e.reward && e.reward.gold) { player.gold = (player.gold || 0) + e.reward.gold; }
      if (e.reward && e.reward.mat && typeof gainMaterial === 'function') { gainMaterial(e.reward.mat, e.reward.qty || 1); }
      log(dlIcon('cycle_banner', 16) + ' Journey milestone complete!', 'important');
      if (typeof sfx === 'function') sfx('levelup');
      saveGameSoon();
    }
  } catch (_e) { /* never let a milestone check throw into the tick loop */ }
}

// ── TOWN MODAL: the Cycles board ─────────────────────────────────────────────
function openCycles() {
  try {
    openTownModal('Cycles', 'cycle_banner');
    setTownContent(renderCycles());
  } catch (_e) { /* modal open is best-effort */ }
}

// Build the Cycles board HTML (returned, not mounted). Shows the season banner +
// headline rule + human countdown; an Enroll button when a live season isn't joined;
// or the Journey checklist (with a completion badge) once enrolled.
function renderCycles() {
  try {
    const n = egCycleNow();
    const cyc = n.cycle;
    const abbr = (v) => (typeof abbreviateNumber === 'function') ? abbreviateNumber(v) : String(v);
    // Format a duration (ms) into a compact d/h/m string.
    const fmt = (ms) => {
      let s = Math.max(0, Math.floor((Number(ms) || 0) / 1000));
      const d = Math.floor(s / 86400); s -= d * 86400;
      const h = Math.floor(s / 3600); s -= h * 3600;
      const m = Math.floor(s / 60);
      if (d > 0) return d + 'd ' + h + 'h ' + m + 'm';
      if (h > 0) return h + 'h ' + m + 'm';
      return m + 'm';
    };

    let html = '<div class="town-blurb">Cycles are opt-in <b>seasons</b>: a fresh hero from level 1, racing a fixed <b>Journey</b> of milestones under one <b>headline rule</b> that changes how the run plays. The leaderboard is <b>snapshot &amp; reset</b> at season end, and when a season closes your seasonal hero forks into a permanent Legacy hero — nothing is lost. Enrolling tags <b>this</b> hero to the season.</div>';

    if (n.phase === 'live' && cyc) {
      const modRow = (Array.isArray(CYCLE_MODIFIERS) ? CYCLE_MODIFIERS : []).find(m => m && m.id === cyc.headlineModifierId) || null;
      const modName = modRow ? modRow.name : 'Open Cycle';
      const modDesc = modRow ? modRow.desc : 'No headline rule — the classic loop.';
      html += '<div class="shop-row"><div class="shop-row-info">'
        + '<div class="shop-row-name">' + dlIcon('cycle_banner', 18) + ' ' + escapeHtml(cyc.name) + '</div>'
        + '<div class="shop-row-stats"><b>Live now</b> · ends in ' + escapeHtml(fmt(n.countdownMs)) + '</div>'
        + '<div class="shop-row-stats"><b>Headline rule:</b> ' + escapeHtml(modName) + ' — ' + escapeHtml(modDesc) + '</div>'
        + '</div></div>';

      if (!egCycleEnrolled()) {
        html += '<div class="shop-row has-actions"><div class="shop-row-info">'
          + '<div class="shop-row-name">Join the season</div>'
          + '<div class="shop-row-stats">Tag this hero to ' + escapeHtml(cyc.name) + ' and start the Journey.</div>'
          + '</div><button class="act-btn" onclick="cycleEnrollUI()">Enroll this hero</button></div>';
      } else {
        const totals = egCycleTotals();
        const prog = cycleJourneyProgress(totals, cyc);
        if (cycleJourneyComplete(totals, cyc)) {
          html += '<div class="town-blurb" style="color:var(--success)"><b>&#10003; Journey complete!</b> Every milestone this season is done.</div>';
        }
        html += '<div class="town-blurb">Your Journey — progress since you enrolled:</div>';
        const nameById = {};
        (Array.isArray(cyc.journey) ? cyc.journey : []).forEach(s => { if (s && s.id) nameById[s.id] = s.name || s.id; });
        html += '<div class="shop-grid">';
        for (const p of prog) {
          if (!p) continue;
          const label = escapeHtml(nameById[p.id] || p.id || 'Milestone');
          const mark = p.done ? '<span style="color:var(--success)">&#10003;</span>' : '<span style="opacity:0.5">&bull;</span>';
          html += '<div class="shop-row"><div class="shop-row-info">'
            + '<div class="shop-row-name">' + mark + ' ' + label + '</div>'
            + '<div class="shop-row-stats">' + escapeHtml(abbr(p.have)) + ' / ' + escapeHtml(abbr(p.need)) + (p.done ? ' · <b style="color:var(--success)">done</b>' : '') + '</div>'
            + '</div></div>';
        }
        html += '</div>';
      }
    } else if (n.phase === 'pre') {
      const nm = cyc ? escapeHtml(cyc.name) : 'the next Cycle';
      html += '<div class="shop-row"><div class="shop-row-info">'
        + '<div class="shop-row-name">' + dlIcon('cycle_banner', 18) + ' Next: ' + nm + '</div>'
        + '<div class="shop-row-stats">No season is live right now. Opens in <b>' + escapeHtml(fmt(n.countdownMs)) + '</b>.</div>'
        + '</div></div>';
    } else {
      const nm = cyc ? escapeHtml(cyc.name) : null;
      html += '<div class="shop-row"><div class="shop-row-info">'
        + '<div class="shop-row-name">' + dlIcon('cycle_banner', 18) + ' Seasons concluded</div>'
        + '<div class="shop-row-stats">' + (nm ? 'The last season was ' + nm + '. ' : '') + 'No Cycle is live right now — check back when the next one opens.</div>'
        + '</div></div>';
    }
    return html;
  } catch (_e) {
    return '<div class="town-blurb">Cycles are unavailable right now.</div>';
  }
}

// Enroll this hero into the live cycle (from the board's Enroll button).
function cycleEnrollUI() {
  try {
    const c = egCycleLive();
    if (!c) { log('No live Cycle to join.'); if (typeof sfx === 'function') sfx('click'); return; }
    player.cycleId = c.id;
    if (!Array.isArray(player.cycleRewardsClaimed)) player.cycleRewardsClaimed = [];
    saveGameSoon();
    if (typeof sfx === 'function') sfx('levelup');
    log('Enrolled in the ' + escapeHtml(c.name) + ' Cycle.', 'important');
    setTownContent(renderCycles());
  } catch (_e) { /* enroll is best-effort */ }
}

// ── AI-PLAY API ──────────────────────────────────────────────────────────────
// Live snapshot block for gameState(): phase, season name, enrollment, countdown,
// and (when enrolled) the Journey progress rows.
function egCycleGameStateBlock() {
  try {
    const n = egCycleNow();
    const row = (n.cycle && Array.isArray(CYCLE_MODIFIERS))
      ? CYCLE_MODIFIERS.find(m => m && m.id === n.cycle.headlineModifierId) : null;
    // The headline RULE and the knobs it is actually applying. Reported so an agent
    // can see WHY its XP, drops, payouts and foes differ from a vanilla run — the
    // rule used to be advertised in the town panel and applied nowhere, so a live
    // readout of the applied values is also the regression guard.
    const mod = egCycleMod();
    return {
      phase: n.phase,
      cycleId: n.cycle ? n.cycle.id : null,
      cycle: n.cycle ? n.cycle.name : null,
      enrolled: egCycleEnrolled(),
      countdownMs: n.countdownMs,
      rule: row ? { id: row.id, name: row.name, desc: row.desc } : null,
      // Live effect on THIS hero: neutral (all no-change) unless they are enrolled.
      applied: {
        xpMult: mod.xpMult, bountyPayoutMult: mod.bountyPayoutMult,
        lootTierShift: mod.lootTierShift, densityMult: mod.densityMult,
        enemyAffix: mod.enemyAffix,
        enemyAffixName: mod.enemyAffix ? ((seasonAffixDef(mod.enemyAffix) || {}).name || null) : null,
      },
      journey: egCycleEnrolled() ? cycleJourneyProgress(egCycleTotals(), egCycleLive()) : null
    };
  } catch (_e) {
    return { phase: 'ended', cycleId: null, cycle: null, enrolled: false, countdownMs: 0, rule: null, applied: null, journey: null };
  }
}

// How-to reference lines for gameGuide()'s Cycles topic.
function egCycleGuideTopic() {
  return [
    'Cycles are opt-in seasonal ladders: an enrolled hero races the live season under a rotating headline rule that changes how the run plays (loot, spawns, XP, economy).',
    'The headline rule turns FIVE knobs, each applied to an enrolled hero only: xpMult on every XP grant, bountyPayoutMult on bounty gold, lootTierShift nudging every rolled drop that many rarity tiers (never past a colour you have not unlocked yet), densityMult on the per-floor spawn count, and enemyAffix — a season-wide modifier on EVERY foe. gameState().endgame.cycle.rule names the rule and .applied reports the live values, so you can read exactly what this run is being scaled by (all-neutral when un-enrolled).',
    'Season enemy affixes: FRENZIED foes swing 25% faster, ARMORED foes turn aside 8% more of every physical blow, and VOLATILE foes detonate when they die — stand more than ~1.6 tiles from a corpse or eat the blast (capped at 12% of your max HP and, like every hazard, never lethal).',
    'Each Cycle has a fixed milestone Journey; completing a milestone banks its reward. A fresh seasonal hero starts every counter at 0, so progress is just your live total.',
    'The leaderboard is snapshot-and-reset at season end — your standing is captured, then the board clears for the next Cycle.',
    'Enrolling tags THIS hero to the live season; when the season closes the hero forks into a permanent Legacy hero, so nothing is lost — only un-seasoned.'
  ];
}

// ── DEEDS ──
// ── THE HALL OF DEEDS — shell integration ────────────────────────────────────
// Account-wide, POWER-FREE renown honour roll. These are top-level declarations
// pasted verbatim into src/legacy/game.js: they run in game.js scope and call its
// globals + the imported pure-core aliases (deedSatisfied/deedProgress/evaluateDeeds/
// deedsByCategory, renownRank/unlockedRewards/renownNextReward, DEEDS/RENOWN_TRACK/
// TITLES/FRAMES/BADGES) directly. The orchestrator pre-declares `let hallDeeds`.
//
// Persistence mirrors the account-wide bestiary ledger (writeBestiaryDex /
// loadBestiaryDex / saveBestiaryDexSoon): one localStorage key, defensive parse,
// in-place mutation of the shared object. Renown NEVER grants a stat — deeds only
// unlock stash tabs, titles, frames and badges.

// Load the account-wide deeds ledger, folding stored fields over the default shape.
// Mutates the existing hallDeeds object IN PLACE (never reassigns) so every module
// that already captured the reference keeps seeing the live values.
function loadHallDeeds() {
  try {
    const raw = JSON.parse(localStorage.getItem('dungeonLoot_deeds_v1'));
    const def = { completed: [], renown: 0, title: null, frame: null, badge: null, claimed: [], classesPlayed: [], mirrored: 0, bountiesTotal: 0 };
    const m = Object.assign(def, raw && typeof raw === 'object' ? raw : {});
    m.completed = Array.isArray(m.completed) ? m.completed : [];
    m.claimed = Array.isArray(m.claimed) ? m.claimed : [];
    m.classesPlayed = Array.isArray(m.classesPlayed) ? m.classesPlayed : [];
    Object.assign(hallDeeds, m);
  } catch (_e) {}
}

// Persist the ledger. Cheap and change-agnostic; a corrupt localStorage never throws.
function writeHallDeeds() {
  try { localStorage.setItem('dungeonLoot_deeds_v1', JSON.stringify(hallDeeds)); } catch (_e) {}
}

// Deferred-save shim to parallel saveBestiaryDexSoon(). Module-level debounce state is
// not allowed in this pasted block, so this just writes now — the payload is tiny.

// ── Ledger bumps called from gameplay edges (breadth / mastery / bounty deeds) ──
function egHallAddClass(cls) {
  try {
    if (cls && !hallDeeds.classesPlayed.includes(cls)) { hallDeeds.classesPlayed.push(cls); writeHallDeeds(); }
  } catch (_e) {}
}
function egHallBumpMirror() {
  try { hallDeeds.mirrored = (hallDeeds.mirrored || 0) + 1; writeHallDeeds(); } catch (_e) {}
}
function egHallBumpBounty() {
  try { hallDeeds.bountiesTotal = (hallDeeds.bountiesTotal || 0) + 1; writeHallDeeds(); } catch (_e) {}
}

// Assemble the read-only account SNAPSHOT the pure deeds core evaluates against (see
// data/deeds.js for the contract). Reads the live Collection, Bestiary dex, hero
// records and the persisted ledger counters. Left un-caught on purpose: if a live
// system is momentarily unavailable and throws, egDeedsEvaluate()'s catch skips the
// write rather than persisting a zeroed snapshot that would drop earned deeds.
function egDeedsSnapshot() {
  const owned = acquiredKeySet(groupStoredArtifacts((stash && stash.items) || [], itemPower));
  const coll = collectionProgress(_COLL_CATALOG, owned);
  const roster = bestiaryRoster();
  const disc = roster.filter(s => speciesDiscovered(bestiaryKills(s))).length;
  return {
    collection: { have: coll.have, total: coll.total },
    bestiary: { discovered: disc, total: roster.length },
    diffCleared: player.diffCleared || 0,
    maxFloor: player.maxFloor || 1,
    endlessFloor: Math.max(0, (player.maxFloor || 1) - FINITE_DEPTH),
    bounties: { total: hallDeeds.bountiesTotal || 0, perClass: {} },
    classesPlayed: hallDeeds.classesPlayed || [],
    setsCompleted: 0,
    mirrored: hallDeeds.mirrored || 0,
  };
}

// Re-evaluate the whole catalog, persist the completed set + lifetime renown, announce
// anything newly earned (mirrors checkAchievements' banner style), then apply any
// newly-crossed renown rewards.
function egDeedsEvaluate() {
  try {
    const snap = egDeedsSnapshot();
    const r = evaluateDeeds(snap, hallDeeds.completed || []);
    hallDeeds.completed = r.completedIds;
    hallDeeds.renown = r.totalRenown;
    for (const id of (r.newlyCompleted || [])) {
      const d = DEEDS.find(x => x.id === id);
      log(dlIcon('deed_trophy', 16) + ' <b>Deed earned:</b> ' + escapeHtml(d ? d.name : id) + ' (+' + (d ? d.renown : 0) + ' Renown)', 'important');
      if (typeof sfx === 'function') sfx('deed');
    }
    egRenownApplyRewards();
    writeHallDeeds();
    return r;
  } catch (_e) { return null; }
}

// Claim every renown reward the lifetime total has unlocked, once each. Only stashTab
// touches the game (a pure storage QoL grant, guarded on the optional helper); titles,
// frames, badges and qol are inert — they surface in the wardrobe and grant NO power.
function egRenownApplyRewards() {
  try {
    for (const rw of unlockedRewards(hallDeeds.renown || 0)) {
      const key = (rw.type || '') + ':' + (rw.id || '');
      if (hallDeeds.claimed.includes(key)) continue;
      hallDeeds.claimed.push(key);
      if (rw.type === 'stashTab' && typeof addStashTab === 'function') { addStashTab(); }
      // title / frame / badge / qol: unlocked -> shown in the wardrobe; POWER-FREE, no stat effects.
    }
  } catch (_e) {}
}

// Open the Hall on the shared town overlay: mount, evaluate (so a just-earned deed
// lights up immediately), then paint.
function openDeeds() {
  try {
    openTownModal('Hall of Deeds', 'deed_trophy');
    egDeedsEvaluate();
    setTownContent(renderDeeds());
  } catch (_e) { try { log('Could not open the Hall of Deeds.', 'important'); } catch (_e2) {} }
}

// Build the Hall body: a renown/rank header with a progress bar + next-reward teaser,
// then one section per deed category (each tile shows DONE or a have/need meter with a
// source hint), then a power-free Wardrobe of unlocked titles/frames/badges. Reuses the
// canonical .town-blurb / .stash-section-title / .shop-grid / .shop-row / .act-btn /
// .bar-track+.bar-fill / .coll-head components.
function renderDeeds() {
  try {
    const snap = egDeedsSnapshot();
    const renown = hallDeeds.renown || 0;
    const rr = renownRank(renown);
    const completed = hallDeeds.completed || [];
    const rpct = Math.round(100 * (rr.pct || 0));
    const nextRw = renownNextReward(renown);
    const rwLabel = function (rw) {
      if (!rw) return 'the top of the ladder';
      if (rw.type === 'title') { const t = (TITLES || []).find(x => x.id === rw.id); return 'the title &ldquo;' + escapeHtml(t ? t.text : rw.id) + '&rdquo;'; }
      if (rw.type === 'frame') return 'a portrait frame';
      if (rw.type === 'badge') return 'a profile badge';
      if (rw.type === 'stashTab') return 'an extra stash tab';
      if (rw.type === 'qol') return 'a quality-of-life unlock';
      return 'a reward';
    };
    const catName = { collection: 'Collection', bestiary: 'Bestiary', conquest: 'Conquest', depth: 'Depth', bounty: 'Bounties', breadth: 'Class Breadth', mastery: 'Mastery' };

    let html = '';
    html += '<div class="town-blurb">The Hall of Deeds is your account-wide honour roll &mdash; every hero you play feeds the same tally. Renown is a <b>power-free</b> status ladder: it unlocks stash tabs, titles, frames and badges, <b>never</b> a stat.</div>';
    html += '<div class="coll-head"><div class="coll-prog">Renown <b>' + renown + '</b> &middot; Rank <b>' + (rr.rank || 0) + '</b></div><div class="coll-prog">Deeds <b>' + completed.length + '</b> / ' + DEEDS.length + '</div></div>';
    html += '<div class="bar-track" style="margin:2px 0 4px"><div class="bar-fill" style="width:' + rpct + '%;background:var(--gold)"></div></div>';
    if (rr.nextThreshold == null) {
      html += '<div class="shop-row-stats" style="margin-bottom:10px">Maxed &mdash; every renown rank unlocked.</div>';
    } else {
      html += '<div class="shop-row-stats" style="margin-bottom:10px">' + (rr.into || 0) + ' / ' + (rr.span || 0) + ' renown to Rank ' + ((rr.rank || 0) + 1) + ' &mdash; next reward: ' + rwLabel(nextRw) + '.</div>';
    }

    // Deed sections — order comes straight from deedsByCategory() (data-driven).
    for (const sec of deedsByCategory()) {
      html += '<div class="stash-section-title">' + escapeHtml(catName[sec.category] || sec.category) + '</div>';
      html += '<div class="shop-grid">';
      for (const deed of sec.deeds) {
        const done = completed.includes(deed.id);
        const p = deedProgress(deed, snap);
        const pc = Math.round(100 * (p.pct || 0));
        let meter;
        if (done) {
          meter = '<div class="shop-row-stats" style="color:var(--uncommon)">&#10003; Earned &middot; +' + deed.renown + ' Renown</div>';
        } else {
          meter = '<div class="shop-row-stats">' + p.have + ' / ' + p.need + ' &middot; +' + deed.renown + ' Renown</div>'
            + '<div class="bar-track" style="margin:4px 0 0"><div class="bar-fill" style="width:' + pc + '%;background:var(--gold)"></div></div>';
        }
        html += '<div class="shop-row has-actions no-icon' + (done ? ' upgrade' : '') + '">'
          + '<div class="shop-row-info">'
          + '<div class="shop-row-name">' + dlIcon(deed.sprite, 18) + ' ' + escapeHtml(deed.name) + '</div>'
          + '<div class="shop-row-sub">' + escapeHtml(deed.desc) + '</div>'
          + meter
          + '</div></div>';
      }
      html += '</div>';
    }

    // Wardrobe — the power-free cosmetics the renown ladder has handed out so far.
    const unlocked = unlockedRewards(renown) || [];
    const titles = unlocked.filter(r => r && r.type === 'title');
    const frames = unlocked.filter(r => r && r.type === 'frame');
    const badges = unlocked.filter(r => r && r.type === 'badge');
    html += '<div class="stash-section-title">Wardrobe &middot; power-free cosmetics</div>';
    html += '<div class="town-blurb" style="opacity:.85">Only how your name and portrait read on the roster &mdash; earned from renown, changing no stat.</div>';
    html += '<div class="shop-grid">';
    if (!titles.length && !frames.length && !badges.length) {
      html += '<div class="coll-empty">Earn renown to unlock titles, frames and badges.</div>';
    }
    for (const rw of titles) {
      const t = (TITLES || []).find(x => x.id === rw.id);
      const worn = hallDeeds.title === rw.id;
      html += '<div class="shop-row has-actions no-icon">'
        + '<div class="shop-row-info"><div class="shop-row-name">' + escapeHtml(t ? t.text : rw.id) + '</div><div class="shop-row-stats">Title</div></div>'
        + '<button class="act-btn" ' + (worn ? 'disabled' : '') + ' onclick="deedEquipTitle(\'' + rw.id + '\')">' + (worn ? 'WORN' : 'WEAR') + '</button>'
        + '</div>';
    }
    for (const rw of frames) {
      const f = (FRAMES || []).find(x => x.id === rw.id);
      const worn = hallDeeds.frame === rw.id;
      html += '<div class="shop-row has-actions">'
        + '<span class="loot-icon">' + dlIcon(f ? f.sprite : 'q_relic', 20) + '</span>'
        + '<div class="shop-row-info"><div class="shop-row-name">Portrait Frame</div><div class="shop-row-stats">Frame</div></div>'
        + '<button class="act-btn" ' + (worn ? 'disabled' : '') + ' onclick="deedEquipFrame(\'' + rw.id + '\')">' + (worn ? 'WORN' : 'USE') + '</button>'
        + '</div>';
    }
    for (const rw of badges) {
      const b = (BADGES || []).find(x => x.id === rw.id);
      html += '<div class="shop-row has-actions">'
        + '<span class="loot-icon">' + dlIcon(b ? b.sprite : 'q_relic', 20) + '</span>'
        + '<div class="shop-row-info"><div class="shop-row-name">Profile Badge</div><div class="shop-row-stats">Badge &middot; always shown</div></div>'
        + '</div>';
    }
    html += '</div>';
    return html;
  } catch (_e) {
    try { log('Hall of Deeds failed to render.', 'important'); } catch (_e2) {}
    return '<div class="town-blurb">The Hall of Deeds is momentarily unavailable.</div>';
  }
}

// Wear an unlocked title (pure cosmetic) and repaint.
function deedEquipTitle(id) {
  try {
    hallDeeds.title = id;
    writeHallDeeds();
    if (typeof sfx === 'function') sfx('click');
    setTownContent(renderDeeds());
  } catch (_e) {}
}
// Wear an unlocked portrait frame (pure cosmetic) and repaint.
function deedEquipFrame(id) {
  try {
    hallDeeds.frame = id;
    writeHallDeeds();
    if (typeof sfx === 'function') sfx('click');
    setTownContent(renderDeeds());
  } catch (_e) {}
}

// Compact live block for gameState().menu.deeds — rank, lifetime renown, completed /
// total, and the worn title (all account-wide, all power-free).
function egDeedsGameStateBlock() {
  try {
    return { rank: renownRank(hallDeeds.renown || 0).rank, renown: hallDeeds.renown || 0, completed: (hallDeeds.completed || []).length, total: DEEDS.length, title: hallDeeds.title || null };
  } catch (_e) {
    return { rank: 0, renown: 0, completed: 0, total: (DEEDS && DEEDS.length) || 0, title: null };
  }
}

// The gameGuide() how-to text for the Hall — plain, self-contained lines.
function egDeedsGuideTopic() {
  return [
    'The Hall of Deeds (in town) is an account-wide honour roll shared by every hero. Renown is a POWER-FREE status ladder — completing deeds never grants a stat.',
    'Deeds are permanent milestones across seven tracks: Collection (distinct uniques/sets stored), Bestiary (species discovered), Conquest (difficulties cleared), Depth (deepest floor plus a separate Endless ladder), Bounties (lifetime contracts completed), Class Breadth (distinct classes levelled), and Mastery (items forged in the Mirrorforge).',
    'Each completed deed adds its Renown to a lifetime total that never resets. Crossing a renown rank threshold unlocks that rank\'s reward.',
    'Rewards are cosmetic or quality-of-life only — extra stash tabs, wearable titles, portrait frames, profile badges, and QoL unlocks. Chasing deeds never gates power behind grind.',
    'Equip an unlocked title or frame from the Wardrobe at the bottom of the Hall. gameState().menu.deeds reports your rank, lifetime renown, deeds completed, and worn title.',
  ];
}

